) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = '文化表';

ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `cover_image` = VALUES(`cover_image`), `summary` = VALUES(`summary`), `content` = VALUES(`content`), `website` = VALUES(`website`), `related_scenic` = VALUES(`related_scenic`), `related_person` = VALUES(`related_person`), `video_url` = VALUES(`video_url`), `tags` = VALUES(`tags`);

