-- ----------------------------------------------------------------------------
-- 景点人气补全（幂等）：为 view_count=0 的景点生成演示浏览量
--     背景：Excel 导入的景点未带 view_count，导致大屏「游客数」近似为 0。
--     仅对 view_count=0 的行赋值，重复执行安全；如需恢复真实值，重导入景点数据即可。
-- ----------------------------------------------------------------------------
UPDATE `scenic_spot`
SET `view_count` = 1200 + (`id` * 173) % 4800
WHERE `deleted` = 0 AND `view_count` = 0;
