INSERT INTO `scenic_spot` (`id`, `name`, `city_id`, `type`, `level`, `address`, `website`, `longitude`, `latitude`, `cover_image`, `description`, `open_time`, `ticket_info`, `score`, `tags`, `recommend_reason`) VALUES
(1, '都江堰', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', '5A', '四川省成都市都江堰市公园路', 'https://baike.baidu.com/item/%E9%83%BD%E6%B1%9F%E5%A0%B0/122963', 103.616295, 30.993937, '/images/scenic/dujiangyan/dujiangyan_cover.jpg', '都江堰是战国时期秦国蜀郡太守李冰父子主持修建的大型无坝引水水利工程，距今两千多年仍在灌溉成都平原，被誉为“世界活的水利博物馆”。工程由鱼嘴分水堤、飞沙堰溢洪道、宝瓶口引水口三大主体构成，另有二王庙、安澜索桥、离堆公园等古迹。2000年与青城山共同列入世界文化遗产名录，是感受中国古代治水智慧的必访之地。', '08:00-18:00', '80元', 4.7, '世界遗产,水利工程,研学,古迹', '两千年不废的古堰，天府之国的生命之源'),
(2, '青城山', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', '5A', '四川省成都市都江堰市青城山镇', 'https://baike.baidu.com/item/%e9%9d%92%e5%9f%8e%e5%b1%b1/1512', 103.559815, 30.907891, '/images/scenic/qingchengshan/qingchengshan_cover.jpg', '青城山是中国道教发祥地之一，以“青城天下幽”闻名，与剑门之险、峨眉之秀、夔门之雄齐名。全山林木苍翠、四季常青，诸峰环峙如城郭。前山以建福宫、天师洞、上清宫等古观为主，宫观众多、文物荟萃；后山则原始幽深、飞瀑流泉，宛如世外桃源。2000年与都江堰共同列入世界文化遗产名录，是修身养性、登山访古的胜地。', '08:00-18:00', '前山80元，后山20元', 4.6, '世界遗产,道教,山林,避暑', '青城天下幽，道教发祥地'),
(3, '成都大熊猫繁育研究基地', (SELECT `id` FROM `city` WHERE `name` = '成都'), '亲子', '4A', '四川省成都市成华区熊猫大道1375号', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E5%A4%A7%E7%86%8A%E7%8C%AB%E7%B9%81%E8%82%B2%E7%A0%94%E7%A9%B6%E5%9F%BA%E5%9C%B0?fromModule=lemma_search-box', 104.135457, 30.740846, '/images/scenic/chengdudaxiongmaofanyuyanjiujidi/chengdudaxiongmaofanyuyanjiujidi_cover.jpg', '成都大熊猫繁育研究基地（Chengdu Research Base of Giant Panda Breeding），位于四川省成都市成华区熊猫大道1375号，距市中心10千米，距成都双流国际机场30余公里。基地总面积3570亩，其中扩建区面积为2535亩。世界著名的大熊猫迁地保护基地、科研繁育基地、公众教育基地和教育旅游基地。基地占地面积1000亩。成都大熊猫繁育研究基地在成都动物园饲养、救治、...', '07:30-18:00', '55元', 4.8, '大熊猫,亲子,科普,动物园', '看国宝熊猫的第一选择'),
(4, '成都武侯祠博物馆', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', '4A', '四川省成都市武侯区武侯祠大街231号', 'https://www.wuhouci.net.cn/', 104.048115, 30.645379, '/images/scenic/chengduwuhoucibowuguan/chengduwuhoucibowuguan_cover.jpg', '武侯祠（Wuhou Shrine），位于四川省成都市武侯区武侯祠大街231号，是纪念刘备、诸葛亮等蜀汉英雄人物的祠庙所在。它是以刘备陵寝所在地（惠陵）为基础发展而来的。南齐高帝萧道成（479-482年在位）诏令刺史傅琰修立先主祠，位置在惠陵东，应是今汉昭烈庙的前身。惠陵旁纪念诸葛亮的专祠——武侯祠大约建于南北朝时期。明洪武二十四年（1391年），明蜀献王朱椿主张“君臣宜一体”，废弃惠陵旁的武侯祠，...', '08:00-18:00', '50元', 4.6, '三国文化,博物馆,古迹,历史', '三国圣地，锦官城外柏森森'),
(5, '成都杜甫草堂博物馆', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', '4A', '四川省成都市青羊区青华路37号', 'https://www.cddfct.cn/go-c11.htm', 104.027013, 30.661367, '/images/scenic/chengdudufucaotangbowuguan/chengdudufucaotangbowuguan_cover.jpg', '杜甫草堂，是中国唐代大诗人杜甫流寓成都时的故居，位于四川省成都市青羊区青华路37号。杜甫先后在此居住近四年，创作诗歌240余首。唐末诗人韦庄寻得草堂遗址，重结茅屋，使之得以保存，宋元明清历代都有修葺扩建。杜甫草堂占地面积近300亩，仍完整保留着明弘治十三年（1500年）和清嘉庆十六年（1811年）修葺扩建时的建筑格局，照壁、正门、大廨、诗史堂、柴门、工部祠排列在一条中轴线上，两旁配以对称的回廊与其...', '08:00-18:30', '50元', 4.6, '诗圣,园林,博物馆,文化', '走进诗圣旧居，感受唐诗意境'),
(6, '金沙遗址博物馆', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', '4A', '四川省成都市青羊区金沙遗址路2号', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E9%87%91%E6%B2%99%E9%81%97%E5%9D%80%E5%8D%9A%E7%89%A9%E9%A6%86/7432729', 104.012666, 30.681607, '/images/scenic/jinshayizhibowuguan/jinshayizhibowuguan_cover.jpg', '成都金沙遗址博物馆（Jinsha Site Museum），位于四川省成都市青羊区金沙遗址路2号，成立于2007年4月，占地面积30万平方米，总建筑面积约40000平方米，是一座为保护、研究、展示金沙文化和古蜀文明而兴建的考古博物馆、国家一级博物馆。2001年2月，金沙遗址在成都市区被发现，2007年4月16日，成都金沙遗址博物馆正式开馆。金沙遗址博物馆分为遗迹馆和陈列馆两部分，其中遗迹馆是中国迄...', '08:00-18:00（周一闭馆）', '70元', 4.7, '古蜀文明,博物馆,遗址,文物', '太阳神鸟故里，触摸古蜀王都'),
(7, '宽窄巷子', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', NULL, '四川省成都市青羊区同仁路', 'https://baike.baidu.com/item/%E5%AE%BD%E7%AA%84%E5%B7%B7%E5%AD%90/546674', 104.050384, 30.665323, '/images/scenic/kuanzhaixiangzi/kuanzhaixiangzi_cover.jpg', '宽窄巷子，位于四川省成都市青羊区少城片区蜀都大道西段。宽窄巷子曾是年羹尧修筑的满城，2003年，成都市宽窄巷子历史文化片区主体改造工程确立，2008年6月14日，宽窄巷子开街。宽窄巷子由宽巷子、窄巷子和井巷子三条老式街道及其之间的四合院群落组成，包含约70座传统四合院院落，占地约32公顷。文化休闲特色街区规划控制面积479亩，其中核心保护区108亩。宽窄巷子北以支矶石街与宽巷子中间划线并纳入成都画院北墙为界，南以井巷子为界，东以长顺上街与宽窄巷东街口为界，西以下同仁路与宽窄巷子西街口为界。2020年7月，宽窄巷子步行街被中华人民共和国商务部公布为首批全国示范步行街名单。2022年1月10日，宽...', '全天开放', '免费', 4.5, '老街,市井,美食,文创', '最成都的慢生活街区'),
(8, '锦里古街', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', NULL, '四川省成都市武侯区武侯祠大街231号', 'https://baike.baidu.com/item/%E9%94%A6%E9%87%8C?fromtitle=%E9%94%A6%E9%87%8C%E5%8F%A4%E8%A1%97&fromid=3653788&fromModule=lemma_search-box', 104.049975, 30.646344, '/images/scenic/jinligujie/jinligujie_cover.jpg', '锦里作为成都武侯祠博物馆【三国历史遗迹区、锦里民俗区、西区（三国文化体验区）】的一部分，位于四川省成都市武侯区武侯祠大街231号附1号，地处成都市中心一环路以内，武侯祠大街中段，北邻锦江，东望彩虹桥，与较为出名的武侯祠仅一墙之隔，西接一环路西一段。占地30000余平方米，建筑面积14000余平方米，街道全长550米，建筑以清末民初四川民居风格为基础，内容以三国文化和四川传统民俗文化为内涵。2004年10月，锦里正式对外开放；2009年1月，锦里延伸段开肆迎客。成都文化名片之一的锦里古街完成升级，“拜武侯、泡锦里”已成为成都旅游较有号召力的响亮口号之一。锦里主要景点有：锦里古街、古戏台、九品小吃...', '全天开放', '免费', 4.5, '古街,小吃,民俗,夜景', '三国民俗街，夜景尤美'),
(9, '文殊院', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', NULL, '四川省成都市青羊区文殊院街66号', 'https://baike.baidu.com/item/%E6%96%87%E6%AE%8A%E9%99%A2?fromModule=lemma_search-box', 104.072722, 30.675494, '/images/scenic/wenshuyuan/wenshuyuan_cover.jpg', '文殊院，又名“空林堂”，位于四川省成都市青羊区文殊院街66号，占地面积20余万余平方米。文殊院始建于隋大业年间（605~617年）。康熙三十六年（1697年）集资重建庙宇，改称文殊院。文殊院是成都市内保存最为完整的佛教寺庙，坐北朝南，建筑为典型川西平原古建风格，主要为木构建筑。殿宇六重，进山门往里走依次是天王殿、三大士殿、大雄宝殿、说法堂、藏经楼。与东西两侧的钟楼、斋堂、廊房等建筑浑然一体，为典型的清代建筑。文殊院建筑以中轴线为主导，建筑风格主要为重檐歇山式、单檐悬山式等，皆呈内向型布局。建筑的布局按照严格的层次和等级区别，体现礼制的制约。文殊院是集禅林圣迹、园林古建、朝拜观光、宗教修学于一体...', '08:00-17:00', '免费', 4.6, '佛教,寺院,禅意,素斋', '闹市中的千年禅林'),
(10, '西岭雪山', (SELECT `id` FROM `city` WHERE `name` = '成都'), '自然', '4A', '四川省成都市大邑县西岭镇', 'https://baike.baidu.com/item/%E8%A5%BF%E5%B2%AD%E9%9B%AA%E5%B1%B1?fromModule=lemma_search-box', 103.188810, 30.698604, '/images/scenic/xilingxueshan/xilingxueshan_cover.jpg', '西岭雪山（Xiling snow mountain），位于四川省成都市大邑县境内，地理坐标为东经102°35′—103°17′，北纬30°35′—30°39′，景区总面积483平方千米。西岭雪山位于西部邛崃山脉的中段、地质构造复杂地段，海拔从1260—5364米不等。景区内最高峰大雪塘海拔5364米，终年积雪不化，为成都第一峰。西岭雪山属四川盆地亚热带湿润季风气候，属立体气温带，年平均气温13.2...', '09:00-16:00', '门票120元，索道另计', 4.5, '雪山,滑雪,云海,大熊猫栖息地', '窗含西岭千秋雪，成都第一峰'),
(11, '安仁古镇', (SELECT `id` FROM `city` WHERE `name` = '成都'), '古镇', '5A', '四川省成都市大邑县安仁镇金桂街15号', 'https://baike.baidu.com/item/%E5%AE%89%E4%BB%81%E5%8F%A4%E9%95%87/861037', 103.619215, 30.508660, '/images/scenic/anrenguzhen/anrenguzhen_cover.jpg', '安仁古镇，位于四川省成都市大邑县，规划面积4.1平方千米，规划边界为西至刘湘骑马像、东至会展路、北至绕镇路、南至斜江河，核心景区面积3平方千米，包含公馆老街、刘氏庄园博物馆、建川博物馆三大核心资源。 安仁古镇距成都市区39千米，双流国际机场36千米，成雅高铁大邑站10千米，成温邛高速大邑南出口8千米，大邑县城8.5千米。安仁古镇历史悠久，已有1400余年的历史。早在唐武德三年（620年）就建安仁县...', '古镇全天', '古镇免费', 4.5, '博物馆小镇,民国公馆,古镇,红色', '民国公馆+博物馆群'),
(12, '黄龙溪古镇', (SELECT `id` FROM `city` WHERE `name` = '成都'), '古镇', '4A', '四川省成都市双流区黄龙溪镇', 'https://baike.baidu.com/item/%E9%BB%84%E9%BE%99%E6%BA%AA%E5%8F%A4%E9%95%87?fromModule=lemma_search-box', 103.970958, 30.317593, '/images/scenic/huanglongxiguzhen/huanglongxiguzhen_cover.jpg', '黄龙溪古镇，古称赤水，地处四川省成都市双流区西南，总面积50.4平方千米。黄龙溪古镇核心区由一湖两河三寺七街九巷组成，有保存完好的民居七十六座，大院三座；有金华庵、三县衙门和古戏台等重点文物保护单位；有火龙、府河船工号子、漂河灯、打更等民间风俗文化。镇内尚保存有传统建筑面积共3.12万平方米，其中较具保护价值，特征鲜明，结构良好的清代穿逗式木结构传统建筑1.37万平方米。黄龙溪古镇有保存完好的明、...', '全天开放', '免费', 4.4, '古镇,水乡,玩水,民俗', '千年水码头，夏日戏水好去处'),
(13, '街子古镇', (SELECT `id` FROM `city` WHERE `name` = '成都'), '古镇', '4A', '四川省成都市崇州市街子镇', 'https://baike.baidu.com/item/%E8%A1%97%E5%AD%90%E5%8F%A4%E9%95%87?fromModule=lemma_search-box', 103.558647, 30.814506, '/images/scenic/jieziguzhen/jieziguzhen_cover.jpg', '街子古镇，位于四川省成都市崇州市西北群山之麓，东北毗邻都江堰，北临青城后山，西北毗邻九龙沟，距成都市57千米，距双流国际机场45千米，可在1小时内联通成都市区及双流国际机场。面积41.18平方千米，与青城山连为一体，其凤栖山为青城山三十六峰之一。街子古镇有“川西水乡”之名，“青城后花园”之称，街子镇建制已有1000余年历史，五代时称“横渠镇”“四界镇”“永康县”。镇域内川西特有的农耕文化、距今约4...', '全天开放', '免费', 4.4, '古镇,水乡,茶文化,休闲', '青城山麓的川西水乡古镇'),
(14, '平乐古镇', (SELECT `id` FROM `city` WHERE `name` = '成都'), '古镇', '4A', '四川省成都市邛崃市平乐镇', 'https://baike.baidu.com/item/%E5%B9%B3%E4%B9%90%E5%8F%A4%E9%95%87/483565', 103.336152, 30.345269, '/images/scenic/pingleguzhen/pingleguzhen_cover.jpg', '平乐古镇，位于四川省成都市邛崃市平乐镇，是中国历史文化名镇、国家4A级旅游景区、全国重点镇及全国环境优美乡镇。其古称“平落”，是南方丝绸之路西出成都的第一站和茶马古道上的重要水陆码头，历史可追溯至秦汉。古镇依白沫江而建，素有“川西水乡”之称，以古街、古寺、古桥等“九古”风华和保存完好的明清古建筑群为特色，其中乐善桥是川西地区现存最长的清代古石桥。如今，古镇举办“平乐中国年”等文旅活动，展现川剧变脸...', '全天开放', '免费', 4.4, '古镇,水乡,茶马古道,休闲', '秦汉古镇，白沫江畔慢时光'),
(15, '洛带古镇', (SELECT `id` FROM `city` WHERE `name` = '成都'), '古镇', '4A', '四川省成都市龙泉驿区洛带镇', 'https://baike.baidu.com/item/%E6%B4%9B%E5%B8%A6%E5%8F%A4%E9%95%87/67973593', 104.328462, 30.636649, '/images/scenic/luodaiguzhen/luodaiguzhen_cover.jpg', '洛带镇，隶属于四川省成都市龙泉驿区，位于成都市东郊，面积42.65平方千米，户籍人口29408人（2018年），下辖6个村、4个社区（2019年）。洛带镇是西部客家第一镇，常住客家人口达95%以上。客家文化是洛带的独特印记，是洛带古镇的灵魂与根基，为洛带经济发展起着牵引带动、核心支撑作用。洛带镇是成都中法生态园、中德产业园的国际文化交流板块，龙泉文化产业核心发展区。洛带镇西距成都市区18千米，南距...', '全天开放', '免费', 4.4, '古镇,客家文化,会馆,小吃', '西部客家第一镇'),
(16, '五凤溪古镇', (SELECT `id` FROM `city` WHERE `name` = '成都'), '古镇', '4A', '四川省成都市金堂县五凤镇', 'https://baike.baidu.com/item/%E4%BA%94%E5%87%A4%E6%BA%AA%E5%8F%A4%E9%95%87/4908326', 104.482451, 30.606970, '/images/scenic/wufengxiguzhen/wufengxiguzhen_cover.jpg', '五凤溪古镇，位于四川省金堂县城南38千米处，地处龙泉山脉中段东麓，旁依倚龙泉山，沿沱江两岸分布。该镇始于汉，兴于唐宋，清置场镇，素有“半边山江半边城”之称，自汉唐时期就是成都较为重要的水陆码头，是成都十大古镇中唯一的山地古镇。五凤溪古镇有金凤街、青凤街、小凤街、白凤街和玉凤街五条以“凤”命名的街道，依照山势沿河道而建，与龙泉山脉和黄水河共同构成了古镇三面临山、一面临水的地理格局。古镇因移民而兴，是...', '全天开放', '免费', 4.2, '古镇,移民文化,码头,会馆', '沱江边的山地水乡古镇'),
(17, '天台山', (SELECT `id` FROM `city` WHERE `name` = '成都'), '自然', '5A', '四川省成都市邛崃市天台山镇', 'https://baike.baidu.com/item/%E4%BA%94%E5%8F%B0%E5%B1%B1/2678', 105.493449, 28.018697, '/images/scenic/tiantaishan/tiantaishan_cover.jpg', '台州市天台山景区，位于浙江省台州市天台县和合街1号，地处宁波、绍兴、金华、温州四市的交界地带，西南连仙霞岭，东北遥接舟山群岛，为曹娥江与甬江的分水岭，多悬岩、峭壁、瀑布。台州市天台山景区总面积为187.1平方千米，区内根据其地理位置和特色共分为：国清景区、赤城景区、佛陇景区、石梁一铜壶景区、仗琼台景区、华顶景区、桐坑溪一万年寺景区、桃源景区、开岩一紫凝景区、清溪景区、寒山湖景区、明寒岩景区和九遮山...', '08:00-18:00', '65元', 4.5, '萤火虫,避暑,瀑布,佛教', '亚洲著名萤火虫观赏地'),
(18, '三圣花乡', (SELECT `id` FROM `city` WHERE `name` = '成都'), '亲子', '4A', '四川省成都市锦江区三圣街道', 'https://baike.baidu.com/item/%E4%B8%89%E5%9C%A3%E8%8A%B1%E4%B9%A1?fromModule=lemma_search-box', 104.144700, 30.575706, '/images/scenic/sanshenghuaxiang/sanshenghuaxiang_cover.jpg', '三圣花乡又称三圣花乡观光旅游区，位于四川省成都市锦江区成龙路三环路外侧，总面积达15000亩，它是一个以观光休闲农业和乡村旅游为主题，集休闲度假、观光旅游、餐饮娱乐、商务会议等于一体的城市近郊生态休闲度假胜地。三圣花乡由“花乡农居”“幸福梅林”“江家菜地”“荷塘月色”“东篱菊园”五个主题景区组成，由于五个景区分别以五类不同花卉为主要特点，被誉为“五朵金花”。2006年4月，三圣花乡被国家旅游总局评...', '全天开放', '免费', 4.3, '花卉,乡村旅游,亲子,农家乐', '成都后花园，四季赏花'),
(19, '花舞人间', (SELECT `id` FROM `city` WHERE `name` = '成都'), '亲子', '4A', '四川省成都市新津区永商镇', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E5%B8%82%E8%8A%B1%E8%88%9E%E4%BA%BA%E9%97%B4%E6%97%85%E6%B8%B8%E6%99%AF%E5%8C%BA?fromtitle=%E8%8A%B1%E8%88%9E%E4%BA%BA%E9%97%B4&fromid=1315360&fromModule=lemma_search-box', 101.786507, 26.525863, '/images/scenic/huawurenjian/huawurenjian_cover.jpg', '成都市花舞人间旅游景区位于成都市新津区永商镇梨花大道1段555号，是国家4A级旅游景区。景区占地3000余亩，以四季花卉为主题，全年举办郁金香节、杜鹃花节等活动，其中杜鹃花品种超过130种，数量达500万株。核心景点包括迷宫花园、杜鹃长廊、花卉博览园等，迷宫花园以植物为墙构建独特游览路径，同心潭结合多层水道设计展现水景特色。景区设有森林漂流项目及四大主题餐厅，提供餐饮与宴会服务。', '09:00-18:00', '80元', 4.4, '花海,郁金香,亲子,踏青', '郁金香花海，成都赏花胜地'),
(20, '成都欢乐谷', (SELECT `id` FROM `city` WHERE `name` = '成都'), '亲子', '4A', '四川省成都市金牛区西华大道16号', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E6%AC%A2%E4%B9%90%E8%B0%B7?fromModule=lemma_search-box', 104.032363, 30.721408, '/images/scenic/chengduhuanlegu/chengduhuanlegu_cover.jpg', '成都欢乐谷（Chengdu Happy Valley），位于四川省成都市金牛区西华大道16号。成都欢乐谷于2009年1月18日正式开业，年均接待游客250万，是继深圳欢乐谷、北京欢乐谷之后，中国欢乐谷连锁品牌的第三站。成都欢乐谷总面积51万平方米，总投资23亿元，由阳光港区、欢乐时光区、加勒比旋风区、巴蜀迷情区、魔幻森林（飞行岛）区、魔幻城堡区、飞跃地中海区、欢乐光年区及丝路传奇区九个主题区组成，...', '09:30-21:00', '约230元', 4.5, '主题乐园,游乐,亲子,演艺', '成都最热门大型主题乐园'),
(21, '宝光寺·桂湖', (SELECT `id` FROM `city` WHERE `name` = '成都'), '人文', '4A', '四川省成都市新都区桂湖街道', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E5%B8%82%E5%AE%9D%E5%85%89%E6%A1%82%E6%B9%96%E6%96%87%E5%8C%96%E6%97%85%E6%B8%B8%E5%8C%BA/67182123', 104.160551, 30.831241, '/images/scenic/baoguangsiguihu/baoguangsiguihu_cover.jpg', '成都市宝光桂湖文化旅游区是位于四川省成都市新都区桂湖街道的国家4A级旅游景区。宝光寺相传始建于东汉，为长江流域“四大佛教丛林”之一，现存“寺塔一体、塔踞中心”的早期佛寺布局，寺内舍利塔因塔身微倾被誉为“东方斜塔”，罗汉堂存有500余尊清代彩塑罗汉，2001年被列为全国重点文物保护单位。桂湖始建于隋唐，明代状元杨慎曾在此植桂赋诗，拥有成都平原保存最完好的850米明代古城墙，园内以红莲、金桂景观著称，...', '08:00-17:30', '宝光寺5元，桂湖20元', 4.4, '佛教,园林,罗汉堂,荷花', '千年宝光寺与明代桂湖园林'),
(22, '崇州竹艺村', (SELECT `id` FROM `city` WHERE `name` = '成都'), '亲子', '4A', '四川省成都市崇州市道明镇', 'https://baike.baidu.com/item/%E7%AB%B9%E8%89%BA%E6%9D%91%E6%99%AF%E5%8C%BA?fromModule=lemma_search-box', 103.604838, 30.665478, '/images/scenic/chongzhouzhuyicun/chongzhouzhuyicun_cover.jpg', '竹艺村景区，竹艺村景区位于四川省成都市崇州市重庆路，与成都市中心市区相距约40千米，与崇州市中心市区相距约9.3千米。景区地处丘陵与坝区的交界处，海拔600—750米。2018年2月，竹艺村景区开放，主要景点有竹艺公园、竹文化体验馆、半山草庐、无动力乐园。景区的创建让传统竹编焕发新的生机与活力。2021年1月，竹艺村景区被中华人民共和国文化和旅游厅评定为国家4A级旅游景区。', '全天开放', '免费', 4.4, '非遗,竹编,乡村,文创', '道明竹编非遗村，乡村美学典范'),
(23, '九寨沟风景名胜区', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '5A', '四川省阿坝州九寨沟县漳扎镇', 'https://baike.baidu.com/item/%E9%98%BF%E5%9D%9D%E8%97%8F%E6%97%8F%E7%BE%8C%E6%97%8F%E8%87%AA%E6%B2%BB%E5%B7%9E%E4%B9%9D%E5%AF%A8%E6%B2%9F%E6%99%AF%E5%8C%BA/64978492?fromtitle=%E4%B9%9D%E5%AF%A8%E6%B2%9F&fromid=122560', 103.886073, 33.116210, '/images/scenic/jiuzhaigoufengjingmingshengqu/jiuzhaigoufengjingmingshengqu_cover.jpg', '九寨沟风景名胜区位于四川省西北部岷山山脉南段的阿坝藏族羌族自治州九寨沟县漳扎镇境内。距离成都市400多千米，系长江水系嘉陵江上游白水江源头的一条大支沟。九寨沟风景名胜区全区面积约720平方千米，大部分为森林所覆盖。九寨沟风景名胜区景观分布在成Ｙ型的树正、日则、则查洼3条主沟内，总长50余千米。主沟叫树正沟，呈南北延伸，南高北低，向北开口，其上有两条支沟，东名则查哇沟，西名日则沟。沟谷总长约50千米...', '07:00-18:00', '旺季169元，淡季80元', 4.9, '世界遗产,自然风光,摄影圣地,海子', '童话世界，水景之王'),
(24, '黄龙风景名胜区', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '5A', '四川省阿坝州松潘县川主寺镇', 'https://baike.baidu.com/item/%E9%BB%84%E9%BE%99%E9%A3%8E%E6%99%AF%E5%90%8D%E8%83%9C%E5%8C%BA/17722?fromtitle=%E5%9B%9B%E5%B7%9D%E9%BB%84%E9%BE%99%E9%A3%8E%E6%99%AF%E5%90%8D%E8%83%9C%E5%8C%BA&fromid=1879735&fromModule=lemma_search-box', 103.930366, 32.778196, '/images/scenic/huanglongfengjingmingshengqu/huanglongfengjingmingshengqu_cover.jpg', '黄龙风景名胜区，简称黄龙景区，位于四川省阿坝藏族羌族自治州松潘县，是中国唯一保护完好的高原湿地，在一条由南向北逐渐隆起的山脊上。黄龙风景名胜区面积700平方千米，与九寨沟相距100千米，海拔1700~5588米。黄龙风景名胜区核心区域点缀着三千多个彩池。以结构奇巧、色彩丰艳的地表钙华景观为主景，由黄龙沟、丹云峡、牟尼沟、雪宝鼎、红军长征纪念碑碑园等组成。主要景观集中于雪宝峰下的黄龙沟中，沟内遍布乳...', '07:00-18:00', '旺季170元，淡季60元', 4.8, '世界遗产,钙华彩池,高原,摄影', '人间瑶池，彩池雪山四绝'),
(25, '稻城亚丁', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '5A', '四川省甘孜州稻城县香格里拉镇', 'https://baike.baidu.com/item/%E7%94%98%E5%AD%9C%E8%97%8F%E6%97%8F%E8%87%AA%E6%B2%BB%E5%B7%9E%E7%A8%BB%E5%9F%8E%E4%BA%9A%E4%B8%81%E6%97%85%E6%B8%B8%E6%99%AF%E5%8C%BA/64869704?fromtitle=%E7%A8%BB%E5%9F%8E%E4%BA%9A%E4%B8%81&fromid=659694', 100.388799, 28.405385, '/images/scenic/daochengyading/daochengyading_cover.jpg', '甘孜藏族自治州稻城亚丁旅游景区，简称稻城亚丁景区（Daocheng Yading Scenic Area）、亚丁景区，是位于四川省甘孜藏族自治州稻城县香格里拉镇境内的旅游景区，景区面积为32.44平方千米。稻城亚丁景区藏语名为“念青贡嘎日松贡布”，意为“向阳之地””。1996年开始开发，以区内藏族小山村“亚丁”命名了该景区，并沿用至今。景区内北峰“仙乃日”意为观音菩萨，海拔6032米，南峰“央迈勇...', '07:00-18:00', '146元（观光车120元另计）', 4.8, '雪山,高原湖泊,徒步,摄影圣地', '最后的香格里拉，三神山圣湖'),
(26, '四姑娘山', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '5A', '四川省阿坝州小金县四姑娘山镇', 'https://baike.baidu.com/item/%E5%9B%9B%E5%A7%91%E5%A8%98%E5%B1%B1?fromModule=lemma_search-box', 102.832468, 30.993079, '/images/scenic/siguniangshan/siguniangshan_cover.jpg', '四姑娘山位于阿坝州小金县，因大姑娘、二姑娘、三姑娘、幺妹峰四座连绵雪峰而得名，主峰幺妹峰海拔6250米，素有“蜀山皇后”“东方阿尔卑斯”之誉。景区由双桥沟、长坪沟、海子沟三条沟组成，雪山、冰川、草甸、原始森林与高山湖泊交织，风光雄奇秀美，是登山、徒步与户外摄影的胜地，四季各有风情，秋季彩林与冬日雪景尤为动人。', '08:00-17:30', '双桥沟80元，长坪沟70元', 4.7, '雪山,徒步,户外,摄影圣地', '蜀山皇后，东方阿尔卑斯'),
(27, '海螺沟冰川森林公园', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '5A', '四川省甘孜州泸定县磨西镇', 'https://baike.baidu.com/item/%E7%94%98%E5%AD%9C%E8%97%8F%E6%97%8F%E8%87%AA%E6%B2%BB%E5%B7%9E%E6%B5%B7%E8%9E%BA%E6%B2%9F%E6%99%AF%E5%8C%BA?fromtitle=%E6%B5%B7%E8%9E%BA%E6%B2%9F%E5%86%B0%E5%B7%9D%E6%A3%AE%E6%9E%97%E5%85%AC%E5%9B%AD&fromid=3258441&fromModule=lemma_search-box', 101.995795, 29.578737, '/images/scenic/hailuogoubingchuansenlingongyuan/hailuogoubingchuansenlingongyuan_cover.jpg', '海螺沟位于贡嘎雪山东坡，是亚洲海拔最低的现代冰川之一，冰川最低处海拔仅2850米，游客可近距离观赏冰川、冰瀑布、冰洞等奇观。沟内有原始森林、温泉、雪山与红石滩，大冰瀑布气势磅礴。景区集冰川、温泉、森林、雪山于一体，可泡温泉、观冰川，四季风光各异，是川西高原极具特色的自然旅游胜地。', '07:00-18:00', '90元（观光车+索道另计）', 4.7, '冰川,温泉,雪山,红石滩', '低海拔现代冰川，可近观大冰瀑'),
(28, '康定情歌（木格措）风景区', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州康定市雅拉乡', 'https://baike.baidu.com/item/%E5%BA%B7%E5%AE%9A%E6%83%85%E6%AD%8C%EF%BC%88%E6%9C%A8%E6%A0%BC%E6%8E%AA%EF%BC%89%E9%A3%8E%E6%99%AF%E5%8C%BA/15204784', 101.904730, 30.187377, '/images/scenic/kangdingqinggemugecuofengjingqu/kangdingqinggemugecuofengjingqu_cover.jpg', '康定情歌（木格措）风景区，又名康定情歌景区，位于四川省甘孜藏族自治州康定市北雅拉乡境内，地处于贡嘎山中段，距离市区17千米，是《康定情歌》发源地。景区总面积达350平方千米，海拔2600-3780米，由杜鹃峡、芳草坪、七色海、药池沸泉、木格措（野人海）和红海草原六个景点组成，以高原湖泊、原始森林、温泉、雪峰、千瀑峡及周边多样化的高山湖泊和温泉景观著称。景区内木格措（野人海）水域面积4平方千米，水深...', '08:00-18:00', '105元（观光车90元另计）', 4.5, '高原湖泊,雪山,温泉,康定情歌', '康定情歌故乡，海子温泉'),
(29, '色达五明佛学院', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '人文', NULL, '四川省甘孜州色达县洛若镇', 'https://baike.baidu.com/item/%E8%89%B2%E8%BE%BE%E4%BA%94%E6%98%8E%E4%BD%9B%E5%AD%A6%E9%99%A2?fromModule=lemma_search-box', 100.470727, 32.150839, '/images/scenic/sedawumingfoxueyuan/sedawumingfoxueyuan_cover.jpg', '色达喇荣五明佛学院坐落于甘孜州色达县喇荣沟，是世界上规模最大的藏传佛学院之一。漫山遍野的红色木屋依山而建、层层叠叠，绵延数公里，蔚为壮观，被誉为“红色的信仰之城”。这里僧众云集、经声不绝，宗教氛围浓郁而神圣，是了解藏传佛教文化与感受信仰力量的地方，黄昏与清晨的光影尤为震撼。', '全天可外观', '免费', 4.7, '藏传佛教,红房子,人文,摄影', '漫山红屋，震撼心灵的信仰之城'),
(30, '新都桥', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', NULL, '四川省甘孜州康定市新都桥镇', 'https://baike.baidu.com/item/%E6%96%B0%E9%83%BD%E6%A1%A5%E9%95%87?fromtitle=%E6%96%B0%E9%83%BD%E6%A1%A5&fromid=5362696&fromModule=lemma_search-box', 101.493546, 30.044018, '/images/scenic/xindouqiao/xindouqiao_cover.jpg', '新都桥镇，隶属于四川省甘孜藏族自治州康定市，地处康定市折多山以西、川藏线南北两路分岔口的立曲河中游，东靠瓦泽乡，南接呷巴乡，西与雅江县接壤，北与塔公乡毗邻。区域面积463平方千米，截至2019年末，户籍人口6320人。1957年，属东俄洛乡。1992年，设新都桥镇。2019年12月，撤销瓦泽乡，将其所属行政区域划归新都桥镇管辖。截至2020年6月，新都桥镇下辖1个社区和25个行政村。2019年，新都桥镇有营业面积超过50平方米以上的综合商店或超市5个。', '全天开放', '免费', 4.6, '摄影天堂,高原草甸,川藏线,藏寨', '318线上的摄影家天堂'),
(31, '塔公草原', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州康定市塔公镇', 'https://baike.baidu.com/item/%E5%A1%94%E5%85%AC%E8%8D%89%E5%8E%9F/1238351', 101.562276, 30.334167, '/images/scenic/tagongcaoyuan/tagongcaoyuan_cover.jpg', '塔公草原位于四川省甘孜藏族自治州康定市塔公镇境内，距康定市区113公里，海拔3730米的高原地带，川藏公路穿境而过。“塔公”藏语意为“菩萨喜欢的地方”。草原面积712.37平方公里，地势起伏和缓，属于高山草甸景观，背靠雅拉神山。景区以高耸的雅拉雪山、起伏的草原和草原上金碧辉煌的“木雅经塔”为主要内容。2024年2月，塔公草原正式挂牌国家3A级旅游景区。自2021年以来，都江堰市累计在塔公村投入援建资金，推动“牧区变景区”的旅游新业态。', '全天开放', '免费', 4.5, '草原,雅拉雪山,藏传佛教,摄影', '菩萨喜欢的地方，草原映雪山'),
(32, '木雅圣地', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州康定市呷巴乡', 'https://baike.baidu.com/item/%E6%9C%A8%E9%9B%85%E5%9C%A3%E5%9C%B0%E6%99%AF%E5%8C%BA/19935917?fromModule=search-result_lemma', 101.573978, 29.961778, '/images/scenic/muyashengdi/muyashengdi_cover.jpg', '木雅圣地景区位于四川省甘孜藏族自治州康定市折多山西侧318国道贡布卡二号桥木雅辛康，占地面积80平方公里，属国家4A级旅游景区，平均海拔3200-4600米，距康定机场13公里，于8月7日正式开业。作为甘孜州首座民俗风情与自然风光相结合的旅游景区，也是全国首个以藏族木雅文化为主题的专题旅游区，景区融合高原草甸、雪山群峰（可远眺贡嘎山）、湿地河流等自然景观。该地历史上既是木雅王国的领地，也是茶马古道...', '08:30-18:00', '约120元', 4.5, '藏寨,草原,雪山,康巴风情', '原始质朴的康巴藏乡圣地'),
(33, '达古冰川', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '4A', '四川省阿坝州黑水县芦花镇', 'https://baike.baidu.com/item/%E8%BE%BE%E5%8F%A4%E5%86%B0%E5%B7%9D?fromModule=lemma_search-box', 102.865736, 32.232474, '/images/scenic/dagubingchuan/dagubingchuan_cover.jpg', '达古冰川位于四川省阿坝藏族羌族自治州黑水县芦花镇马桥，系现代山地冰川。走进远古，探古溯源，“达古冰川”因此得名。风景游览区规划面积210平方千米、自然保护区面积632平方千米。景区内共有现代冰川13条，冰面积6.04平方千米。1992年，日本科学家在卫星上发现了达古冰川。同年8月，科学家登上了达古冰川对其进行了一周的考察，并认为达古冰川是全球海拔最低，面积最大，年纪最轻的冰川，也是距离城市最近的冰...', '08:00-17:00', '120元（索道180元另计）', 4.6, '冰川,索道,雪山,彩林', '全球最高索道，直抵云端冰川'),
(34, '毕棚沟', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '4A', '四川省阿坝州理县朴头镇', 'https://baike.baidu.com/item/%E6%AF%95%E6%A3%9A%E6%B2%9F?fromModule=lemma_search-box', 102.938413, 31.303950, '/images/scenic/bipenggou/bipenggou_cover.jpg', '毕棚沟，又称毕棚沟风景区，位于四川省阿坝藏族羌族自治州理县朴头乡梭罗沟境内，四姑娘山北，是大熊猫栖息地和米亚罗的核心区域，被称为“川西小瑞士”。毕棚沟海拔在2015—5922米之间，面积613.8平方千米。沟内自然景观原始古朴，涵盖冰川、雪峰、海子、原始森林、溪流、飞瀑、高山草甸、红叶、花海、彩林等自然风光，有骆驼峰、玉兔峰、狮子峰、青龙瀑布、卓玛湖、月亮湾等景点。2013年1月，毕棚沟被评为国家...', '08:00-18:00', '80元（观光车60元另计）', 4.6, '红叶,雪山,湖泊,避暑', '川西小瑞士，秋日红叶如画'),
(35, '奶子沟彩林', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '4A', '四川省阿坝州黑水县沙石多乡', 'https://baike.baidu.com/item/%E5%A5%B6%E5%AD%90%E6%B2%9F%E5%BD%A9%E6%9E%97%E6%99%AF%E5%8C%BA?fromtitle=%E5%A5%B6%E5%AD%90%E6%B2%9F%E5%BD%A9%E6%9E%97&fromid=505292&fromModule=lemma_search-box', 117.861843, 41.747313, '/images/scenic/naizigoucailin/naizigoucailin_cover.jpg', '奶子沟彩林景区，又名奶子沟彩林公园旅游区、奶子沟彩林公园，位于四川阿坝藏族羌族自治州黑水县至马尔康的要道之间，与红原大草原相连。“奶子沟”在藏语中是美丽富饶、幸福安宁之意。奶子沟彩林景区是中国开发并已开放时面积最大、景观较为壮观的红叶景区之一，是亚洲最大的八十里天然彩林，包括洛哩措、羊茸村、藏寨、栈道等景点和藏式土火锅、土豆宴等美食。奶子沟彩林景区植被丰茂，阳光灿烂，氧气充足。这里生活着安多藏族和嘉绒藏族，是典型的安多和嘉绒地域文化相汇交融的地方。2019年11月，黑水奶子沟彩林公园旅游区获评国家AAAA级景区。2023年8月22日，黑水奶子沟彩林公园旅游区获评2023四川十大避暑胜地。202...', '全天开放', '免费', 4.6, '彩林,红叶,自驾,摄影', '亚洲最大彩林，八十里画廊'),
(36, '卓克基土司官寨', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '人文', '4A', '四川省阿坝州马尔康市卓克基镇', 'https://baike.baidu.com/item/%E5%8D%93%E5%85%8B%E5%9F%BA%E5%9C%9F%E5%8F%B8%E5%AE%98%E5%AF%A8?fromModule=lemma_search-box', 102.293074, 31.867250, '/images/scenic/zhuokejitusiguanzhai/zhuokejitusiguanzhai_cover.jpg', '卓克基土司官寨位于阿坝州马尔康市卓克基镇，是全国重点文物保护单位，也是嘉绒藏族土司文化与建筑的代表。官寨始建于清乾隆年间，依山傍水、雄伟壮观，为典型的嘉绒藏式建筑，集官署、住宅、经堂于一体，木石结构、雕饰精美，被誉为“东方建筑明珠”。著名作家阿来的《尘埃落定》即以此地为背景，周边还有西索民居等景点。', '08:30-18:00', '60元', 4.5, '土司文化,古建筑,嘉绒藏族,红色', '尘埃落定故事地，东方建筑明珠'),
(37, '甲居藏寨', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '人文', '4A', '四川省甘孜州丹巴县甲居镇', 'https://baike.baidu.com/item/%E7%94%B2%E5%B1%85%E8%97%8F%E5%AF%A8?fromModule=lemma_search-box', 101.865601, 30.940488, '/images/scenic/jiajucangzhai/jiajucangzhai_cover.jpg', '甲居藏寨位于四川甘孜州丹巴县境内，距县城约8公里，是丹巴最具特色的旅游景区。2016年9月，正式获批成为国家4A级旅游景区。“甲居”，藏语是百户人家之意。藏寨从大金河谷层层向上攀缘，一直伸延到卡帕玛群峰脚下，整个山寨依着起伏的山势迤逦连绵，在相对高差近千米的山坡上，一幢幢藏式楼房洒落在绿树丛中。或星罗棋布，或稠密集中，或在高山悬崖上，或在河坝绿茵间，不时炊烟袅袅、烟云缭绕，与充满灵气的山谷、清澈的...', '全天开放', '60元', 4.6, '藏寨,田园,嘉绒藏族,摄影', '中国最美乡村，嘉绒碉楼藏寨'),
(38, '泸定桥', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '红色', '4A', '四川省甘孜州泸定县泸桥镇', 'https://baike.baidu.com/item/%E6%B3%B8%E5%AE%9A%E6%A1%A5?fromModule=lemma_search-box', 102.231774, 29.911794, '/images/scenic/ludingqiao/ludingqiao_cover.jpg', '泸定桥（Luding Chain Bridge），又名大渡桥，是中国四川省甘孜藏族自治州泸定县泸桥镇境内的一座跨大渡河铁索桥，为泸定桥风景区的主要景观文物。泸定桥始建于清康熙四十四年（1705年）九月，于清康熙四十五年（1706年）四月投入使用；于1961年3月4日被纳入中国首批全国重点文物保护单位；于2003年纳入景区管理。泸定桥全长103.67米，宽3米，由13根锁链组成，为一座历史悠久的古桥...', '07:30-19:00', '10元', 4.6, '红色旅游,铁索桥,长征,历史', '红军飞夺泸定桥，重温长征'),
(39, '德格印经院', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '人文', '4A', '四川省甘孜州德格县更庆镇', 'https://baike.baidu.com/item/%E5%BE%B7%E6%A0%BC%E5%8D%B0%E7%BB%8F%E9%99%A2?fromModule=lemma_search-box', 98.580765, 31.804101, '/images/scenic/degeyinjingyuan/degeyinjingyuan_cover.jpg', '德格印经院位于甘孜州德格县更庆镇，是全国重点文物保护单位，与拉萨布达拉宫印经院、甘肃拉卜楞寺印经院并称藏区三大印经院。它始建于清雍正年间，藏有各类藏文典籍雕版二十余万块，内容涵盖宗教、历史、医学、天文等，被称为“藏族文化宝库”“藏文化敦煌”。院内保留着完整的雕版与印刷工艺，可观看工匠手工印制经书的全过程。', '09:00-12:00,14:00-17:00', '50元', 4.6, '藏文化,印经院,雕版,非遗', '藏文化宝库，手工雕版印刷圣地'),
(40, '伍须海', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州九龙县汤古镇', 'https://baike.baidu.com/item/%E4%BC%8D%E9%A1%BB%E6%B5%B7?fromModule=lemma_search-box', 101.405587, 29.152518, '/images/scenic/wuxuhai/wuxuhai_cover.jpg', '伍须海是国家级贡嘎山风景名胜区的重要组成部分，伍须海风景区位于四川甘孜九龙县北部，距离县城25公里，景区面积400km²，境内山峦重叠、沟壑纵横，西南白雪皑皑的大雪山南北走向，地势北高南低，年平均气温4.9℃，景区平均海拔3500m，平均最低海拔1440m，最高海拔6010m。伍须海在藏语中意为“光辉灿烂的湖泊”，享有“康巴第一海”的美誉。其迤逦风光早在1929年就被美国探险家约瑟夫·洛克发现并发...', '08:30-17:30', '60元', 4.5, '高原湖泊,原始森林,秘境,摄影', '康巴第一海，静谧原始秘境'),
(41, '措普沟', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州巴塘县茶洛乡', 'https://baike.baidu.com/item/%E6%8E%AA%E6%99%AE%E6%B2%9F?fromModule=lemma_search-box', 99.550421, 30.492078, '/images/scenic/cuopugou/cuopugou_cover.jpg', '措普沟是位于川西甘孜州海子山下巴塘县县城北部措拉区（茶洛乡）境内的景区，东起毛垭坝与理塘县接壤，西至海拔4860米的亚素高山，南从列衣、沙溪乡以上至扎金甲波神山与白玉相邻，方圆九百平方公里。措普沟浓缩了川西藏区的美景，雪山、草原、森林、湖泊、寺庙。措普沟上的措普湖被誉为“康巴第一圣湖”。2023年11月30日，国家林业和草原局公布《陆生野生动物重要栖息地名录（第一批）》，四川巴塘措普沟雉类及爬行类...', '全天开放', '免费（项目另收）', 4.5, '圣湖,温泉,秘境,高原风光', '康巴第一圣湖，高原秘境'),
(42, '花湖生态旅游区', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '4A', '四川省阿坝州若尔盖县213国道旁', 'https://baike.baidu.com/item/%E8%8B%A5%E5%B0%94%E7%9B%96%E8%8A%B1%E6%B9%96%E7%94%9F%E6%80%81%E6%97%85%E6%B8%B8%E5%8C%BA/24186460?fromModule=search-result_lemma', 102.826184, 33.921110, '/images/scenic/huahushengtailvyouqu/huahushengtailvyouqu_cover.jpg', '若尔盖花湖（外文名：ruoergaihuahu）位于四川省阿坝州若尔盖县与甘肃郎木寺之间的213国道旁，地处热尔大坝草原腹心地带，海拔3468米，由错尔干、错热哈三个海子组成，属若尔盖湿地国家级自然保护区核心区域。该湖为黄河上游重要水源涵养地，年补水量达44亿立方米，占黄河年径流量7.58%，拥有中国最大高原泥炭沼泽湿地，碳储量达16.10kg/m²，承担着黄河流域生态屏障功能。湖区属高寒湿地生态...', '07:00-18:00', '约75元', 4.6, '湿地,草原,观鸟,花海', '若尔盖草原上的绿宝石'),
(43, '黄河九曲第一湾', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '4A', '四川省阿坝州若尔盖县唐克镇', 'https://baike.baidu.com/item/%E9%BB%84%E6%B2%B3%E4%B9%9D%E6%9B%B2%E7%AC%AC%E4%B8%80%E6%B9%BE?fromModule=lemma_search-box', 102.470518, 33.477917, '/images/scenic/huanghejiuqudiyiwan/huanghejiuqudiyiwan_cover.jpg', '黄河九曲第一湾，又称四川若尔盖黄河九曲第一湾景区，四川省阿坝藏族羌族自治州若尔盖县唐克镇和辖曼镇交界处景观，地处四川、青海、甘肃三省交界处，是国家4A级旅游景区。由于北秦岭、龙门山和大雪山三大构造带的挤压，阻挡了黄河由西北向东南继续前进的道路，黄河在若尔盖县唐克乡与白河汇合，形成黄河九曲第一湾。景区属高原大陆性高寒湿润区，全年四季界限模糊，年均气温1.2℃。有各种生物生活，包括黑颈鹤、耗牛、锦鸡、...', '全天开放', '约65元', 4.6, '黄河,草原,落日,摄影', '黄河大拐弯，草原落日震撼'),
(44, '若尔盖草原', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', NULL, '四川省阿坝州若尔盖县', 'https://baike.baidu.com/item/%E8%8B%A5%E5%B0%94%E7%9B%96%E8%8D%89%E5%8E%9F/9305889', 102.508037, 33.308589, '/images/scenic/ruoergaicaoyuan/ruoergaicaoyuan_cover.jpg', '若尔盖草原，位于四川省阿坝藏族羌族自治州若尔盖县，是若尔盖国家公园组成部分。2022年5月，以若尔盖草原等为核心的若尔盖国家公园创建方案获批。若尔盖草原海拔3500米左右，属典型的丘状高原。冬季严寒，夏季凉爽，春秋短，日照充足，昼夜温差大。有花湖、热尔坝大草原、松潘草原、红原草原、黄河九曲第一湾等景点。2019年11月，若尔盖花湖生态旅游区获批国家AAAA级旅游景区。国道213、248、345线和省道217、445线贯穿全境。2023年4月8日，若尔盖花湖生态旅游区黄河九曲第一湾景区正式开园。若尔盖草原是黄河上游最重要的水源涵养地和生态功能区，是世界上最大的“高原固体水库”——若尔盖泥炭沼泽湿...', '全天开放', '免费', 4.6, '草原,湿地,自驾,露营', '川西北高原绿洲，辽阔牧歌草原'),
(45, '松潘古城', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '人文', '3A', '四川省阿坝州松潘县进安镇', 'https://baike.baidu.com/item/%E6%9D%BE%E6%BD%98%E5%8F%A4%E5%9F%8E/2606563?fromModule=lemma_search-box', 103.598228, 32.637982, '/images/scenic/songpangucheng/songpangucheng_cover.jpg', '松潘古城位于四川省阿坝藏族羌族自治州东北部的松潘县境内，处于川西民族走廊东部、岷江峡谷流域。古城分内、外两城，内城平面跨崇山，依山顺势略呈三角形，东部崇山之下河谷部分为长方形，外城毗邻内城南面的河谷下坝，有城门与内城相通，平面为长方形。城墙总长6.2千米，用本地烧制的青砖砌成墙身，内土石而成，高12.5米，厚12余米，以糯米、石灰、桐油熬制的灰浆粕连勾缝，坚固如铜墙铁壁。松潘古城始建于唐武德元年（618年），迄今已有1400余年的历史。明洪武十二年（1379年），宁州卫指挥高显来到松潘主持筑城事宜，历经五年，古城初步成形。至明嘉靖五年（1526年），松潘总兵何卿再度主持增筑外城1000余米，至...', '全天开放', '免费', 4.3, '古城,茶马古道,民族风情,历史', '川西北军事重镇，多民族古城'),
(46, '莲宝叶则·石头山', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '自然', '4A', '四川省阿坝州阿坝县龙藏乡', 'https://baike.baidu.com/item/%E8%8E%B2%E5%AE%9D%E5%8F%B6%E5%88%99/4368819?fromModule=search-result_lemma', 101.249383, 33.127585, '/images/scenic/lianbaoyezeshitoushan/lianbaoyezeshitoushan_cover.jpg', '莲宝叶则（Lianbao Yeze），又名石头山（藏名：叶尔精扎拉），地处青藏高原东南部，位于四川省阿坝藏族羌族自治州阿坝县和青海省久治县、班玛县之间，总面积约800余平方千米，四川阿坝境内面积约500余平方千米，青海境内称年宝玉则，又叫果洛山。莲宝叶则山为青藏高原上雄伟的巴颜喀拉山支脉果洛山的余脉，海拔在3500米至5369米之间，最高峰5369米，终年积雪。是藏区著名的神山，位居藏区十大神山的...', '08:00-18:00', '120元', 4.6, '冰川地貌,奇峰,高原湖泊,摄影', '奇峰怪石与高原湖泊的荒野秘境'),
(47, '亚拉雪山', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州道孚县泰宁镇', 'https://baike.baidu.com/item/%E4%BA%9A%E6%8B%89%E9%9B%AA%E5%B1%B1?fromModule=lemma_search-box', 101.701487, 30.378074, '/images/scenic/yalaxueshan/yalaxueshan_cover.jpg', '亚拉雪山景区，位于四川省甘孜藏族自治州道孚县，亚拉雪山景区规划面积251平方公里，雪山主峰海拔5820米，被，景区以亚拉雪山为核心，是集观光、山地休闲、极高山体验、康巴文化体验、茶马古道穿越等于一体的大型综合性旅游区。亚拉雪山景区，南北长约43公里，规划面积251平方公里。亚拉雪山景区最高点海拔5820米，山体岩层以花岗岩为主，加上长期冰蚀作用，坡壁陡峭，岩石裸露，坡度多大于60度，茶马古道从中穿...', '08:00-18:00', '约70元', 4.5, '雪山,冰川,草原,藏地神山', '藏区神山，雪山冰川草原'),
(48, '八美墨石公园', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '自然', '4A', '四川省甘孜州道孚县八美镇', 'https://baike.baidu.com/item/%E5%A2%A8%E7%9F%B3%E5%85%AC%E5%9B%AD%E6%99%AF%E5%8C%BA/20496609?fromModule=search-result_lemma', 101.483482, 30.483132, '/images/scenic/bameimoshigongyuan/bameimoshigongyuan_cover.jpg', '八美墨石公园位于甘孜州道孚县八美镇，是世界罕见的高原糜棱岩石林地质奇观。景区内奇石嶙峋、沟壑纵横，深邃的墨灰色石林随季节与天气变化呈现出不同色泽，宛如异域星球，极具视觉冲击力。这里海拔约3500米，周围是辽阔的高原草甸与连绵雪山，风光苍茫独特，是川西高原上一处极具辨识度的地质景观与摄影秘境。', '08:00-18:00', '约80元', 4.5, '地质奇观,石林,摄影,异域', '糜棱岩石林，随季节变色的奇景'),
(49, '甘孜格萨尔王城', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '人文', '4A', '四川省甘孜州甘孜县甘孜镇', 'https://baike.baidu.com/item/%E6%A0%BC%E8%90%A8%E5%B0%94%E7%8E%8B%E5%9F%8E?fromModule=lemma_search-box', 99.555439, 31.753344, '/images/scenic/ganzigesaerwangcheng/ganzigesaerwangcheng_cover.jpg', '格萨尔王城位于四川省甘孜藏族自治州甘孜县城东南部，地处格萨尔史诗“霍岭大战”遗址之上。该项目于2017年6月开工建设，2019年9月16日正式开城，规划占地1455亩，总投资约6.3亿元，是甘孜州一个产业扶贫与文化旅游融合项目。王城以格萨尔文化为主题，核心建筑包括森珠达孜王宫及三十员大将寨子，集文化展示、旅游体验、商贸休闲于一体，拥有尼泊尔风情街等特色区域。2020年5月，景区被评定为国家4A级旅...', '08:30-18:00', '约60元', 4.4, '格萨尔文化,藏文化,史诗,建筑', '格萨尔史诗文化主题之城'),
(50, '巴格嘛呢石经墙', (SELECT `id` FROM `city` WHERE `name` = '甘孜'), '人文', '4A', '四川省甘孜州石渠县长沙贡马乡', 'https://baike.baidu.com/item/%E6%9D%BE%E6%A0%BC%E5%98%9B%E5%91%A2%E7%9F%B3%E7%BB%8F%E5%9F%8E%E5%92%8C%E5%85%AB%E6%A0%BC%E5%98%9B%E5%91%A2%E7%9F%B3%E7%BB%8F%E5%A2%99/4280445?fromModule=search-result_lemma', 97.962428, 33.248370, '/images/scenic/bagemaneshijingqiang/bagemaneshijingqiang_cover.jpg', '巴格嘛呢石经墙位于四川省石渠县长沙贡马乡境内，距县城约53公里，背靠扎加庞秀神山，前临雅砻江。该墙始建于1640年，由第一世巴格喇嘛桑登彭措堆建，是世界上最长的嘛呢石经建筑群，并经吉尼斯认证为全球最长石经墙，2006年5月25日被国务院批准为第六批全国重点文物保护单位。墙体全部用刻有六字箴言、《甘珠尔》《丹珠尔》经文及彩绘图案的嘛呢石片垒砌，现石墙长1.7公里，宽2—3米，高2.5—3.5米，现存石刻佛像3000余尊，并藏有《贤劫经》《解脱经》等藏文典籍。沿墙体间隔分布多座佛塔及转经筒墙，两侧每隔3米设有石龛式窗口供奉彩绘佛像，墙头悬挂五色经幡。历经四世巴格喇嘛扩建维护，包括增刻经文、增建八座...', '全天开放', '免费', 4.5, '宗教,石经墙,藏文化,人文', '世界最长嘛呢石经墙'),
(51, '峨眉山', (SELECT `id` FROM `city` WHERE `name` = '乐山'), '自然', '5A', '四川省乐山市峨眉山市黄湾镇', 'https://baike.baidu.com/item/%E5%B3%A8%E7%9C%89%E5%B1%B1/2676', 103.339025, 29.520008, '/images/scenic/emeishan/emeishan_cover.jpg', '乐山市峨眉山景区，又称峨眉山风景名胜区，简称峨眉山景区（Mount Emei Scenic Area），位于四川省乐山市峨眉山市黄湾镇境内的旅游景区，核心景区面积154平方千米。峨眉山主峰金顶海拔3079米，最高峰万佛顶海拔3099米，拥有“雄、秀、奇、险、幽”的自然风光、丰富的生物资源、厚重的文化底蕴。峨眉山垂直落差2600米，具有世界上最典型、保存最完好的亚热带原始植被景观，按照现有标准划分的...', '06:00-18:30', '160元（旺季）', 4.8, '世界遗产,佛教名山,金顶,云海', '峨眉天下秀，金顶观日出云海'),
(52, '乐山大佛', (SELECT `id` FROM `city` WHERE `name` = '乐山'), '人文', '5A', '四川省乐山市市中区篦子街', 'https://baike.baidu.com/item/%E4%B9%90%E5%B1%B1%E5%A4%A7%E4%BD%9B/142192', 103.771520, 29.544156, '/images/scenic/leshandafu/leshandafu_cover.jpg', '乐山市乐山大佛景区，位于四川省乐山市岷江、青衣江、大渡河三江汇流处，与乐山隔江相望，景区面积17.88平方千米，其中核心景区面积2.81平方千米。乐山市乐山大佛景区核心乐山大佛开凿于唐玄宗开元元年（713年），最早是由贵州僧人海通主持修建的，修凿的佛像为弥勒佛，目的是减弱该河流交汇处的水势。2020年6月，乐山大佛景区集凤峰升级改造项目启动。2021年11月，乐山大佛景区集凤峰升级改造项目全面竣工...', '07:30-18:30', '80元', 4.8, '世界遗产,石刻,佛教,古迹', '山是一尊佛，世界最大摩崖坐佛'),
(53, '蜀南竹海', (SELECT `id` FROM `city` WHERE `name` = '宜宾'), '自然', '4A', '四川省宜宾市长宁县竹海镇', 'https://baike.baidu.com/item/%E8%9C%80%E5%8D%97%E7%AB%B9%E6%B5%B7%E6%97%85%E6%B8%B8%E5%BA%A6%E5%81%87%E5%8C%BA/60205021', 105.018734, 28.481606, '/images/scenic/shunanzhuhai/shunanzhuhai_cover.jpg', '宜宾市蜀南竹海风景名胜区位于四川省宜宾市长宁县与江安县交界处，总面积120平方公里，核心景区45平方公里，为国家4A级旅游景区和国家级旅游度假区。景区拥有7万余亩天然竹林，覆盖27条峻岭、500多座峰峦，生长着楠竹、紫竹等58种竹类，植被覆盖率92.4%，负氧离子浓度达30223个/立方厘米，素有“竹海天下翠”之称。主要景观包括翡翠长廊、七彩飞瀑、仙寓硐、忘忧谷等八大主景区，形成集丹霞地貌、湖泊瀑...', '08:00-18:00', '约110元', 4.6, '竹海,森林,避暑,摄影', '万顷竹海，中国最美森林之一'),
(54, '自贡恐龙博物馆', (SELECT `id` FROM `city` WHERE `name` = '自贡'), '亲子', '4A', '四川省自贡市大安区燊海井路四段268号', 'https://baike.baidu.com/item/%E8%87%AA%E8%B4%A1%E6%81%90%E9%BE%99%E5%8D%9A%E7%89%A9%E9%A6%86/444423', 104.828689, 29.396018, '/images/scenic/zigongkonglongbowuguan/zigongkonglongbowuguan_cover.jpg', '自贡恐龙博物馆（Zigong Dinosaur Museum），位于四川省自贡市的东北部大山铺镇，于1987年建成开放，占地面积6.6万多平方米，馆藏化石标本囊括了距今2.01~1.45亿年前侏罗纪时期所有已知恐龙种类，是全国首批“国家一级博物馆”，联合国教科文组织“自贡世界地质公园”的核心园区，自贡恐龙旅游度假区内景点，国家AAAA级旅游景区。是“中国旅游胜地四十佳”“全国科普教育基地”“全国甲...', '08:30-17:30', '约40元', 4.7, '恐龙,博物馆,科普,亲子', '世界三大恐龙遗址博物馆之一'),
(55, '李庄古镇', (SELECT `id` FROM `city` WHERE `name` = '宜宾'), '古镇', '4A', '四川省宜宾市翠屏区李庄镇', 'https://baike.baidu.com/item/%E6%9D%8E%E5%BA%84%E5%8F%A4%E9%95%87/9009500', 104.800560, 28.804815, '/images/scenic/lizhuangguzhen/lizhuangguzhen_cover.jpg', '李庄古镇（Lizhuang Ancient Town）是四川省宜宾市内的国家AAAA级景区，是历史文化古镇，位于四川省宜宾市翠屏区李庄镇。截至2022年9月，全镇幅员面积71.52平方千米，人口4.7万；建成区3平方千米，核心景区面积为1平方千米。李庄古镇始建于梁代大同六年（公元540年），距今已有1480余年的建置史，辖区曾作为六同郡和南广（南溪）县治所在地长达400多年，一度曾是川南6县政治、...', '全天开放', '免费', 4.5, '古镇,抗战文化,长江,古建', '万里长江第一镇，抗战文化名镇'),
(56, '兴文石海', (SELECT `id` FROM `city` WHERE `name` = '宜宾'), '自然', '4A', '四川省宜宾市兴文县石海镇', 'https://baike.baidu.com/item/%E5%85%B4%E6%96%87%E7%9F%B3%E6%B5%B7/7256614', 105.137123, 28.171517, '/images/scenic/xingwenshihai/xingwenshihai_cover.jpg', '兴文石海（兴文石海洞乡旅游区，兴文石海景区）位于四川省宜宾市兴文县石海镇境内。兴文石海总面积约156平方千米，公园内保存了距今4.9亿年—2.5亿年各时代的碳酸盐地层，地层中含有海相古生物化石和沉积相标志。是国内发现和研究天坑最早的地方，也是研究西南地区喀斯特地貌的地区之一。核心景区14平方千米范围内集中石海景观、地下溶洞群、世界级的大漏斗，被专家誉为喀斯特地貌博物馆。2005年2月，兴文石海被联...', '08:30-17:30', '约90元', 4.5, '喀斯特,石海,溶洞,苗族', '世界地质公园，石海溶洞奇观'),
(57, '中华彩灯大世界', (SELECT `id` FROM `city` WHERE `name` = '自贡'), '人文', '4A', '四川省自贡市大安区东盐都大道', 'https://baike.baidu.com/item/%E4%B8%AD%E5%8D%8E%E5%BD%A9%E7%81%AF%E5%A4%A7%E4%B8%96%E7%95%8C%E6%99%AF%E5%8C%BA/66722518', 120.686658, 30.530913, '/images/scenic/zhonghuacaidengdashijie/zhonghuacaidengdashijie_cover.jpg', '中华彩灯大世界景区（Zigong · Chinese Lantern World）位于四川省自贡市东部新城，为国家AAAA级旅游景区，占地面积9773亩，系自贡国际恐龙灯会永久举办地，由自贡市引进华侨城集团合作开发。景区分两期建设，一期于2018年12月投用，二期灯光博览城、彩灯总部基地等项目于2022年12月建成。作为大安区"一轴两翼"精品文化旅游线路左翼核心项目，景区联动江姐故居、自贡花海等景...', '以灯会档期为准', '以灯会为准', 4.6, '彩灯,灯会,夜游,非遗', '南国灯城，自贡灯会主场'),
(58, '燊海井', (SELECT `id` FROM `city` WHERE `name` = '自贡'), '人文', '4A', '四川省自贡市大安区大安街289号', 'https://baike.baidu.com/item/%E7%87%8A%E6%B5%B7%E4%BA%95/505769', 104.787943, 29.374034, '/images/scenic/shenhaijing/shenhaijing_cover.jpg', '自贡市燊海井景区是国家AAAA级旅游景区，位于四川省自贡市大安区大安街道，规划总面积近2000亩（主景区面积约1600亩），森林覆盖率达60%，为自贡世界地质公园核心组成部分。景区由燊海井、老盐场1957、燊海公园三大区域构成，集盐业遗址保护、工业遗产展示与生态休闲功能于一体，成人票价为25元（11月起对18岁以下未成年人实行免票），夏季开放时间为8:30-17:30，冬季为8:30-17:00。...', '08:30-17:30', '约30元', 4.5, '盐业,古井,工业遗产,非遗', '世界第一口超千米深井'),
(59, '泸州老窖旅游区', (SELECT `id` FROM `city` WHERE `name` = '泸州'), '人文', '4A', '四川省泸州市江阳区三星街', 'https://baike.baidu.com/item/%E6%B3%B8%E5%B7%9E%E8%80%81%E7%AA%96%E6%97%85%E6%B8%B8%E5%8C%BA/17390801', 105.453810, 28.884279, '/images/scenic/luzhoulaojiaolvyouqu/luzhoulaojiaolvyouqu_cover.jpg', '泸州老窖旅游区（又称泸州老窖景区、国窖1573广场）位于四川省泸州市江阳区三星街国窖广场，是国家AAAA级景区。泸州老窖旅游区以中国浓香型白酒发祥地和泸州老窖“双国宝”（中国现存建造最早、持续使用时间最长、保存完整的原生古窖池群——全国重点文物保护单位“1573国宝窖池群”，以及国家级非物质文化遗产“泸州老窖酒传统酿制技艺”）为核心，包含酒史浮雕图、泸州老窖酿酒水源龙泉井、纯手工酿制技艺生产现场、...', '08:30-17:30', '约50元', 4.5, '白酒,酒文化,工业旅游,非遗', '浓香鼻祖，1573国宝窖池群'),
(60, '尧坝古镇', (SELECT `id` FROM `city` WHERE `name` = '泸州'), '古镇', '4A', '四川省泸州市合江县尧坝镇', 'https://baike.baidu.com/item/%E5%B0%A7%E5%9D%9D%E5%8F%A4%E9%95%87/3352124', 105.645390, 28.740180, '/images/scenic/yaobaguzhen/yaobaguzhen_cover.jpg', '尧坝古镇位于四川省泸州市合江县尧坝镇，地处川渝黔结合部，距合江37公里、泸州22公里。古镇依山傍水，高低错落。现存建筑保存极为完整，古镇大多是典型的川南民居四合院的风格，绝大多数为清代、民国时期建筑。古民居群位于古街道两旁，全长1000多米，有小青瓦房2000余间，形成有节奏、有韵律的民居群落。尧坝古镇历史悠久，始于北宋，兴于明清，是古江阳到夜郎国的必经之道，有“川黔走廊”、“茶盐古道”之称；古镇...', '全天开放', '免费', 4.4, '古镇,影视,古街,民俗', '川南民居活化石，影视取景地'),
(61, '罗城古镇', (SELECT `id` FROM `city` WHERE `name` = '乐山'), '古镇', '4A', '四川省乐山市犍为县罗城镇', 'https://baike.baidu.com/item/%E7%BD%97%E5%9F%8E%E5%8F%A4%E9%95%87/1246529', 104.099686, 29.073389, '/images/scenic/luochengguzhen/luochengguzhen_cover.jpg', '罗城古镇是四川省乐山市犍为县下辖镇，位于犍为县东北部，距乐山市60公里，居住着汉、回、彝等7个民族。古镇属亚热带季风气候，交通便利。始建于明崇祯元年（1628年），成形于清代，曾是军事要地，旧称“罗城铺”。罗城古镇以船形街闻名，街长209米，是省级文物保护单位和省级历史文化名街。2018年被评为国家AAAA级景区，门票免费。2020年当选巴蜀文化旅游走廊新地标，特色食品包括清真牛肉系列，并因影视作...', '全天开放', '免费', 4.4, '古镇,船形街,市井,茶文化', '东方诺亚方舟，船形街奇特'),
(62, '柳江古镇', (SELECT `id` FROM `city` WHERE `name` = '眉山'), '古镇', '4A', '四川省眉山市洪雅县柳江镇', 'https://baike.baidu.com/item/%E6%9F%B3%E6%B1%9F%E9%95%87/10981316', 103.234559, 29.714240, '/images/scenic/liujiangguzhen/liujiangguzhen_cover.jpg', '柳江镇，隶属于四川省眉山市洪雅县，地处洪雅县西南部，东与花溪镇、桃源乡接壤，南与高庙镇相连，西与雅安市雨城区严桥镇、宴场镇交界，北靠瓦屋山镇，区域面积225.2平方千米。1949年，属柳江镇；1983年，改柳江镇；2005年，赵河乡并入柳江镇。2019年，撤销花溪镇，将其所属行政区域划归柳江镇管辖。2019年末，柳江镇总人口3.81万人。截至2020年6月，柳江镇辖2个社区、7个行政村，镇人民政府...', '全天开放', '免费', 4.4, '古镇,吊脚楼,烟雨,古榕', '烟雨柳江，川南烟雨古镇'),
(63, '瓦屋山', (SELECT `id` FROM `city` WHERE `name` = '眉山'), '自然', '4A', '四川省眉山市洪雅县瓦屋山镇', 'https://baike.baidu.com/item/%E7%93%A6%E5%B1%8B%E5%B1%B1/1056262', 102.942310, 29.642506, '/images/scenic/wawushan/wawushan_cover.jpg', '四川瓦屋山国家森林公园位于四川省眉山市洪雅县，距成都180公里，距乐山100公里，地处邛崃山支脉峨眉山西北面，地理坐标东经102°49′—103°00′、北纬29°25′—29°34′，总面积65869.80公顷，其中自然保护区面积36490.1公顷。该公园是世界第二大、亚洲最大的桌山，顶部平缓的玄武岩台面面积约11平方公里，四周为垂直落差逾千米的断崖。山体形成于6亿年前的震旦系灰岩和2亿年前的火...', '08:00-17:00', '约100元', 4.5, '山岳,杜鹃,云海,森林', '云上瓦屋，杜鹃花海仙境'),
(64, '三苏祠', (SELECT `id` FROM `city` WHERE `name` = '眉山'), '人文', '4A', '四川省眉山市东坡区纱縠行南段72号', 'https://baike.baidu.com/item/%E4%B8%89%E8%8B%8F%E7%A5%A0/4959313', 103.831072, 30.040654, '/images/scenic/sansuci/sansuci_cover.jpg', '三苏祠博物馆，国家一级博物馆，位于眉山市东坡区，是苏洵、苏轼、苏辙父子三人的故居及祠堂。原为约五亩的庭院，元代改宅为祠，明末毁于兵燹，清康熙四年（1665年）在原址模拟重建，是一座占地104亩的古典园林，2024年5月18日获评并于同年6月8日正式授牌国家一级博物馆。三苏祠博物馆是四川省重点文物保护单位，第六批全国重点文物保护单位，2010年1月被国家旅游局评为国家AAAA级旅游景区。2022年9...', '08:30-18:00', '40元', 4.6, '三苏,古建,园林,文化', '一门三父子，三苏故里祠堂'),
(65, '蒙顶山', (SELECT `id` FROM `city` WHERE `name` = '雅安'), '自然', '4A', '四川省雅安市名山区蒙顶山镇', 'https://baike.baidu.com/item/%E8%92%99%E9%A1%B6%E5%B1%B1/854669', 103.047961, 30.081423, '/images/scenic/mengdingshan/mengdingshan_cover.jpg', '蒙顶山风景区，位于四川省雅安市名山区三蒙路，四川盆地西南部。蒙顶山因夏禹足迹所至而有“禹贡蒙山”之称。以入贡“皇茶”而有“仙茶故乡”之名；以风景秀丽有“游览胜地”之誉。蒙山因雨雾蒙蒙而得名。蒙顶山山体长约10千米，宽约4千米。蒙顶五峰环列，状若莲花，最高峰上清峰，海拔1456米。景区由蒙顶山和百丈湖两个主景区组合而成。景区总面积54平方千米，核心面积15平方千米。蒙顶山风景区，是四川首批省级风景名...', '08:00-18:00', '约60元', 4.5, '茶文化,发源地,山林,茶山', '世界茶文化发源地，蒙顶茶香'),
(66, '碧峰峡', (SELECT `id` FROM `city` WHERE `name` = '雅安'), '自然', '5A', '四川省雅安市雨城区碧峰峡镇', 'https://baike.baidu.com/item/%E9%9B%85%E5%AE%89%E5%B8%82%E7%A2%A7%E5%B3%B0%E5%B3%A1%E6%97%85%E6%B8%B8%E6%99%AF%E5%8C%BA/64823780', 103.016398, 30.105502, '/images/scenic/bifengxia/bifengxia_cover.jpg', '雅安市碧峰峡旅游景区，简称碧峰峡旅游景区、碧峰峡景区（Bifeng Gorge Scenic Area），是位于四川省雅安市雨城区碧峰峡镇境内的旅游景区，景区占地面积20平方千米。碧峰峡景区由中国大熊猫保护研究中心碧峰峡基地、野生动物园和生态峡谷景区三部分组成。碧峰峡野生动物园规划面积10000亩，由猛兽车行观赏区（猛兽区）和温驯动物步行观光区（步行区）组成，是西南第一家野生动物园，也是中国第一家...', '08:30-17:00', '约118元', 4.6, '峡谷,大熊猫,瀑布,生态', '峡幽瀑美，大熊猫基地相伴'),
(67, '上里古镇', (SELECT `id` FROM `city` WHERE `name` = '雅安'), '古镇', '4A', '四川省雅安市雨城区上里镇', 'https://baike.baidu.com/item/%E4%B8%8A%E9%87%8C%E9%95%87/10981294', 103.076032, 30.180766, '/images/scenic/shangliguzhen/shangliguzhen_cover.jpg', '上里古镇，位于四川省雅安市雨城区北部，是国家AAAA级旅游景区和中国历史文化名镇。古镇古称“罗绳”，是历史上南方丝绸之路和茶马古道上的重要驿站。其街道呈“井”字形布局，明清风格的木结构建筑保存完好，以韩家大院、二仙桥、白马泉等为代表。1935年红军长征曾驻扎于此，留下了珍贵的石刻标语群。古镇因历史上韩、杨、陈、许、张五大家族聚居，又得名“五家口”，享有“四川十大古镇”之一的美誉。', '全天开放', '免费', 4.4, '古镇,茶马古道,石桥,田园', '茶马古道驿站，川西田园古镇'),
(68, '中国死海', (SELECT `id` FROM `city` WHERE `name` = '遂宁'), '亲子', '4A', '四川省遂宁市大英县中海大道888号', 'https://baike.baidu.com/item/%E4%B8%AD%E5%9B%BD%E6%AD%BB%E6%B5%B7/80400', 105.248890, 30.597799, '/images/scenic/zhongguosihai/zhongguosihai_cover.jpg', '遂宁市中国死海旅游度假区管理委员会成立于2019年11月，前身为大英县文化产业园区和大英县文化旅游产业园区，系正处级派出机构，驻地大英县城核心区及拓展区，总规划面积51平方公里，紧邻沪蓉高速大英出口。现任党工委副书记、管委会主任为王玉军。该机构负责度假区党建、纪检监察、政法协调及社会管理工作，统筹发展规划编制、招商引资、旅游资源开发与宣传营销，并承担基础设施建设、安全生产监管、生态环境保护及国有资...', '09:00-22:00', '约200元', 4.3, '漂浮,温泉,度假,亲子', '盐卤漂浮体验，休闲度假'),
(69, '安岳石刻·圆觉洞', (SELECT `id` FROM `city` WHERE `name` = '资阳'), '人文', '4A', '四川省资阳市安岳县岳城街道', 'https://baike.baidu.com/item/%E5%9C%86%E8%A7%89%E6%B4%9E/13141', 105.346157, 30.087310, '/images/scenic/anyueshikeyuanjuedong/anyueshikeyuanjuedong_cover.jpg', '圆觉洞风景名胜区位于四川省安岳县城东南1公里处的云居山上，为国家AAAA级旅游景区、全国重点文物保护单位。现存窟龛103个，造像1933躯，唐、五代、宋时期作品居多，以释迦、净瓶观音、莲花手观音三尊6米多高的大像最为壮观。景区内有宋代理学大师陈抟墓，现存“图南仙迹”“希夷炼丹处”等遗迹，墓前嵌立陈抟自赞碑及明代重建刻记。圆觉洞以造有十二圆觉而得名，佛家所谓“圆觉”即不分你我、人人都可觉醒成佛。景区...', '08:30-17:30', '约50元', 4.5, '石刻,石窟,唐宋,艺术', '唐宋石刻艺术宝库，造像精美'),
(70, '陈毅故里', (SELECT `id` FROM `city` WHERE `name` = '资阳'), '红色', '4A', '四川省资阳市乐至县劳动镇', 'https://sc.cri.cn/n/20230628/e0fa25bb-8acf-af5a-af6b-757eabc5a9be.html', 104.954623, 30.376886, '/images/scenic/chenyiguli/chenyiguli_cover.jpg', '陈毅故里景区位于四川省资阳市乐至县劳动镇，距县城7.8公里，是国家AAAA级旅游景区、全国红色旅游经典景区、全国爱国主义教育示范基地及国家国防教育基地，同时被列为省级廉政文化教育基地。景区核心景点包括全国重点文物保护单位陈毅故居、国家二级博物馆陈毅纪念馆及陈毅生平事迹陈列馆，其中故居为清代木质穿榫结构四合院，存有邓小平题写匾额和珍贵文物展陈，陈氏宗祠于2022年入选四川省第二批可移动革命文物名录。...', '09:00-17:00', '免费', 4.5, '红色旅游,名人故里,纪念,教育', '陈毅元帅故里，红色教育景点'),
(71, '隆昌石牌坊', (SELECT `id` FROM `city` WHERE `name` = '内江'), '人文', '4A', '四川省内江市隆昌市', 'https://baike.baidu.com/item/%E9%9A%86%E6%98%8C%E7%9F%B3%E7%89%8C%E5%9D%8A/4218104', 105.261704, 29.363736, '/images/scenic/longchangshipaifang/longchangshipaifang_cover.jpg', '隆昌石牌坊位于内江市隆昌市，是全国重点文物保护单位，现存明清石牌坊十余座，被誉为“中国石牌坊之乡”。这些牌坊或立于古驿道上，或藏于街巷民居间，雕刻精美、题材丰富，有德政坊、节孝坊、功德坊等多种类型，集中展现了明清时期的建筑艺术与礼制文化。漫步隆昌街头，可近距离欣赏这些“立体史书”，感受古城厚重的历史底蕴。', '08:30-17:30', '约40元', 4.4, '石牌坊,古建,明清,人文', '中国石牌坊之乡，明清牌坊群'),
(72, '嘉阳·桫椤湖', (SELECT `id` FROM `city` WHERE `name` = '乐山'), '人文', '4A', '四川省乐山市犍为县芭沟镇', 'https://baike.baidu.com/item/%E5%98%89%E9%98%B3%E6%A1%AB%E6%A4%A4%E6%B9%96%E6%99%AF%E5%8C%BA/22342634', 104.099686, 29.073389, '/images/scenic/jiayangsuoluohu/jiayangsuoluohu_cover.jpg', '嘉阳·桫椤湖景区位于乐山市犍为县，以运行着“工业革命活化石”——嘉阳蒸汽窄轨小火车和恐龙时代孑遗植物桫椤林而闻名。游客可乘着复古的蒸汽小火车穿行于山间田野，探访芭蕉沟老矿区，感受浓郁的年代气息；桫椤湖周边生长着大片桫椤，生态原始、空气清新。景区集工业遗产、怀旧体验与自然生态于一体，别具魅力。', '09:00-17:00', '约130元（含小火车）', 4.5, '蒸汽小火车,桫椤,工业遗产,怀旧', '工业革命活化石，蒸汽小火车'),
(73, '剑门关', (SELECT `id` FROM `city` WHERE `name` = '广元'), '人文', '5A', '四川省广元市剑阁县剑门关镇', 'https://baike.baidu.com/item/%E5%89%91%E9%97%A8%E5%85%B3/4466980', 105.567032, 32.212599, '/images/scenic/jianmenguan/jianmenguan_cover.jpg', '广元市剑门蜀道剑门关旅游景区，位于四川省广元市剑阁县北部，由剑门关、翠云廊两个紧邻的景区组成，是国家级风景名胜区、全国红色经典旅游景区、国家自然与文化双遗产，并列入《中国世界文化遗产预备名单》。剑门关景区面积84平方千米，核心区面积6平方千米。广元市剑门蜀道剑门关旅游景区地势西北高东南低，主要有峰丛形丹霞地貌，有世界罕见的城墙式砾岩断崖景观，其地貌特征可概括为“雄、险、峻、奇”。景区属亚热带湿润季...', '08:00-18:00', '约90元', 4.6, '蜀道,关隘,古柏,三国', '剑门天下险，古蜀道要冲'),
(74, '昭化古城', (SELECT `id` FROM `city` WHERE `name` = '广元'), '古镇', '4A', '四川省广元市昭化区昭化镇', 'https://baike.baidu.com/item/%E6%98%AD%E5%8C%96%E5%8F%A4%E5%9F%8E/10444437', 105.717326, 32.333078, '/images/scenic/zhaohuagucheng/zhaohuagucheng_cover.jpg', '昭化古城位于广元市昭化区，是中国历史文化名镇，古称葭萌，素有“巴蜀第一县”“蜀国第二都”之称。古城保存着完好的明清街巷、城门城墙与民居院落，三国文化底蕴深厚，张飞夜战马超、费祎墓等遗迹犹存。漫步青石板古街，可见古县衙、考棚、文庙等建筑，古朴静谧，是了解三国历史与川北古城风貌的经典目的地。', '全天开放', '免费', 4.4, '古城,三国,明清,古街', '巴蜀第一县，三国古城'),
(75, '皇泽寺', (SELECT `id` FROM `city` WHERE `name` = '广元'), '人文', '4A', '四川省广元市利州区皇泽路97号', 'https://baike.baidu.com/item/%E7%9A%87%E6%B3%BD%E5%AF%BA/781775', 105.840000, 32.445000, '/images/scenic/huangzesi/huangzesi_cover.jpg', '皇泽寺位于广元市利州区，是全国重点文物保护单位，也是中国唯一的女皇帝武则天祀庙。寺院依崖而建，保存有大量南北朝至唐宋的摩崖造像，其中以武则天石刻像最为著名，另有则天殿、写心经洞等古迹。寺内殿宇古朴、江景开阔，既可凭吊女皇生平，又能欣赏珍贵的石窟造像艺术，是广元最具代表性的历史文化名胜之一。', '08:30-17:30', '约50元', 4.5, '武则天,摩崖造像,古寺,人文', '中国唯一女皇祀庙，摩崖造像'),
(76, '明月峡', (SELECT `id` FROM `city` WHERE `name` = '广元'), '人文', '4A', '四川省广元市朝天区朝天镇', 'https://baike.baidu.com/item/%E6%98%8E%E6%9C%88%E5%B3%A1/8617985', 105.613186, 30.740883, '/images/scenic/mingyuexia/mingyuexia_cover.jpg', '明月峡位于四川广元嘉陵江西陵峡东段，面积 6.1 平方千米，距广元33千米左右。因峡两岸的山岩多呈银白色，并和青峰、江水相辉映，使整个峡江好像镀上了一层朦胧的月光，因此得名。明月峡，峡中多奇峰怪石：有山势嵯峨半插天的天柱峰，有宏丽幽深的黄颡洞，有茶圣陆羽称之为“天下第四泉”的蛤蟆碚，有腾空飞架的仙人桥，有裁云剪雾的青峰“三把刀”。', '08:30-17:30', '约60元', 4.4, '古栈道,峡谷,交通史,遗址', '中国交通史博物馆，古栈道'),
(77, '唐家河', (SELECT `id` FROM `city` WHERE `name` = '广元'), '自然', '4A', '四川省广元市青川县青溪镇', 'https://baike.baidu.com/item/%E5%94%90%E5%AE%B6%E6%B2%B3%E5%9B%BD%E5%AE%B6%E7%BA%A7%E8%87%AA%E7%84%B6%E4%BF%9D%E6%8A%A4%E5%8C%BA/8762239', 107.916764, 31.021592, '/images/scenic/tangjiahe/tangjiahe_cover.jpg', '唐家河风景区位于四川省广元市青川县，是国家AAAA级旅游景区，总面积40000公顷，其中森林面积17000公顷，属亚热带季风气候。1978年设立自然保护区，2011年创建国家AAAA级景区，以保护大熊猫、川金丝猴、扭角羚等珍稀野生动物为主要目标。该景区地处横断山脉北端向青藏高原过渡地带，海拔范围1150-3837米，保存有第四纪冰川遗留物种。区内高等植物达2629种，脊椎动物471种，包括珙桐、红...', '08:00-17:00', '约60元', 4.5, '自然保护区,大熊猫,森林,野趣', '大熊猫栖息地，原始森林野趣'),
(78, '曾家山', (SELECT `id` FROM `city` WHERE `name` = '广元'), '自然', '4A', '四川省广元市朝天区曾家镇', 'https://baike.baidu.com/item/%E6%9B%BE%E5%AE%B6%E5%B1%B1/8976806', 104.523427, 29.086010, '/images/scenic/cengjiashan/cengjiashan_cover.jpg', '曾家山景区位于广元市朝天区曾家镇。景区涵盖夏季平均气温23℃，负氧离子浓度最高达33000个/cm³，设有避暑季、冰雪季等主题活动。该景区自2021年起实施智慧旅游建设，构建“一中心三平台N应用”体系，涵盖智能停车、视频监控等服务。2022年贯通七盘关至曾家山旅游公路，开通环线公交，建成华美达、芷筑等高端酒店。2023年启动国家级旅游度假区创建工作，核心区面积26平方公里，承办大蜀道文化旅游节。2...', '08:30-17:30', '约60元', 4.4, '喀斯特,高山草甸,避暑,康养', '川北康养胜地，避暑高山草甸'),
(79, '阆中古城', (SELECT `id` FROM `city` WHERE `name` = '南充'), '古镇', '5A', '四川省南充市阆中市阆水中路33号', 'https://baike.baidu.com/item/%E9%98%86%E4%B8%AD%E5%8F%A4%E5%9F%8E/7504387', 105.968809, 31.575181, '/images/scenic/langzhonggucheng/langzhonggucheng_cover.jpg', '阆（làng）中古城，位于四川省南充市阆中市阆水中路33号，地处四川盆地东北缘、嘉陵江中游，古代巴国蜀国军事重镇，有中国春节文化之乡、“中国四大古城之一”称号。古城属亚热带湿润季风气候区，年均温度17℃，年均降水量1033.9毫米。阆中古城景区总面积4.59平方千米，古城核心区域2平方千米，有张飞庙、永安寺、五龙庙、滕王阁、观音寺、巴巴寺、大佛寺、川北道贡院等8处全国重点文物保护单位；有邵家湾墓群...', '全天开放', '免费（景点另收）', 4.6, '古城,风水,春节文化,明清', '中国四大古城之一，风水古城'),
(80, '朱德故里', (SELECT `id` FROM `city` WHERE `name` = '南充'), '红色', '5A', '四川省南充市仪陇县马鞍镇大湾路47号', 'https://sichuan.scol.com.cn/ggxw/202211/58755595.html', 106.608327, 31.459925, '/images/scenic/zhudeguli/zhudeguli_cover.jpg', '南充市朱德故里景区，是位于四川省南充市仪陇县马鞍镇的国家5A级旅游景区。景区总体规划面积52.5平方公里，核心景区5.6平方公里。朱德故里景区属中丘中谷地貌，海拔最高点关刀山657.75米，是一个与村民共生共融的开放式、原生态景区，景区由琳琅山、柏杨湖、蓬莱阁、插旗山景区和马鞍古镇五部分组成，核心景区由朱德故居、朱德同志故居纪念馆等核心景点组成。截止到2018年5月，景区有全国文物保护单位3处，省...', '09:00-17:00', '免费', 4.6, '红色旅游,元帅故里,纪念,教育', '朱德元帅故里，红色经典'),
(81, '七曲山', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '人文', '4A', '四川省绵阳市梓潼县文昌镇', 'https://baike.baidu.com/item/%E4%B8%83%E6%9B%B2%E5%B1%B1%E5%9B%BD%E5%AE%B6%E6%A3%AE%E6%9E%97%E5%85%AC%E5%9B%AD/4011989', 105.194524, 31.698193, '/images/scenic/qiqushan/qiqushan_cover.jpg', '七曲山国家森林公园位于四川省梓潼县七曲山，规划面积2346公顷，地理坐标为东经105°11′至105°15′2″、北纬31°40′40″至31°47′30″，距梓潼县城3-20公里，川陕公路贯穿全园，距绵阳57公里、成都177公里。公园1994年获评国家森林公园，属深丘地貌，海拔500-892米，森林覆盖率74%，以柏木、马尾松为主，现存野猪、麂子等野生动物。园内核心景观以"古文化、古道、古建筑、...', '08:30-17:30', '约50元', 4.5, '文昌文化,古建,祈福,古柏', '文昌帝君祖庭，祈福求学圣地'),
(82, '平武报恩寺', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '人文', '4A', '四川省绵阳市平武县龙安镇', 'https://baike.baidu.com/item/%E5%B9%B3%E6%AD%A6%E6%8A%A5%E6%81%A9%E5%AF%BA/10714489', 104.531476, 32.408790, '/images/scenic/pingwubaoensi/pingwubaoensi_cover.jpg', '平武报恩寺位于绵阳市平武县，是全国重点文物保护单位，始建于明代，被誉为“深山紫禁城”“明代建筑一绝”。全寺以珍贵的金丝楠木为主要建材，殿宇气势恢宏，斗拱飞檐、雕梁画栋，并保存有精美的彩塑、壁画与千手观音等，工艺精湛。寺内建筑融宫殿与寺庙风格于一体，规模宏大，是研究明代木构建筑与佛教艺术的珍贵实物。', '08:30-17:30', '约40元', 4.6, '古建筑,明代,彩塑,楠木', '深山紫禁城，明代木构精品'),
(83, '窦圌山', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '自然', '4A', '四川省绵阳市江油市武都镇', 'https://baike.baidu.com/item/%E7%BB%B5%E9%98%B3%E5%B8%82%E6%B1%9F%E6%B2%B9%E7%AA%A6%E5%9C%8C%E5%B1%B1%E9%A3%8E%E6%99%AF%E5%8C%BA/65662116', 104.808677, 31.909336, '/images/scenic/douchuanshan/douchuanshan_cover.jpg', '绵阳市江油窦圌（chuán）山风景区位于江油市武都镇境内。北距江油市区25公里，绵阳市区66公里、成都170余公里，交通便捷，属剑门蜀道国家级风景名胜区组成部分。景区核心面积1300余亩，规划面积5平方公里，主峰海拔1140米，相对高度608米，属典型砾岩丹霞地貌，三峰矗立形若画屏，岩体裸露呈丹赤色。其山峰分别名为东岳峰（亦称问月峰）、飞仙峰、神斧峰。景区以奇特山峰、铁索飞渡及云岩寺古建筑群著称，...', '08:30-17:30', '约70元', 4.4, '奇峰,铁索,丹霞,道教', '奇险山峰铁索飞渡，蜀中名山'),
(84, '九皇山', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '自然', '4A', '四川省绵阳市北川县桂溪镇', 'https://baike.baidu.com/item/%E8%A5%BF%E7%BE%8C%E4%B9%9D%E7%9A%87%E5%B1%B1%E6%99%AF%E5%8C%BA/17979584', 104.687412, 31.934640, '/images/scenic/jiuhuangshan/jiuhuangshan_cover.jpg', '西羌九皇山景区是国家AAAA级旅游景区，位于四川省绵阳市北川羌族自治县，开发面积25平方公里，海拔范围620-2840米。景区以羌族文化为核心，保留羌族建筑、工艺及婚俗等传统，建有猿王洞、情人桥、羌情园等景点，设置徒手逮猎场、高空滑道、绝壁栈道等体验项目，融合自然景观与民俗文化特色。属亚热带季风性湿润气候区，年均气温14.7℃-15.8℃，负氧离子浓度达80000个/立方厘米，涵盖喀斯特地貌、原始...', '08:00-17:30', '约90元', 4.4, '羌族文化,溶洞,辛夷花,体验', '羌文化风情，辛夷花海溶洞'),
(85, '江油李白故居', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '人文', '4A', '四川省绵阳市江油市青莲镇', 'https://baike.baidu.com/item/%E5%A4%AA%E7%99%BD%E6%95%85%E9%87%8C%E9%A3%8E%E6%99%AF%E5%90%8D%E8%83%9C%E5%8C%BA/15607511', 104.680281, 31.674937, '/images/scenic/jiangyoulibaiguju/jiangyoulibaiguju_cover.jpg', '太白故里风景名胜区位于四川省江油市青莲镇，为国家AAAA级旅游景区。景区由李白故居、李白纪念馆、太白碑林等组成，占地面积约500亩。此处为李白青少年时期居住地，李白5岁随父入蜀定居青莲并自号“青莲居士”。核心景点含省级文物保护单位陇西院、太白祠等。江油市坚持以李白文化为核心发展文旅产业，举办李白故里文化旅游节等活动。景区实行分时段开放。', '08:30-17:30', '约40元', 4.5, '李白,名人故里,文化,古建', '诗仙故里，陇西院太白祠'),
(86, '两弹城', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '红色', '4A', '四川省绵阳市梓潼县长卿镇', 'https://baike.baidu.com/item/%E4%B8%A4%E5%BC%B9%E5%9F%8E/16019504', 105.072637, 31.645793, '/images/scenic/liangdancheng/liangdancheng_cover.jpg', '两弹城（中国两弹城、两弹城景区），位于四川省绵阳市梓潼县文昌路南段988号（长卿山下），占地3000余亩，建筑面积20万平方米。1965年8月三线建设时期中国工程物理研究院（九院）内迁梓潼，在此相继完成原子弹、氢弹的设计方案，被称为“两弹城”，有王淦昌旧居、将军楼、邓稼先旧居、大礼堂、两弹历程馆、两弹城博物馆等文物建筑。两弹城先后获四川省党史学习教育基地、第八批全国重点文物保护单位、国防科技工业军...', '09:00-17:00', '约50元', 4.5, '红色,两弹一星,科技,教育', '两弹研制旧址，红色科教基地'),
(87, '光雾山', (SELECT `id` FROM `city` WHERE `name` = '巴中'), '自然', '5A', '四川省巴中市南江县光雾山镇', 'https://baike.baidu.com/item/%E5%B7%B4%E4%B8%AD%E5%B8%82%E5%85%89%E9%9B%BE%E5%B1%B1%E6%97%85%E6%B8%B8%E6%99%AF%E5%8C%BA/64844263', 106.807105, 32.667358, '/images/scenic/guangwushan/guangwushan_cover.jpg', '巴中市光雾山旅游景区，简称光雾山旅游区、光雾山景区（Guangwu Mountain Scenic Area），是位于四川省巴中市南江县光雾山镇境内的旅游景区，景区占地面积235平方千米（一说410平方千米）。“光雾”在地方方言表示“都是雾，全是雾”，因常年被雾气笼罩，因而得名光雾山。光雾山旅游区被称为“生物基因库、天然大氧吧”，生态环境类型多样，属秦巴生物多样性生态功能区，景区森林覆盖率达97%...', '07:30-18:00', '约90元', 4.7, '红叶,喀斯特,峰丛,摄影', '中国红叶第一山'),
(88, '诺水河', (SELECT `id` FROM `city` WHERE `name` = '巴中'), '自然', '4A', '四川省巴中市通江县诺水河镇', 'https://baike.baidu.com/item/%E8%AF%BA%E6%B0%B4%E6%B2%B3%E5%9B%BD%E5%AE%B6%E7%BA%A7%E9%A3%8E%E6%99%AF%E5%90%8D%E8%83%9C%E5%8C%BA/2694740', 107.183380, 32.322750, '/images/scenic/nuoshuihe/nuoshuihe_cover.jpg', '诺水河位于巴中市通江县，是世界地质公园，以规模宏大的喀斯特溶洞群著称。景区内中峰洞、狮子洞、楼房洞等溶洞景致神奇壮丽，钟乳石千姿百态、地下河幽深莫测，洞外则是峡谷、峰丛与飞瀑。诺水河集溶洞观光、地质科普与峡谷漂流于一体，被誉为“地下奇观”，是川东北极具特色的自然与地质旅游目的地。', '08:30-17:30', '约70元', 4.4, '溶洞,地质公园,喀斯特,漂流', '世界地质公园，溶洞群奇观'),
(89, '恩阳古镇', (SELECT `id` FROM `city` WHERE `name` = '巴中'), '古镇', '4A', '四川省巴中市恩阳区', 'https://baike.baidu.com/item/%E6%81%A9%E9%98%B3%E5%8F%A4%E9%95%87/6043898', 106.593172, 31.707720, '/images/scenic/enyangguzhen/enyangguzhen_cover.jpg', '恩阳古镇，位于中国四川省巴中市恩阳区，占地面积约2平方千米，距离巴中市区30分钟车程，距省会成都市324.3千米。与恩阳区中心区域隔河相望。恩阳古镇有四川省规模较大成片保存较为完好的明、清时代古建筑群，是观摩川东北独特民居最佳地。古镇内既有连接川陕的米仓古道，又有通达渝沪的古水码头；既有湖广、江西、福建等恢宏大气雄姿依然的客家会馆，又有义阳山、红梅阁、普贤寺、文治寨、千佛岩、登科寺、白云寺等一大批...', '全天开放', '免费', 4.3, '古镇,红色,明清,古街', '红色古镇，明清老街'),
(90, '巴山大峡谷', (SELECT `id` FROM `city` WHERE `name` = '达州'), '自然', '4A', '四川省达州市宣汉县渡口土家族乡', 'https://baike.baidu.com/item/%E5%B7%B4%E5%B1%B1%E5%A4%A7%E5%B3%A1%E8%B0%B7/18616541', 108.035562, 31.751197, '/images/scenic/bashandaxiagu/bashandaxiagu_cover.jpg', '中国·巴山大峡谷景区，位于川渝陕结合部达州市宣汉县东北边缘，是巴文化重要发祥地，四川省唯一的土家族聚居地，被誉为“中国巴文化之乡”“天然褶皱博物馆”和“大巴山生物基因库”。景区地处“中国南北气候的分界线”规划面积达29.87平方公里，森林覆盖率超80%，属喀斯特地貌。2020年，景区当选“成渝十大文旅产业地标”。游客可从达州汽车站乘直达班车前往，经包茂高速巴山大峡谷收费站，从达州城区自驾至景区只需...', '08:00-18:00', '约120元', 4.5, '峡谷,溶洞,土家风情,漂流', '川东大峡谷，土家风情浓'),
(91, '八台山', (SELECT `id` FROM `city` WHERE `name` = '达州'), '自然', '4A', '四川省达州市万源市八台镇', 'https://baike.baidu.com/item/%E5%85%AB%E5%8F%B0%E5%B1%B1/6203968', 108.218149, 31.930033, '/images/scenic/bataishan/bataishan_cover.jpg', '八台山（Batai Mountains）是四川省达州市万源市八台乡东部的国家AAAA级旅游景区和国家级自然遗产地，总面积120平方公里，主峰新八台海拔2272.3米，享有"巴山第二峰"美誉，因阶梯状递升八层地貌得名。作为国家级地质公园，其喀斯特地貌是中国南北方岩溶分界线，拥有四级剥蚀面等地质奇观。景区以日出、云海、佛光等气象景观闻名，被誉为“川东峨眉”和“迎接四川第一缕阳光的地方”。八台山属亚热带...', '08:00-18:00', '约80元', 4.5, '云海,日出,杜鹃,山岳', '高山云海日出，川东名山'),
(92, '华蓥山', (SELECT `id` FROM `city` WHERE `name` = '广安'), '自然', '4A', '四川省广安市华蓥市红岩乡', 'https://baike.baidu.com/item/%E5%8D%8E%E8%93%A5%E5%B1%B1/3361830', 107.115095, 30.773884, '/images/scenic/huayingshan/huayingshan_cover.jpg', '华蓥山位于广安市华蓥市，是川东著名的山岳景区，以喀斯特石林、溶洞和红色文化著称。山上奇石林立、溶洞幽深，植被茂密、气候凉爽，是夏季避暑的好去处。这里也是华蓥山游击队曾经战斗的地方，红色遗迹众多，革命故事广为流传。景区将自然奇观与红色文化融为一体，既可探访石林溶洞，又能接受革命传统教育。', '08:30-17:30', '约70元', 4.4, '石林,溶洞,红色,避暑', '喀斯特石林溶洞，红色文化'),
(93, '邓小平故里', (SELECT `id` FROM `city` WHERE `name` = '广安'), '红色', '5A', '四川省广安市广安区协兴镇', 'https://go.huanqiu.com/article/9CaKrnJCc7E', 106.636098, 30.519638, '/images/scenic/dengxiaopingguli/dengxiaopingguli_cover.jpg', '广安市邓小平故里旅游区位于四川省广安市广安区协兴镇，面积3.19平方公里，是集缅怀纪念、爱国主义教育、古镇文化、社会主义新农村展示、休闲度假于一体的复合型旅游景区。主要景点有邓小平故居、洗砚池、翰林院子、蚕房院子、北山小学堂、清水塘、神道碑、德政坊、古树坪等近20处邓小平童年及青少年时期活动场所；经中共中央批准修建的邓小平故居陈列馆、邓小平铜像广场、邓小平缅怀馆等纪念设施；展示社会主义新农村建设成...', '09:00-17:00', '免费', 4.7, '红色旅游,名人故里,纪念,教育', '小平故里，红色旅游经典'),
(94, '汶川特别旅游区', (SELECT `id` FROM `city` WHERE `name` = '阿坝'), '红色', '5A', '四川省阿坝州汶川县', 'https://baike.baidu.com/item/%E9%98%BF%E5%9D%9D%E8%97%8F%E6%97%8F%E7%BE%8C%E6%97%8F%E8%87%AA%E6%B2%BB%E5%B7%9E%E6%B1%B6%E5%B7%9D%E7%89%B9%E5%88%AB%E6%97%85%E6%B8%B8%E5%8C%BA/64869703', 103.488523, 31.054160, '/images/scenic/wenchuantebielvyouqu/wenchuantebielvyouqu_cover.jpg', '阿坝藏族羌族自治州汶川特别旅游区，简称汶川特别旅游区（Wenchuan Special Tourist Area），是位于四川省阿坝藏族羌族自治州汶川县境内的旅游景区。汶川特别旅游区是2008年“5·12汶川地震”重建后特别开发的纪念性和文化主题景区。旅游区涵盖汶川县南部的三江乡、映秀镇和水磨镇，由映秀地震遗址（又称震中映秀、天地映秀）、水磨古镇（又称水磨羌城、丹青水墨）、三江生态旅游区（又称三江...', '09:00-17:00', '免费（部分另收）', 4.6, '地震遗址,红色,纪念,羌藏', '5·12地震纪念地，灾后重建典范'),
(95, '北川羌城旅游区', (SELECT `id` FROM `city` WHERE `name` = '绵阳'), '人文', '5A', '四川省绵阳市北川县永昌镇', 'https://baike.baidu.com/item/%E7%BB%B5%E9%98%B3%E5%B8%82%E7%BE%8C%E5%9F%8E%E6%97%85%E6%B8%B8%E5%8C%BA/64823770', 104.462473, 31.593240, '/images/scenic/beichuanqiangchenglvyouqu/beichuanqiangchenglvyouqu_cover.jpg', '绵阳市羌城旅游区，又称绵阳市北川羌城旅游区，简称北川羌城旅游区（Beichuan Qiangcheng Tourist Area），是位于四川省绵阳市北川羌族自治县境内的旅游景区，总面积为6.01平方千米。北川羌城旅游区由两城（新县城巴拿恰、老县城）两馆（“5.12”汶川特大地震纪念馆、北川羌民俗博物馆）一寨（吉娜羌寨）一中心（游客中心）组成，分为地震纪念旅游景点、大爱文化旅游景点和禹羌文化旅游景...', '09:00-17:00', '部分免费', 4.5, '羌族文化,地震遗址,民俗,纪念', '全国唯一羌族自治县，羌文化'),
(96, '泸沽湖', (SELECT `id` FROM `city` WHERE `name` = '凉山'), '自然', '4A', '四川省凉山州盐源县泸沽湖镇', 'https://baike.baidu.com/item/%E6%B3%B8%E6%B2%BD%E6%B9%96/396555', 100.790904, 27.702886, '/images/scenic/luguhu/luguhu_cover.jpg', '凉山州泸沽湖旅游景区位于四川省盐源县泸沽湖镇，水域面积达31.2平方公里，占全湖总面积的2/3。景区以高原断层溶蚀陷落湖为核心，形成马蹄形湖盆地貌，现存15000亩草海湿地和18个摩梭原始村寨。作为摩梭文化核心载体，其走婚习俗、达巴文化等多项非物质文化遗产构成独特人文景观。该景区自2009年获评国家4A级景区以来，于2023年8月启动国家5A级旅游景区创建工作。', '全天开放', '70元', 4.7, '高原湖泊,摩梭文化,走婚,摄影', '东方女儿国，摩梭母系文化'),
(97, '邛海泸山', (SELECT `id` FROM `city` WHERE `name` = '凉山'), '自然', '4A', '四川省凉山州西昌市海滨中路', 'https://baike.baidu.com/item/%E9%82%9B%E6%B5%B7%E6%B3%B8%E5%B1%B1%E9%A3%8E%E6%99%AF%E5%90%8D%E8%83%9C%E5%8C%BA/62995081', 102.313737, 27.826488, '/images/scenic/qionghailushan/qionghailushan_cover.jpg', '邛海泸山风景名胜区位于中国最大的彝族自治州——四川省凉山彝族自治州首府西昌市，为国家AAAA级旅游景区，地理坐标为东经102°16′-102°20′，北纬27°47′-27°52′，山体面积6509km²，湖面面积31km²，形成山、水、城相依的独特景观。邛海是四川省境内最大湖泊之一，最大水深34米；泸山主峰海拔2317米，分布有九龙汉柏等珍稀植物，与邛海水面形成807米高差。20世纪因围海造田导...', '全天开放', '免费（泸山另收）', 4.5, '湖泊,湿地,阳光,度假', '四川第二大湖，阳光康养度假'),
(98, '螺髻山', (SELECT `id` FROM `city` WHERE `name` = '凉山'), '自然', '4A', '四川省凉山州普格县螺髻山镇', 'https://baike.baidu.com/item/%E8%9E%BA%E9%AB%BB%E5%B1%B1/2048353', 102.405534, 27.416715, '/images/scenic/luojishan/luojishan_cover.jpg', '螺髻山旅游景区，又名螺髻山风景区、螺髻山景区、螺髻山风景名胜区，景区位于四川省凉山彝族自治州普格县螺髻山镇，跨普格、德昌、西昌两县一市，是邛海—螺髻山风景名胜区组成部分，也是中国最大的彝族聚居区，拥有古朴的民俗风情、文化。螺髻山旅游景区面积1000余平方千米，主峰海拔4359米，海拔4000米以上的山峰高达72座，因其主峰高耸入云，形似青螺，宛若玉髻而得名螺髻山，名字来源于与峨眉山有“姊妹”关系。...', '08:30-17:30', '约60元', 4.5, '冰川遗迹,温泉瀑布,湖泊,山岳', '古冰川遗迹，温泉瀑布奇观'),
(99, '会理古城', (SELECT `id` FROM `city` WHERE `name` = '凉山'), '古镇', '4A', '四川省凉山州会理市', 'https://baike.baidu.com/item/%E4%BC%9A%E7%90%86%E5%8F%A4%E5%9F%8E/3393757', 102.244840, 26.661630, '/images/scenic/huiligucheng/huiligucheng_cover.jpg', '会理古城位于凉山州会理市，是中国历史文化名镇，保存着完好的明清古城格局。古城以钟鼓楼为中心，街巷纵横、民居古朴，城墙、古井、会馆与庙宇散布其间，融汇川滇风情。这里自古是南方丝绸之路上的重镇，商贸与文化交融，生活气息浓厚。漫步古城，可在老茶馆里品茶、尝石榴与鸡火丝饵块，感受悠闲而厚重的古城时光。', '全天开放', '免费', 4.4, '古城,明清,钟鼓楼,历史', '保存完好的明清古城'),
(100, '彝海', (SELECT `id` FROM `city` WHERE `name` = '凉山'), '红色', '4A', '四川省凉山州冕宁县彝海镇', 'https://baike.baidu.com/item/%E5%BD%9D%E6%B5%B7/6797125', 102.262819, 28.730214, '/images/scenic/yihai/yihai_cover.jpg', '彝海位于凉山州冕宁县，是彝族聚居区的一处高山淡水湖泊，更是著名的红色革命纪念地。1935年红军长征途中，刘伯承与彝族首领小叶丹在此歃血为盟，留下一段民族团结的佳话。景区由彝海湖、结盟纪念碑、纪念馆等组成，湖水清澈、山林环抱，红色文化与自然风光交融，是进行爱国主义教育与感受彝海结盟历史的经典景点。', '08:30-17:30', '约40元', 4.4, '红色,彝海结盟,彝族,纪念', '彝海结盟纪念地，红色经典')
