INSERT INTO `food` (`id`, `name`, `video_url`, `category`, `city_name`, `cover_image`, `description`, `history`, `spicy_level`, `recommend_index`, `avg_price`, `shop_name`, `shop_address`, `shop_longitude`, `shop_latitude`, `shop_image`) VALUES
(1, '冰粉', 'https://www.bilibili.com/video/BV1qQgz6TEBK/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '甜品', '成都', '/images/food/bingfen/bingfen_dish.jpg', '冰粉以冰粉子揉搓出浆凝固而成，晶莹剔透、冰凉爽滑，浇红糖汁、醪糟、山楂与葡萄干等配料，清甜解辣。夏日吃一碗，消暑又解辣，是川渝火锅与烧烤的最佳“伴侣”。冰凉爽口、甜而不腻，是川渝夏日的解辣佳品。', '以假酸浆冰粉子手工凝制而成', 1, 5, 10.00, '冰粉妹妹（建设路店）', '成都市成华区建设巷', 104.065818, 30.657443, '/images/food/bingfen/bingfen_shop.jpg'),
(2, '柴火鸡', 'https://www.bilibili.com/video/BV1wqbnzSEM5/', '火锅', '成都', '/images/food/chaihuoji/chaihuoji_dish.jpg', '柴火鸡以土灶柴火现炒现炖，土鸡配土豆、青椒与秘制酱料同焖，锅气十足、肉香浓郁。围灶而食，配以锅边贴玉米饼，质朴热闹，是川西乡村风味的代表，也是成都近郊农家乐的人气菜品。', '源自川西农家柴火土灶的烹饪方式', 3, 4, 90.00, '倪家桥柴火鸡（都江堰店）', '成都市都江堰市青城山镇', 104.065818, 30.657443, '/images/food/chaihuoji/chaihuoji_shop.jpg'),
(3, '崇州查渣面', 'https://www.bilibili.com/video/BV13CRyY9Evc/?', '面食', '成都', '/images/food/chongzhouchazhamian/chongzhouchazhamian_dish.jpg', '查渣面以酥脆的肉渣（酥肉）为臊，面条软滑，汤鲜味美、咸鲜微辣，酥肉嚼之香脆。制法独特、口感丰富，是成都崇州一带广受欢迎的地方特色面食。一碗下肚、酣畅满足，是四川人日常钟爱的味道。', '因以酥肉“渣”作臊而得名，崇州传统面食', 3, 4, 13.00, '崇州查渣面（老店）', '成都市崇州市崇阳街道', 104.065818, 30.657443, '/images/food/chongzhouchazhamian/chongzhouchazhamian_shop.jpg'),
(4, '川味凉面', 'https://www.bilibili.com/video/BV1w5411A7Si/?spm_id_from=333.337.search-card.all.click', '面食', '成都', '/images/food/chuanweiliangmian/chuanweiliangmian_dish.jpg', '川味凉面以面条煮后掸凉，抖散拌油，食时加红油、蒜泥、豆芽与调料，面条筋道、麻辣清爽，酸辣开胃。夏日一碗冰镇凉面，消暑又解馋，是川渝街头巷尾的经典小吃。汤面交融、麻辣鲜香，是四川街头随处可见的美味。', '川人夏日消暑面食，凉拌而食', 4, 4, 10.00, '老成都凉面摊（建设巷）', '成都市成华区建设巷', 104.065818, 30.657443, '/images/food/chuanweiliangmian/chuanweiliangmian_shop.jpg'),
(5, '串串香', 'https://www.bilibili.com/video/BV1ZF411r785/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/chuanchuanxiang/chuanchuanxiang_dish.jpg', '串串香是成都最具烟火气的小吃，将荤素食材穿成小串，在麻辣锅底中涮煮，按签计费。牛肉、毛肚、鸭肠、时蔬样样皆可成串，配干碟或油碟，丰俭由人、随吃随煮，是深夜街头的灵魂美食。', '起源于上世纪成都街头，由小贩挑担串卖而来', 5, 5, 60.00, '玉林串串香（玉林总店）', '成都市武侯区玉林横街3号', 104.065818, 30.657443, '/images/food/chuanchuanxiang/chuanchuanxiang_shop.jpg'),
(6, '担担面', 'https://www.bilibili.com/video/BV1RM4y1G75X/?', '面食', '成都', '/images/food/dandanmian/dandanmian_dish.jpg', '担担面因旧时小贩挑担沿街叫卖而得名，面条细薄、臊子酥香，配红油、花椒、蒜泥与碎米芽菜，麻辣鲜香、干爽少汤。一碗下肚，香醋与辣味交融，是成都面食的头牌。汤面交融、麻辣鲜香，是四川街头随处可见的美味。', '源于清道光年间小贩挑担沿街叫卖', 4, 5, 15.00, '担担面（总府路店）', '成都市锦江区总府路23号', 104.065818, 30.657443, '/images/food/dandanmian/dandanmian_shop.jpg'),
(7, '蛋烘糕', 'https://www.bilibili.com/video/BV1sW411r7ND/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/danhonggao/danhonggao_dish.jpg', '蛋烘糕以鸡蛋、面粉调浆，在铜锅上烤制，包入肉松、奶油、豆沙或芽菜肉末等馅，外皮金黄酥软，内馅咸甜自由。现烤现卖、香气四溢，是成都街头巷尾最受欢迎的小吃之一。老少皆宜、回味悠长，深受本地人与游客喜爱。', '清代由南京传入，经川人改良为蛋烘糕', 1, 4, 8.00, '蛋烘糕（宽窄巷子店）', '成都市青羊区窄巷子', 104.049627, 30.665185, '/images/food/danhonggao/danhonggao_shop.jpg'),
(8, '豆瓣鱼', 'https://www.bilibili.com/video/BV1Z9NyzQEVu/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/doubanyu/doubanyu_dish.jpg', '豆瓣鱼以鲜鱼配郫县豆瓣、泡椒、姜蒜烧制，鱼肉细嫩入味，汤汁红亮、微辣鲜香，鱼香与豆瓣香交融。集鲜、辣、香、嫩于一体，是川菜烧鱼的代表。麻辣鲜香、咸鲜适口，尽显川菜烹饪技艺的精妙。', '以郫县豆瓣入馔，川人烧鱼的经典做法', 3, 4, 68.00, '谭氏川菜馆（建设路店）', '成都市成华区建设路', 104.065818, 30.657443, '/images/food/doubanyu/doubanyu_shop.jpg'),
(9, '肥肠粉', 'https://www.bilibili.com/video/BV18Gf7B5EyL/?spm_id_from=333.337.search-card.all.click', '面食', '成都', '/images/food/feichangfen/feichangfen_dish.jpg', '肥肠粉以红苕粉为主，配软糯肥肠与酥黄豆、菜叶，浇红油与骨汤，粉条滑韧、肥肠软糯，麻辣鲜香。一碗下肚热气腾腾，是成都街头随处可见、慰藉肠胃的平民美食，常配锅盔同食。', '成都名小吃，红薯粉配肥肠而食', 4, 5, 12.00, '白家肥肠粉（总店）', '成都市二环路南三段', 104.065818, 30.657443, '/images/food/feichangfen/feichangfen_shop.jpg'),
(10, '粉蒸肉', 'https://www.bilibili.com/video/BV1c741177m5/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '川菜', '成都', '/images/food/fenzhengrou/fenzhengrou_dish.jpg', '粉蒸肉以五花肉裹蒸肉米粉，垫以红苕、南瓜或土豆蒸制，肉烂米香、软糯鲜香、咸鲜微辣。粉子吸满肉汁，荤素交融，是川味家常蒸菜的代表，口感丰收敦实。一菜一格、百菜百味，是川菜馆里经久不衰的经典。', '川式家常蒸菜，以米粉裹肉蒸制', 2, 4, 35.00, '宽窄巷子宽坐三楼川菜', '成都市青羊区宽巷子', 104.049627, 30.665185, '/images/food/fenzhengrou/fenzhengrou_shop.jpg'),
(11, '夫妻肺片', 'https://www.bilibili.com/video/BV1fX4y1V7eR/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/fuqifeipian/fuqifeipian_dish.jpg', '夫妻肺片以牛头皮、牛心、牛舌、牛肚等卤制切片，浇红油、花椒面、芝麻与花生碎凉拌，麻辣鲜香、软糯爽口、红亮油润。虽是牛杂凉菜，却做得精细考究，是成都最具代表性的川味凉菜之一。', '由成都郭朝华夫妇创制，取名“夫妻肺片”', 4, 5, 45.00, '夫妻肺片（总府路店）', '成都市锦江区总府路23号', 104.065818, 30.657443, '/images/food/fuqifeipian/fuqifeipian_shop.jpg'),
(12, '干煸四季豆', 'https://www.bilibili.com/video/BV1kT411T7z8/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/ganbiansijidou/ganbiansijidou_dish.jpg', '干煸四季豆将四季豆煸至虎皮起皱，配肉臊、芽菜、干辣椒同炒，豆角干香入味、麻辣咸鲜，口感酥嫩。简单家常却锅气十足，是川味餐桌上的下饭利器一菜一格、百菜百味，是川菜馆里经久不衰的经典。', '川菜干煸技法代表菜，家常风味经典', 3, 4, 28.00, '陈麻婆豆腐（骡马市店）', '成都市青羊区西玉龙街197号', 104.065818, 30.657443, '/images/food/ganbiansijidou/ganbiansijidou_shop.jpg'),
(13, '干锅肥肠', 'https://www.bilibili.com/video/BV12z4y127j9/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/ganguofeichang/ganguofeichang_dish.jpg', '干锅肥肠以肥肠与土豆、洋葱、青椒同炒，肥肠软糯入味、麻辣干香，锅底点火边加热边吃，越煮越香。荤素交融、下饭一绝，是川味干锅系列中的人气担当。荤素得宜、味型丰富，是川菜宴席与家常餐桌的常客。', '川味干锅代表，肥肠软糯干香', 4, 4, 50.00, '干锅传奇（春熙路店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/ganguofeichang/ganguofeichang_shop.jpg'),
(14, '宫保鸡丁', 'https://www.bilibili.com/video/BV1NMXTYKE6M/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/gongbaojiding/gongbaojiding_dish.jpg', '宫保鸡丁以鸡丁、花生米、干辣椒同炒，荔枝口味、甜酸微辣，鸡丁滑嫩、花生酥脆。色泽红亮、糊辣荔枝味突出，相传因清代四川总督丁宝桢（宫保）喜爱而得名，是闻名中外的川菜名品。', '相传为清代四川总督丁宝桢家厨所创', 3, 5, 40.00, '老码头火锅·川菜馆（宽窄巷子店）', '成都市青羊区窄巷子', 104.049627, 30.665185, '/images/food/gongbaojiding/gongbaojiding_shop.jpg'),
(15, '桂花糕', 'https://www.bilibili.com/video/BV1mP411n7tB/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '甜品', '成都', '/images/food/guihuagao/guihuagao_dish.jpg', '桂花糕以糯米或大米粉配糖桂花蒸制，糕体软糯，桂花香清雅、甜而不腻。切块而食，满口桂花香，是川中秋日应景的传统甜点，配盖碗茶更惬意。软糯香甜、抚慰肠胃，是川渝人钟爱的甜蜜滋味。', '中秋前后以桂花入糕，川地传统甜点', 1, 4, 8.00, '新都桂花糕（新都店）', '成都市新都区桂湖', 104.055564, 30.770301, '/images/food/guihuagao/guihuagao_shop.jpg'),
(16, '韩包子', 'https://www.bilibili.com/video/BV1PM4y1L7Go/?', '小吃', '成都', '/images/food/hanbaozi/hanbaozi_dish.jpg', '韩包子以发面做成，皮白壳薄、馅心鲜嫩，肉馅多汁、松软清香。分南虾、火腿、鲜肉等多种馅料，口味鲜咸适口，是成都与龙抄手、钟水饺齐名的传统小吃。街头巷尾随处可见，是成都烟火气里的经典小吃。', '创于1914年，创始人韩映斗，故称韩包子', 1, 4, 12.00, '韩包子（春熙路店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/hanbaozi/hanbaozi_shop.jpg'),
(17, '红糖糍粑', 'https://www.bilibili.com/video/BV1Vb411i7Vw/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '甜品', '成都', '/images/food/hongtangciba/hongtangciba_dish.jpg', '红糖糍粑以糯米蒸熟捣打成糍团，切块煎至外皮金黄，淋上热腾的红糖汁，外酥里糯、香甜诱人。既可作街头小吃，也是火锅店常见的解辣甜点，软糯香甜、人气极高。清甜解辣、老少皆宜，是川味餐桌上的甜蜜收尾。', '川渝常见小吃，红糖裹糍粑香甜', 1, 5, 12.00, '马旺子·红糖糍粑（锦里店）', '成都市武侯区武侯祠大街', 104.065818, 30.657443, '/images/food/hongtangciba/hongtangciba_shop.jpg'),
(18, '回锅肉', 'https://www.bilibili.com/video/BV1xa4y1U7Dx/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '川菜', '成都', '/images/food/huiguorou/huiguorou_dish.jpg', '回锅肉被誉为“川菜之首”，以二刀坐臀肉先煮后炒，配郫县豆瓣、豆豉、蒜苗爆炒，肉片灯盏窝、肥而不腻、咸鲜微辣。色泽红亮、香气扑鼻，是川渝家家会做、人人爱吃的家常头牌。', '源于民间祭祀后的“回锅”再炒，遂成经典', 3, 5, 40.00, '陈麻婆豆腐（青羊店）', '成都市青羊区西玉龙街', 104.065818, 30.657443, '/images/food/huiguorou/huiguorou_shop.jpg'),
(19, '荤豆花', 'https://www.bilibili.com/video/BV1Xa4y137u3/?', '小吃', '成都', '/images/food/hundouhua/hundouhua_dish.jpg', '荤豆花以嫩豆花配腊肉、酥肉、菌菇、青菜同煮，豆花绵软、汤鲜味浓，荤素兼备。蘸上香辣蘸水，麻辣鲜香、暖身开胃，是成都人冬日围炉的家常美食。价廉物美、风味独特，是川渝街头的常客。', '川人将豆花与荤料同煮的家常吃法', 3, 4, 30.00, '郑婆婆荤豆花（建设路店）', '成都市成华区建设路', 104.065818, 30.657443, '/images/food/hundouhua/hundouhua_shop.jpg'),
(20, '火锅冒菜', 'https://www.bilibili.com/video/BV1J54y1f7Ys/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/huoguomaocai/huoguomaocai_dish.jpg', '火锅冒菜以一人份的火锅汤底，将蔬菜、肉片、粉条等一同烫煮，装锅上桌、边煮边吃。既有火锅的麻辣浓郁，又省去多人围锅的麻烦，是快节奏生活中“一个人也能吃火锅”的惬意选择。', '火锅与冒菜结合的小份吃法，近年流行', 4, 4, 45.00, '蜀大侠小火锅冒菜（万象城店）', '成都市成华区双庆路8号', 104.065818, 30.657443, '/images/food/huoguomaocai/huoguomaocai_shop.jpg'),
(21, '家常豆腐', 'https://www.bilibili.com/video/BV1wP411G7gX/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/jiachangdoufu/jiachangdoufu_dish.jpg', '家常豆腐将豆腐煎至两面金黄，配肉片、青椒、豆瓣同烧，豆腐外酥里嫩、吸饱汁水，咸鲜微辣、家常可口。做法简单、味道淳厚，是川渝家庭餐桌上的下饭常客。一菜一格、百菜百味，是川菜馆里经久不衰的经典。', '川式家常烧豆腐，郫县豆瓣提味', 3, 4, 26.00, '陈麻婆豆腐（青羊店）', '成都市青羊区西玉龙街', 104.065818, 30.657443, '/images/food/jiachangdoufu/jiachangdoufu_shop.jpg'),
(22, '简阳羊肉汤', 'https://www.bilibili.com/video/BV1YsqfYHEbf/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/jianyangyangroutang/jianyangyangroutang_dish.jpg', '简阳羊肉汤以当地大耳羊炖制，汤色奶白、鲜而不腻，羊肉鲜嫩、膻味极轻。配以米线、锅盔同食，蘸干碟更香，暖身滋补，是四川人秋冬季最爱的暖胃汤锅，简阳“羊肉美食节”遐迩闻名。', '简阳自宋代养羊，羊肉汤闻名川内', 2, 4, 60.00, '简阳许师傅羊肉汤', '成都市简阳市简城街道', 104.065818, 30.657443, '/images/food/jianyangyangroutang/jianyangyangroutang_shop.jpg'),
(23, '九宫格火锅', 'https://www.bilibili.com/video/BV1sNH7zbEAb/', '火锅', '成都', '/images/food/jiugonggehuoguo/jiugonggehuoguo_dish.jpg', '九宫格火锅将锅底分为九格，中心火力最旺适合快涮毛肚鸭肠，边格适合久煮的土豆藕片，四角则用于焖煮老肉。一锅分格、各取所需，既讲究火候又充满仪式感，是老火锅的经典吃法。', '源于码头船工分格而食，避免食材混淆', 5, 5, 120.00, '小龙坎老火锅（春熙路店）', '成都市锦江区下东大街80号', 104.065818, 30.657443, '/images/food/jiugonggehuoguo/jiugonggehuoguo_shop.jpg'),
(24, '军屯锅盔', 'https://www.bilibili.com/video/BV1vS4y117W7/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/juntunguokui/juntunguokui_dish.jpg', '军屯锅盔出自彭州军屯镇，以面团抹油卷馅后煎烤，外皮千层酥脆、内里软韧，有鲜肉、卤肉、红糖等馅。一口咬下酥香掉渣，配肥肠粉同食更佳。老少皆宜、回味悠长，深受本地人与游客喜爱。', '源于彭州军屯，相传为古代军粮油饼演变', 2, 4, 8.00, '军屯锅盔（彭州老店）', '成都市彭州市军乐镇', 104.065818, 30.657443, '/images/food/juntunguokui/juntunguokui_shop.jpg'),
(25, '菌汤火锅', 'https://www.bilibili.com/video/BV1H2QKY4EoB/', '火锅', '成都', '/images/food/juntanghuoguo/juntanghuoguo_dish.jpg', '菌汤火锅以多种山珍菌菇熬制汤底，汤色清亮、菌香浓郁，鲜美回甘。锅底不辣，适合先喝汤再涮菜，搭配时蔬、豆腐与鲜肉，健康养生，是川内火锅中难得的清鲜之选，老少皆宜。', '依托川西高原丰富菌产，菌汤锅底应运而生', 2, 4, 100.00, '小龙翻大江火锅（绿地店）', '成都市武侯区天府大道北段1700号', 104.065818, 30.657443, '/images/food/juntanghuoguo/juntanghuoguo_shop.jpg'),
(26, '开水白菜', 'https://www.bilibili.com/video/BV1mS4y1Q7NR/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/kaishuibaicai/kaishuibaicai_dish.jpg', '开水白菜是川菜中的“清汤之首”，以老母鸡、干贝、火腿等吊制顶汤，汤清如水却鲜美无比，白菜嫩心入味、清淡不腻。看似朴素、实则极考功夫，体现了川菜“以清衬鲜”的高超技艺，为高级宴会名菜。', '相传为川菜大师黄敬临所创，登堂国宴', 1, 4, 180.00, '松云泽（锦江店）', '成都市锦江区滨江东路', 104.065818, 30.657443, '/images/food/kaishuibaicai/kaishuibaicai_shop.jpg'),
(27, '辣子鸡', 'https://www.bilibili.com/video/BV12X5h6MEZu/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/laziji/laziji_dish.jpg', '辣子鸡以鸡块与大量干辣椒、花椒同炒，鸡块炸至外酥里嫩，在辣椒堆中翻找鸡块别有一番乐趣。麻辣干香、越嚼越香，是川菜中重辣重香的代表作，佐酒下饭皆宜，人气长盛不衰。', '源自川东民间辣炒鸡块，后成名菜', 5, 5, 60.00, '大蓉和（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/laziji/laziji_shop.jpg'),
(28, '赖汤圆', 'https://www.bilibili.com/video/BV1Bx411V7mW/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/laitangyuan/laitangyuan_dish.jpg', '赖汤圆以糯米粉包黑芝麻馅为主，皮薄馅香、软糯香甜，煮后不浑汤、不粘牙。吃时蘸白糖芝麻，香甜细腻，是成都与龙抄手、钟水饺齐名的传统甜食小吃。老少皆宜、回味悠长，深受本地人与游客喜爱。', '创于清末，创始人赖元鑫，故名赖汤圆', 1, 4, 12.00, '赖汤圆（总府路店）', '成都市锦江区总府路23号', 104.065818, 30.657443, '/images/food/laitangyuan/laitangyuan_shop.jpg'),
(29, '醪糟粉子', 'https://www.bilibili.com/video/BV1wJ4m1P7xZ/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '甜品', '成都', '/images/food/laozaofenzi/laozaofenzi_dish.jpg', '醪糟粉子以糯米小圆子配醪糟（甜酒）煮制，再加鸡蛋与红糖，香甜暖胃、软糯微酸，酒香扑鼻。既可作早餐，也是川人待客的甜汤，尤其在节庆与产后滋补常见。冰凉爽口、甜而不腻，是川渝夏日的解辣佳品。', '川人冬季滋补甜汤，以醪糟煮粉子', 1, 4, 10.00, '宽窄巷子醪糟粉子', '成都市青羊区宽巷子', 104.049627, 30.665185, '/images/food/laozaofenzi/laozaofenzi_shop.jpg'),
(30, '老鸭汤火锅', 'https://www.bilibili.com/video/BV1f2hqzeEJu/', '火锅', '成都', '/images/food/laoyatanghuoguo/laoyatanghuoguo_dish.jpg', '老鸭汤火锅以老鸭配酸萝卜、泡姜慢炖，汤鲜味醇、酸香开胃，鸭肉酥烂脱骨。相较麻辣锅底，老鸭汤清淡滋补、温和不燥，适合秋冬进补与不善辣者，是川味火锅中的清润一脉。热辣翻滚、围锅共食，是川渝人聚餐待客的经典方式。', '酸萝卜老鸭汤本为民间滋补汤菜，后入火锅', 2, 4, 90.00, '老妈酸萝卜老鸭汤（一品天下店）', '成都市金牛区一品天下大街', 104.065818, 30.657443, '/images/food/laoyatanghuoguo/laoyatanghuoguo_shop.jpg'),
(31, '冷吃串串', 'https://www.bilibili.com/video/BV1JU4y1G7uD/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/lengchichuanchuan/lengchichuanchuan_dish.jpg', '冷吃串串与冷锅串串相近，食材煮熟后浸入冰镇红油汤底，麻辣中透着一丝清凉。荤素串串在冰汤中吸味，越吃越香，夏天食用尤为爽快，是成都夜市里消暑解馋的热门选择。随取随吃、麻辣过瘾，是川渝街头经久不衰的小吃。', '在冷锅串串基础上冰镇升级，夏夜走红', 4, 4, 50.00, '串场·冷吃串串（太古里店）', '成都市锦江区中纱帽街', 104.065818, 30.657443, '/images/food/lengchichuanchuan/lengchichuanchuan_shop.jpg'),
(32, '冷锅串串', 'https://www.bilibili.com/video/BV1ZF411r785/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/lengguochuanchuan/lengguochuanchuan_dish.jpg', '冷锅串串将食材预煮后浸入调好的红油藤椒汤底，上桌即食、无需再煮。汤底麻辣鲜香，冷吃更入味，爽口不烫，尤其适合夏日。配一碗冰粉，冷热相宜，是成都人的消暑神器。随取随吃、麻辣过瘾，是川渝街头经久不衰的小吃。', '为便食客免于久等，店家先煮后浸创出冷锅吃法', 4, 5, 50.00, '冷串苗·冷锅串串（建设路店）', '成都市成华区建设巷', 104.065818, 30.657443, '/images/food/lengguochuanchuan/lengguochuanchuan_shop.jpg'),
(33, '廖记棒棒鸡', 'https://www.bilibili.com/video/BV1dv411E7x7/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/liaojibangbangji/liaojibangbangji_dish.jpg', '廖记棒棒鸡以嫩鸡肉撕条后淋特制红油藤椒汁，鸡肉鲜嫩、麻辣鲜香，色泽红亮。源自乐山，以鸡肉用木棒敲松入味而得名，如今已是川渝街头热销的招牌凉菜。价廉物美、风味独特，是川渝街头的常客。', '源自乐山，以木棒敲打鸡肉入味而得名', 4, 4, 35.00, '廖记棒棒鸡（春熙路店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/liaojibangbangji/liaojibangbangji_shop.jpg'),
(34, '龙抄手', 'https://www.bilibili.com/video/BV1BY411b7eh/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/longchaoshou/longchaoshou_dish.jpg', '龙抄手是成都著名小吃，以面皮包鲜肉馅，皮薄馅嫩、汤清味鲜，配清汤、红油或奶茶味汁。创始于上世纪四十年代，以“薄如纸、细如绸”闻名，是成都小吃代表之一。价廉物美、风味独特，是川渝街头的常客。', '创于1941年，创始人以“龙”字取名寓意吉祥', 2, 5, 20.00, '龙抄手（春熙路总店）', '成都市锦江区春熙路南段6号', 104.065818, 30.657443, '/images/food/longchaoshou/longchaoshou_shop.jpg'),
(35, '麻辣牛肉干', 'https://www.bilibili.com/video/BV1by4y1s7Ap/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '成都', '/images/food/malaniurougan/malaniurougan_dish.jpg', '麻辣牛肉干以牛肉经卤、切、炒、烘多道工序制成，色泽红亮、麻辣干香，嚼劲十足、越嚼越香。既是下酒佐餐的硬菜，也是便于携带的川味特产，深受食客喜爱。街头巷尾随处可见，是成都烟火气里的经典小吃。', '川人善制牛肉干，麻辣味为经典', 4, 4, 35.00, '张飞牛肉（成都总店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/malaniurougan/malaniurougan_shop.jpg'),
(36, '麻辣烫', 'https://www.bilibili.com/video/BV1xJ4m1L7Z3/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/malatang/malatang_dish.jpg', '麻辣烫将各式食材穿串或按份，在麻辣汤底中煮熟，装碗淋汤，可按串或按份售卖。相较火锅更为随性便捷，麻辣鲜香、价廉物美，是学生与上班族钟爱的平价川味小吃。荤素自由搭配、按签计费，是成都夜市的灵魂美食。', '由川江船工的麻辣烫食法演变而来', 4, 4, 30.00, '张亮麻辣烫（成都春熙路店）', '成都市锦江区春熙路北段', 104.065818, 30.657443, '/images/food/malatang/malatang_shop.jpg'),
(37, '麻辣香锅', 'https://www.bilibili.com/video/BV1ym4y1R7QX/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/malaxiangguo/malaxiangguo_dish.jpg', '麻辣香锅将荤素食材与辣椒、花椒、香料一同炒制，一锅麻辣鲜香、香气扑鼻，可按喜好自由搭配。麻、辣、干、香，既像干锅又像火锅，是学生与年轻人聚餐的热门选择。一菜一格、百菜百味，是川菜馆里经久不衰的经典。', '川式干锅与火锅结合的流行吃法', 5, 4, 50.00, '麻辣香锅（建设路店）', '成都市成华区建设路', 104.065818, 30.657443, '/images/food/malaxiangguo/malaxiangguo_shop.jpg'),
(38, '麻辣小龙虾', 'https://www.bilibili.com/video/BV1J64y1d7ty/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/malaxiaolongxia/malaxiaolongxia_dish.jpg', '麻辣小龙虾以小龙虾配辣椒、花椒、香料重料卤烧，虾肉紧实弹牙、麻辣鲜香、越吃越上瘾。配着啤酒与好友畅饮畅食，是川渝夜宵摊上最具人气的“宵夜之王”。一菜一格、百菜百味，是川菜馆里经久不衰的经典。', '川人重料卤制，成川渝夏夜宵夜招牌', 5, 5, 80.00, '青石桥麻辣小龙虾（青石桥店）', '成都市锦江区青石桥', 104.096924, 30.627015, '/images/food/malaxiaolongxia/malaxiaolongxia_shop.jpg'),
(39, '麻婆豆腐', 'https://www.bilibili.com/video/BV1BC4y1471h/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '川菜', '成都', '/images/food/mapodoufu/mapodoufu_dish.jpg', '麻婆豆腐是川菜经典，豆腐嫩滑、牛肉臊酥香，配以豆瓣、花椒与辣椒烧制，集麻、辣、烫、香、酥、嫩、鲜于一体。红亮油润、麻辣鲜香，拌饭一绝，是川菜“一菜一格”的杰出代表，享誉海内外。', '清同治年间陈麻婆首创于成都万福桥畔', 4, 5, 30.00, '陈麻婆豆腐（骡马市店）', '成都市青羊区西玉龙街197号', 104.065818, 30.657443, '/images/food/mapodoufu/mapodoufu_shop.jpg'),
(40, '毛肚火锅', 'https://www.bilibili.com/video/BV1NunmzLEbF/', '火锅', '成都', '/images/food/maoduhuoguo/maoduhuoguo_dish.jpg', '毛肚火锅以脆嫩毛肚为核心，讲究“七上八下”涮烫，入口爽脆弹牙。锅底麻辣厚重，蘸以香油蒜泥，最大限度激发出毛肚本身的鲜香，是川味火锅中点击率最高的经典搭配。围炉而食、越煮越香，是川渝夜宵桌上的常客。', '毛肚为码头火锅最早的下水食材之一', 5, 5, 130.00, '马路边边麻辣烫（建设路店）', '成都市成华区建设路26号', 104.065818, 30.657443, '/images/food/maoduhuoguo/maoduhuoguo_shop.jpg'),
(41, '毛血旺', 'https://www.bilibili.com/video/BV1XY41157Xz/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/maoxuewang/maoxuewang_dish.jpg', '毛血旺以鸭血、毛肚、黄喉、午餐肉等为料，配麻辣红汤烩煮，血旺嫩滑、荤料丰富，麻辣烫鲜、汤汁红亮。一锅之中荤素兼备、热辣过瘾，发源于重庆磁器口、流行于川渝的江湖名菜。', '源于重庆磁器口码头，由贩卖杂碎发明', 5, 5, 60.00, '干锅传奇（春熙路店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/maoxuewang/maoxuewang_shop.jpg'),
(42, '冒菜', 'https://www.bilibili.com/video/BV1ny4y1Z7t9/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/maocai/maocai_dish.jpg', '冒菜被称为“一个人的火锅”，将蔬菜、肉片、豆制品等按份放入竹篓，在麻辣汤底中烫熟，装碗后淋红油与蒜泥。荤素自由搭配，麻辣鲜香、汤宽味浓，一人一碗也能吃出火锅的酣畅。', '由火锅简化为一人份而来，流行于成都街头', 4, 5, 30.00, '冒椒火辣冒菜（春熙店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/maocai/maocai_shop.jpg'),
(43, '牛油火锅', 'https://www.bilibili.com/video/BV1iA4114774/', '火锅', '成都', '/images/food/niuyouhuoguo/niuyouhuoguo_dish.jpg', '牛油火锅以整块牛油炒制底料，配以二荆条辣椒与汉源花椒，浓郁醇厚、麻辣厚重，冷却后凝成红油块。相较清油锅底，牛油更能锁住香味，越煮越香，是重口味食客的最爱。红汤翻滚、香气四溢，尽显川渝火锅的酣畅江湖。', '牛油锅底在重庆码头兴起，后传入成都风靡全川', 5, 5, 130.00, '大龙燚火锅（蜀都店）', '成都市锦江区红星路三段1号', 104.065818, 30.657443, '/images/food/niuyouhuoguo/niuyouhuoguo_shop.jpg'),
(44, '泡椒鸡杂', 'https://www.bilibili.com/video/BV1C44y1o7JF/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/paojiaojiza/paojiaojiza_dish.jpg', '泡椒鸡杂以鸡胗、鸡肠、鸡肝等与泡椒、泡姜同炒，酸辣开胃、鲜香脆嫩，泡椒的酸香与鸡杂的脆弹相得益彰。色泽红亮、下饭一绝，是川味江湖菜中极受欢迎的一道。麻辣鲜香、咸鲜适口，尽显川菜烹饪技艺的精妙。', '以川泡菜入馔，江湖菜经典做法', 4, 4, 45.00, '老妈蹄花（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/paojiaojiza/paojiaojiza_shop.jpg'),
(45, '泡椒牛蛙', 'https://www.bilibili.com/video/BV1zT421a7BA/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/paojiaoniuwa/paojiaoniuwa_dish.jpg', '泡椒牛蛙以牛蛙肉配泡椒、泡姜同炒，肉质雪白滑嫩、酸辣鲜香，泡椒的酸香与牛蛙的鲜嫩相得益彰。蛙肉嫩滑、酸辣开胃，是川味江湖菜中极受欢迎的一道。荤素得宜、味型丰富，是川菜宴席与家常餐桌的常客。', '以川泡椒入馔，牛蛙嫩滑酸辣', 4, 4, 65.00, '老妈蹄花（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/paojiaoniuwa/paojiaoniuwa_shop.jpg'),
(46, '邛崃奶汤面', 'https://www.bilibili.com/video/BV1Sb4y1M7Eq/?spm_id_from=333.337.search-card.all.click', '面食', '成都', '/images/food/qionglainaitangmian/qionglainaitangmian_dish.jpg', '邛崃奶汤面以猪骨、鸡骨熬制奶白色的酽汤，面条滑爽，汤鲜味醇、奶香扑鼻，配以臊子与甑子饭更香。一清二白的奶汤面温润养人，是邛崃清晨最受欢迎的传统面食。汤面交融、麻辣鲜香，是四川街头随处可见的美味。', '邛崃传统面食，以奶白高汤得名', 2, 4, 12.00, '邛崃奶汤面（老店）', '成都市邛崃市文君街道', 104.065818, 30.657443, '/images/food/qionglainaitangmian/qionglainaitangmian_shop.jpg'),
(47, '三大炮', 'https://www.bilibili.com/video/BV1AsMnzKEhc/?', '小吃', '成都', '/images/food/sandapao/sandapao_dish.jpg', '三大炮以糯米蒸熟捣打成糍团，抛掷于放有钢盘的案上，发出“当当当”三声，故得名。糍团表软糯，裹上炒香黄豆粉，淋红糖汁，香甜软糯、有趣好看，是成都庙会上最吸眼的甜食。', '因抛打时发三声响而得名，庙会名小吃', 1, 4, 10.00, '三大炮（宽窄巷子店）', '成都市青羊区宽巷子', 104.049627, 30.665185, '/images/food/sandapao/sandapao_shop.jpg'),
(48, '伤心凉粉', 'https://www.bilibili.com/video/BV1BW411q7W1/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/shangxinliangfen/shangxinliangfen_dish.jpg', '伤心凉粉是洛带古镇名小吃，以豌豆凉粉浇极辣的红油与小米椒，辣得让人流泪如伤心，故得名。粉嫩爽滑、麻辣无比，勇气可嘉者不妨一试，是川味辣度的极致体验。价廉物美、风味独特，是川渝街头的常客。', '因辣到催人泪下而得名，洛带古镇招牌', 5, 4, 10.00, '客家伤心凉粉（洛带店）', '成都市龙泉驿区洛带古镇', 104.065818, 30.657443, '/images/food/shangxinliangfen/shangxinliangfen_shop.jpg'),
(49, '双流老妈兔头', 'https://www.bilibili.com/video/BV1KyetzdEur/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '小吃', '成都', '/images/food/shuangliulaomatutou/shuangliulaomatutou_dish.jpg', '双流老妈兔头以卤制兔头为招牌，分麻辣与五香两味，肉质鲜美、麻辣入味，啃着有味的兔头更是成都人最爱的零食。俗话说“没吃过兔头就不算了解四川”，足见其地位。老少皆宜、回味悠长，深受本地人与游客喜爱。', '源于双流，因创始人“老妈”而得名', 4, 5, 15.00, '双流老妈兔头（总店）', '成都市双流区升平街', 104.090904, 30.558000, '/images/food/shuangliulaomatutou/shuangliulaomatutou_shop.jpg'),
(50, '水煮肉片', 'https://www.bilibili.com/video/BV1DK4y1M7eZ/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/shuizhuroupian/shuizhuroupian_dish.jpg', '水煮肉片以猪里脊切片上浆，垫以菜心、豆芽，浇麻辣红汤，肉片滑嫩、麻辣鲜香，汤面铺满辣椒花椒。趁热食用，麻辣烫鲜、肉嫩汤香，是川菜家常与水煮系列中的经典之作。荤素得宜、味型丰富，是川菜宴席与家常餐桌的常客。', '由水煮牛肉演变而来，肉片版同样风靡', 5, 5, 55.00, '大蓉和（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/shuizhuroupian/shuizhuroupian_shop.jpg'),
(51, '水煮鱼', 'https://www.bilibili.com/video/BV1qY411j7Nw/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/shuizhuyu/shuizhuyu_dish.jpg', '水煮鱼以鲜鱼片在红油辣汤中汆烫，鱼片雪白滑嫩，汤面铺满辣椒与花椒，麻辣鲜香、油而不腻。鱼肉嫩滑入味，趁热浇油“滋滋”作响，香气四溢，是川菜中极具冲击力的经典大菜。', '起源川东渔家，后经餐馆改良风靡全国', 5, 5, 80.00, '大蓉和水煮鱼（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/shuizhuyu/shuizhuyu_shop.jpg'),
(52, '四川火锅', 'https://www.bilibili.com/video/BV18eGW6nE7r/', '火锅', '成都', '/images/food/sichuanhuoguo/sichuanhuoguo_dish.jpg', '四川火锅以牛油、花椒、辣椒熬制红汤锅底，麻辣鲜香、汤色红亮，是川渝饮食的灵魂代表。涮品从毛肚、鸭肠到黄喉、午餐肉无所不包，配以香油蒜泥碟，热气腾腾、酣畅淋漓，是成都人聚餐待客的首选。', '火锅源于长江码头船工的粗放饮食，后经川人改良定型', 5, 5, 120.00, '蜀九香火锅（天府店）', '成都市武侯区天府大道北段1480号', 104.065818, 30.657443, '/images/food/sichuanhuoguo/sichuanhuoguo_shop.jpg'),
(53, '素椒杂酱面', 'https://www.bilibili.com/video/BV1XY4y1G771/?spm_id_from=333.337.search-card.all.click', '面食', '成都', '/images/food/sujiaozajiangmian/sujiaozajiangmian_dish.jpg', '素椒杂酱面以肉臊配素椒油与芝麻酱，面条劲道，麻辣鲜香中带着芝麻酱的醇香，素椒的清香解腻提味。成都方言中“素椒”指辣椒，“杂酱”为肉臊，二者相搭咸鲜爽口，是面馆点单率极高的经典。', '成都面馆经典，素椒与杂酱搭配而成', 4, 4, 12.00, '老王杂酱面（建设路店）', '成都市成华区建设路', 104.065818, 30.657443, '/images/food/sujiaozajiangmian/sujiaozajiangmian_shop.jpg'),
(54, '酸辣粉', 'https://www.bilibili.com/video/BV1D7411p7z9/?spm_id_from=333.337.search-card.all.click', '面食', '成都', '/images/food/suanlafen/suanlafen_dish.jpg', '酸辣粉以红薯粉为主，配酸醋、辣椒油、花生、榨菜与豆芽，粉条筋道、酸辣开胃，酸香与辣香交融。麻、辣、鲜、香、酸、烫于一碗，是四川街头人气极高的小吃面食。一碗下肚、酣畅满足，是四川人日常钟爱的味道。', '川渝街头经典小吃，以酸辣见长', 4, 5, 10.00, '好又来酸辣粉（春熙路店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/suanlafen/suanlafen_shop.jpg'),
(55, '蒜泥白肉', 'https://www.bilibili.com/video/BV1V7411m738/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/suannibairou/suannibairou_dish.jpg', '蒜泥白肉以带皮二刀肉煮后切薄片，浇蒜泥、红油、复制酱油调成的味汁，肉片肥瘦相间、肥而不腻，蒜香浓郁、咸鲜微辣。色白肉嫩、蒜香扑鼻，是川菜凉菜中的经典，配饭下酒皆相宜。', '由满族白肉传入川地后加蒜泥红油改造而成', 3, 4, 38.00, '陈麻婆豆腐（青羊店）', '成都市青羊区西玉龙街', 104.065818, 30.657443, '/images/food/suannibairou/suannibairou_shop.jpg'),
(56, '坛子肉', 'https://www.bilibili.com/video/BV1t14y1m7CN/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/tanzirou/tanzirou_dish.jpg', '坛子肉以五花肉油炸后装入坛罐，配干豇豆、五香白豆或渣海椒封坛焖煨，肉质粑糯、肥而不腻，带有坛存特有的醇香。一坛慢煨、香气内敛，是川西民间保存肉食与风味的智慧，家常又地道。', '川西民间以坛罐炖焖存肉的技法流传至今', 2, 4, 50.00, '宽窄巷子宽坐三楼川菜', '成都市青羊区宽巷子', 104.049627, 30.665185, '/images/food/tanzirou/tanzirou_shop.jpg'),
(57, '糖醋排骨', 'https://www.bilibili.com/video/BV1bk4y167qZ/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/tangcupaigu/tangcupaigu_dish.jpg', '糖醋排骨以猪肋排先炸后烧，裹上糖醋汁，色泽红亮、酸甜可口，外香里嫩、骨肉酥软。甜酸风味老少皆宜，是川菜中颇受欢迎的经典家常菜，宴会与家宴皆常见。麻辣鲜香、咸鲜适口，尽显川菜烹饪技艺的精妙。', '川菜糖醋味代表，酸甜适口老少皆宜', 1, 4, 45.00, '陈麻婆豆腐（青羊店）', '成都市青羊区西玉龙街', 104.065818, 30.657443, '/images/food/tangcupaigu/tangcupaigu_shop.jpg'),
(58, '糖油果子', 'https://www.bilibili.com/video/BV1FV411g7y7/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/tangyouguozi/tangyouguozi_dish.jpg', '糖油果子以糯米粉团油炸后裹红糖糖浆，外酥里糯、色泽棕红，撒上白芝麻，香甜可口、颗颗圆润。串成串状，是成都街头常见的小吃，香糯甜润，老少皆爱。街头巷尾随处可见，是成都烟火气里的经典小吃。', '成都街头传统甜食，以红糖裹炸而成', 1, 4, 6.00, '糖油果子（锦里店）', '成都市武侯区武侯祠大街', 104.065818, 30.657443, '/images/food/tangyouguozi/tangyouguozi_shop.jpg'),
(59, '甜水面', 'https://www.bilibili.com/video/BV1Xv411W7Pu/?spm_id_from=333.337.search-card.all.click', '面食', '成都', '/images/food/tianshuimian/tianshuimian_dish.jpg', '甜水面以粗条面条为主，滑爽劲道，淋红油、复制酱油、蒜泥与芝麻酱调成的甜辣酱汁，回甜微辣、醇香顺口。面条粗美、滋味浓烈，是成都小吃面食里的经典，甜咸党都能接受。一碗下肚、酣畅满足，是四川人日常钟爱的味道。', '成都传统小吃面食，以甜辣风味独树一帜', 3, 5, 15.00, '甜水面（宽窄巷子店）', '成都市青羊区窄巷子', 104.049627, 30.665185, '/images/food/tianshuimian/tianshuimian_shop.jpg'),
(60, '五香兔头', 'https://www.bilibili.com/video/BV1Hk4y1m7GM/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '小吃', '成都', '/images/food/wuxiangtutou/wuxiangtutou_dish.jpg', '五香兔头以八角、桂皮等香料卤制，兔头麻辣鲜香、五香入味，肉质紧实、越啃越香。麻辣与五香两种口味各有拥趸，是成都夜市里下酒解闷的招牌小吃。街头巷尾随处可见，是成都烟火气里的经典小吃。', '成都人喜食兔头，卤制而成的小吃', 3, 4, 12.00, '王妈手撕烤兔（玉林店）', '成都市武侯区玉林南街', 104.058669, 30.628802, '/images/food/wuxiangtutou/wuxiangtutou_shop.jpg'),
(61, '咸烧白', 'https://www.bilibili.com/video/BV1q96YBdESK/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/xianshaobai/xianshaobai_dish.jpg', '咸烧白为川式扣肉，以五花肉与芽菜蒸制，肉片酥软化渣、肥而不腻，芽菜咸香入味。肉皮油亮、咸鲜醇厚，是川味“九大碗”中的经典蒸菜，逢年过节餐桌必备。荤素得宜、味型丰富，是川菜宴席与家常餐桌的常客。', '川西九大碗名菜，蒸制扣肉代表', 2, 4, 45.00, '宽窄巷子宽坐三楼川菜', '成都市青羊区宽巷子', 104.049627, 30.665185, '/images/food/xianshaobai/xianshaobai_shop.jpg'),
(62, '香辣虾', 'https://www.bilibili.com/video/BV1gx4y1F7cS/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/xianglaxia/xianglaxia_dish.jpg', '香辣虾以鲜虾与干辣椒、花椒同炒，虾肉鲜嫩弹牙、麻辣鲜香、色泽红亮。配以土豆、黄瓜同炒，香辣入味、下饭下酒皆宜，是川味江湖菜中极受欢迎的菜品。麻辣鲜香、咸鲜适口，尽显川菜烹饪技艺的精妙。', '川味江湖菜，以香辣炒虾风靡川渝', 4, 4, 70.00, '大蓉和（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/xianglaxia/xianglaxia_shop.jpg'),
(63, '小郡肝串串', 'https://www.bilibili.com/video/BV16i4y1777p/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/xiaojunganchuanchuan/xiaojunganchuanchuan_dish.jpg', '小郡肝串串以爽脆的鸡胗（郡肝）为招牌，配以牛肉、郡把等，穿串入麻辣锅底涮煮，涮几秒即熟，脆嫩弹牙。按签计费、随取随涮，配干碟蘸食，麻辣过瘾，是成都串串的热门品类。', '以郡肝为招牌，兴起于成都钢管厂五区', 5, 5, 60.00, '钢管厂五区小郡肝串串香', '成都市成华区建设路', 104.065818, 30.657443, '/images/food/xiaojunganchuanchuan/xiaojunganchuanchuan_shop.jpg'),
(64, '叶儿粑', 'https://www.bilibili.com/video/BV12E411r72b/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/yeerba/yeerba_dish.jpg', '叶儿粑以糯米粉包馅，外用粽叶包裹蒸制，呈青绿色，糯米软糯、馅心咸鲜带清香。有肉馅与芝麻馅两种，带叶清香、软糯适口，是川西一带逢年过节与街头常见的传统小吃。价廉物美、风味独特，是川渝街头的常客。', '川西传统小吃，以粽叶包蒸而得名', 2, 4, 8.00, '叶儿粑（宽窄巷子店）', '成都市青羊区宽巷子', 104.049627, 30.665185, '/images/food/yeerba/yeerba_shop.jpg'),
(65, '银耳羹', 'https://www.bilibili.com/video/BV12f4y197Rf/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '甜品', '成都', '/images/food/yinergeng/yinergeng_dish.jpg', '银耳羹以银耳、红枣、枸杞、薏米等慢炖成胶，浓稠清甜、润燥养颜。冰镇后食用清凉爽口，是川渝餐馆与甜品店里解辣润喉、滋补养生的经典甜汤。清甜解辣、老少皆宜，是川味餐桌上的甜蜜收尾。', '川人炖制银耳的传统甜汤，润燥养颜', 1, 4, 15.00, '耙耳朵甜品（成都店）', '成都市锦江区春熙路', 104.106142, 30.603490, '/images/food/yinergeng/yinergeng_shop.jpg'),
(66, '油卤串串', 'https://www.bilibili.com/video/BV1Yv4y1A7VH/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '成都', '/images/food/youluchuanchuan/youluchuanchuan_dish.jpg', '油卤串串以秘制油卤汁浸泡各式串串，色泽红亮、香气扑鼻，成串食材吸满卤香，麻辣中带着醇厚卤味。既可热吃也可冷食，荤素皆宜，是近年在成都迅速走红的串串新吃法。一签一串、随取随涮，尽显成都街头的烟火气。', '融合卤菜与串串工艺，近年风靡蓉城', 4, 4, 55.00, '耍海椒油卤串串（科华店）', '成都市武侯区科华北路', 104.058669, 30.628802, '/images/food/youluchuanchuan/youluchuanchuan_shop.jpg'),
(67, '鱼头火锅', 'https://www.bilibili.com/video/BV1qZ8yzjEr3/', '火锅', '成都', '/images/food/yutouhuoguo/yutouhuoguo_dish.jpg', '鱼头火锅以花鲢鱼头为主角，先煎后煮，红汤麻辣与鱼头鲜嫩相得益彰，鱼脑滑润、鱼肉细嫩。配以豆腐、宽粉、菌菇同煮，鲜辣交融，汤汁拌饭一绝，是川内极具人气的特色火锅。', '川人善用江河鲜味，鱼头入锅成就独特风味', 4, 4, 100.00, '谭鱼头火锅（宽窄巷子店）', '成都市青羊区下同仁路19号', 104.065818, 30.657443, '/images/food/yutouhuoguo/yutouhuoguo_shop.jpg'),
(68, '鱼香茄子', 'https://www.bilibili.com/video/BV1xg411L7Qa/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/yuxiangqiezi/yuxiangqiezi_dish.jpg', '鱼香茄子以茄子炸软后配鱼香汁烧制，茄条软糯入味，咸酸甜辣、葱姜蒜香齐备，色泽红亮、油润下饭。鱼香调味与软糯茄菜是绝佳搭配，是川味家常菜中的人气之选。麻辣鲜香、咸鲜适口，尽显川菜烹饪技艺的精妙。', '鱼香调味应用于茄菜，家常川味代表', 3, 4, 32.00, '老妈蹄花（总府路店）', '成都市锦江区总府路', 104.106142, 30.603490, '/images/food/yuxiangqiezi/yuxiangqiezi_shop.jpg'),
(69, '鱼香肉丝', 'https://www.bilibili.com/video/BV1zZAAerEJ3/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/yuxiangrousi/yuxiangrousi_dish.jpg', '鱼香肉丝以肉丝配木耳、竹笋、泡椒炒制，咸甜酸辣兼具、葱姜蒜香浓郁，虽不见鱼却有鱼香之味，故名“鱼香”。肉丝滑嫩、色泽红亮、下饭极佳，是川菜中家喻户晓的经典家常菜，也是川味调味技艺的代表。', '源于民间烹鱼调味，取其鱼香味而不用鱼', 3, 5, 35.00, '老码头火锅·川菜馆（宽窄巷子店）', '成都市青羊区窄巷子', 104.049627, 30.665185, '/images/food/yuxiangrousi/yuxiangrousi_shop.jpg'),
(70, '芋儿鸡', 'https://www.bilibili.com/video/BV1qWivBnEvA/', '火锅', '成都', '/images/food/yuerji/yuerji_dish.jpg', '芋儿鸡以仔鸡与芋头同烧，红油麻辣、芋儿粉糯，鸡肉鲜嫩入味。汤汁浓稠、麻辣鲜香，芋头吸饱鸡汁，入口即化，是一道既可当菜又可下饭的川味硬菜，常以干锅或火锅形式呈现。', '源于川西农家的烧鸡做法，后衍生为江湖菜', 4, 4, 80.00, '王妈手撕烤兔·芋儿鸡（玉林店）', '成都市武侯区玉林南街', 104.058669, 30.628802, '/images/food/yuerji/yuerji_shop.jpg'),
(71, '鸳鸯火锅', 'https://www.bilibili.com/video/BV1kJ411J7mU', '火锅', '成都', '/images/food/yuanyanghuoguo/yuanyanghuoguo_dish.jpg', '鸳鸯火锅以太极形铜锅分隔红汤与清汤，一半麻辣一半清淡，兼顾嗜辣者与不辣者的口味。清汤以鸡骨菌菇吊鲜，红汤以牛油辣椒提味，一锅两味，是接待外地朋友的贴心之选。热辣翻滚、围锅共食，是川渝人聚餐待客的经典方式。', '为照顾不同口味，川人创制一锅两味之鸳鸯锅', 3, 4, 110.00, '蜀大侠火锅（春熙店）', '成都市锦江区中纱帽街8号', 104.065818, 30.657443, '/images/food/yuanyanghuoguo/yuanyanghuoguo_shop.jpg'),
(72, '樟茶鸭', 'https://www.bilibili.com/video/BV12J411J7rh/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '成都', '/images/food/zhangchaya/zhangchaya_dish.jpg', '樟茶鸭以肥鸭先用樟树叶、花茶等熏制，再蒸再炸，皮酥肉嫩、烟香浓郁，色泽枣红、咸鲜醇厚。因以樟木与茶叶熏制而得名，是川菜宴席上极具特色的一道传统名菜，尤受老一辈食客喜爱。', '因以樟叶与茶叶熏制而得名，川菜宴席名菜', 1, 4, 98.00, '鸡毛店川菜（宽窄巷子店）', '成都市青羊区下同仁路', 104.065818, 30.657443, '/images/food/zhangchaya/zhangchaya_shop.jpg'),
(73, '蒸蒸糕', 'https://www.bilibili.com/video/BV1ky4y1v7df/?', '小吃', '成都', '/images/food/zhengzhenggao/zhengzhenggao_dish.jpg', '蒸蒸糕以米粉入小木模具蒸制，糕面撒白糖、蜜枣或果脯，出笼时热气腾腾、甜香扑鼻。糕体松软微弹、清甜不腻，以“现蒸现卖、吹一口热气”为特色，是成都老小吃。街头巷尾随处可见，是成都烟火气里的经典小吃。', '成都传统蒸制米糕，街头叫卖声令人怀念', 1, 4, 5.00, '蒸蒸糕（锦里店）', '成都市武侯区武侯祠大街', 104.065818, 30.657443, '/images/food/zhengzhenggao/zhengzhenggao_shop.jpg'),
(74, '钟水饺', 'https://www.bilibili.com/video/BV1tA411n7vw/?spm_id_from=333.337.search-card.all.click', '小吃', '成都', '/images/food/zhongshuijiao/zhongshuijiao_dish.jpg', '钟水饺皮薄馅嫩，与北方水饺不同，它浇以特制红油、蒜泥与复制酱油，咸甜微辣、色泽红亮，鲜香入味。因其创始人姓钟而得名，是成都最早的招牌小吃之一，百年不衰。老少皆宜、回味悠长，深受本地人与游客喜爱。', '创于清末，创始人姓钟故名钟水饺', 3, 5, 15.00, '钟水饺（总府路总店）', '成都市锦江区总府路23号', 104.065818, 30.657443, '/images/food/zhongshuijiao/zhongshuijiao_shop.jpg'),
(75, '达州灯影牛肉', 'https://www.bilibili.com/video/BV1JrkMYKEVT/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '小吃', '达', '/images/food/dazhoudengyingniurou/dazhoudengyingniurou_dish.jpg', '灯影牛肉是达州名产，牛肉切薄如纸、薄可透光，在灯下影影绰绰如皮影，故名。片薄酥脆、麻辣回甜、入口化渣，既是佐酒佳品，也是馈赠亲友的地方特产。老少皆宜、回味悠长，深受本地人与游客喜爱。', '因肉片薄可透光似灯影而得名', 3, 4, 40.00, '老川东灯影牛肉（达州店）', '达州市通川区', 107.527895, 31.236685, '/images/food/dazhoudengyingniurou/dazhoudengyingniurou_shop.jpg'),
(76, '罗江豆鸡', 'https://www.bilibili.com/video/BV1ez4y1V7jh/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '德阳', '/images/food/luojiangdouji/luojiangdouji_dish.jpg', '罗江豆鸡是德阳罗江特产，以豆油皮抹芝麻酱、花椒粉卷制而成，色棕红、软绵上口，麻辣鲜香、越嚼越香。虽名为鸡，实为豆制品，却形味似鸡肉，是川北著名素小吃。街头巷尾随处可见，是成都烟火气里的经典小吃。', '罗江特产，以豆油皮卷制仿鸡形而名', 3, 4, 20.00, '罗江豆鸡（罗江店）', '德阳市罗江区', 104.414575, 31.154299, '/images/food/luojiangdouji/luojiangdouji_shop.jpg'),
(77, '广元蒸凉面', 'https://www.bilibili.com/video/BV1db411H7k6/?', '面食', '广元', '/images/food/guangyuanzhengliangmian/guangyuanzhengliangmian_dish.jpg', '广元蒸凉面以大米磨浆蒸制成皮，切条后拌红油、蒜水与调料，口感软糯爽滑、麻辣鲜香。以“女皇蒸凉面”最为闻名，是广元人夏日最爱的清凉主食，老少皆宜。面条筋道、调味浓郁，是川味面馆最受欢迎的招牌。', '相传与武则天有关，故称女皇蒸凉面', 3, 4, 10.00, '广元女皇蒸凉面（老城店）', '广元市利州区老城', 105.667819, 32.379606, '/images/food/guangyuanzhengliangmian/guangyuanzhengliangmian_shop.jpg'),
(78, '剑门豆腐', 'https://www.bilibili.com/video/BV1mt41177Em/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '广元', '/images/food/jianmendoufu/jianmendoufu_dish.jpg', '剑门豆腐以当地山泉与黄豆磨制，质地细嫩、豆香浓郁，可做成麻辣、怀胎、崩山豆腐等百余种菜式，一桌“豆腐宴”令人称奇。麻辣鲜香、清淡养生，是剑门关镇的一道招牌。老少皆宜、回味悠长，深受本地人与游客喜爱。', '剑门关镇特产，相传与姜维守关有关', 3, 4, 35.00, '剑门关豆腐宴（剑门镇）', '广元市剑阁县剑门关镇', 105.843238, 32.266165, '/images/food/jianmendoufu/jianmendoufu_shop.jpg'),
(79, '钵钵鸡', 'https://www.bilibili.com/video/BV1Jt411i75U/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '乐山', '/images/food/boboji/boboji_dish.jpg', '钵钵鸡是乐山名小吃，将鸡块、鸡爪、藕片、木耳等穿串，浸入盛在陶钵里的红油麻辣或藤椒汤汁中冷食。汤底由鸡汤与红油、芝麻调制，麻辣鲜香、清爽不腻，随取随吃，是街头巷尾的经典。', '源自乐山，因盛于陶钵、主料为鸡而得名', 4, 5, 40.00, '叶婆婆钵钵鸡（乐山总店）', '乐山市市中区上河街', 103.711846, 29.601817, '/images/food/boboji/boboji_shop.jpg'),
(80, '峨眉豆腐脑', 'https://www.bilibili.com/video/BV1oJ411D7AV/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '乐山', '/images/food/emeidoufunao/emeidoufunao_dish.jpg', '峨眉豆腐脑以嫩豆花为主，浇上粉蒸牛肉、豌豆、馓子与红油臊子，麻辣鲜香、咸鲜适口，一勺下去有豆花的嫩滑与肉臊的酥香。峨眉人讲究搭配蛋烘糕同食，是当地的早餐标配。街头巷尾随处可见，是成都烟火气里的经典小吃。', '庙会小吃演变而来，以臊子豆腐脑闻名', 4, 4, 10.00, '峨眉豆腐脑（书院街店）', '乐山市峨眉山市书院街', 103.711846, 29.601817, '/images/food/emeidoufunao/emeidoufunao_shop.jpg'),
(81, '乐山跷脚牛肉', 'https://www.bilibili.com/video/BV1Vk9jBTEVw/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '乐山', '/images/food/leshanqiaojiaoniurou/leshanqiaojiaoniurou_dish.jpg', '跷脚牛肉是乐山名菜，以牛杂、牛肉在清汤锅中烫熟，蘸干辣椒碟食用，汤鲜肉嫩、驱寒上口。因旧时食客习惯翘腿而坐而得名，如今汤锅与蒸笼并存，是乐山杨公桥一带的招牌风味。', '相传由乐山周村屠户发明，因食客翘脚而食得名', 3, 5, 55.00, '周村跷脚牛肉（杨公桥店）', '乐山市市中区杨公桥', 103.711846, 29.601817, '/images/food/leshanqiaojiaoniurou/leshanqiaojiaoniurou_shop.jpg'),
(82, '藤椒钵钵鸡', 'https://www.bilibili.com/video/BV1wK4y187ud/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '串串', '乐山', '/images/food/tengjiaoboboji/tengjiaoboboji_dish.jpg', '藤椒钵钵鸡以藤椒与青花椒调制清麻汤底，汤色清亮、麻香突出，辣度温和而麻味悠长。食材浸于藤椒汤汁中，清凉爽口、鲜麻生津，与红油钵钵鸡并称乐山双绝，尤受喜麻者青睐。', '乐山人以藤椒入馔，创制清麻口味的钵钵鸡', 3, 4, 40.00, '张公桥藤椒钵钵鸡', '乐山市市中区张公桥好吃街', 103.711846, 29.601817, '/images/food/tengjiaoboboji/tengjiaoboboji_shop.jpg'),
(83, '西昌火盆烧烤', 'https://www.bilibili.com/video/BV1Mr4y1S7n7/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '小吃', '凉山', '/images/food/xichanghuopenshaokao/xichanghuopenshaokao_dish.jpg', '西昌火盆烧烤以烧红的木炭入火盆，架上铁网烤制小香猪、乳猪与各式肉串，肉质外焦里嫩、蘸上干辣椒，麻辣鲜香。围盆而食、热热闹闹，是凉山最有烟火气的特色美食。价廉物美、风味独特，是川渝街头的常客。', '凉山彝族火塘文化衍生出的烧烤吃法', 4, 5, 80.00, '西昌火盆烧烤（邛海边店）', '凉山州西昌市海滨中路', 105.213217, 32.383431, '/images/food/xichanghuopenshaokao/xichanghuopenshaokao_shop.jpg'),
(84, '泸州白糕', 'https://www.bilibili.com/video/BV19N4y1G7Ct/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '泸', '/images/food/luzhoubaigao/luzhoubaigao_dish.jpg', '泸州白糕以大米发酵蒸制，洁白松软、微甜回香，顶上一颗红点、中间夹馅，入口溢满米香。既是街头早点，也是年节点心，清淡养人、老少皆宜，是泸州人的甜蜜记忆。老少皆宜、回味悠长，深受本地人与游客喜爱。', '泸州传统米发糕，以白嫩微甜著称', 1, 4, 5.00, '泸州白糕（江阳老店）', '泸州市江阳区', 105.443179, 28.844232, '/images/food/luzhoubaigao/luzhoubaigao_shop.jpg'),
(85, '绵阳米粉', 'https://www.bilibili.com/video/BV1d94y187QE/?spm_id_from=333.337.search-card.all.click', '面食', '绵阳', '/images/food/mianyangmifen/mianyangmifen_dish.jpg', '绵阳米粉以细如丝的米粉为体，浇牛肉、肥肠或鸡汤臊子，汤色红亮、臊子酥脆，米粉滑爽入味。麻辣鲜香、分量十足，是绵阳人早晨离不开的一碗，堪称“绵阳人的早餐执念”。一碗下肚、酣畅满足，是四川人日常钟爱的味道。', '绵阳早餐文化代表，臊子米粉闻名川内', 4, 5, 10.00, '绵阳开元米粉（总店）', '绵阳市涪城区临园路', 104.717352, 31.459911, '/images/food/mianyangmifen/mianyangmifen_shop.jpg'),
(86, '太白鸭', 'https://www.bilibili.com/video/BV1v1s5zLEBa/?', '川菜', '绵阳', '/images/food/taibaiya/taibaiya_dish.jpg', '太白鸭相传为唐代诗人李白所嗜，以肥鸭配竹苏、火腿蒸制，鸭肉酥烂、汤清味鲜，鲜香醇厚、营养滋补。做法考究、风味清雅，是川菜中不多见的清鲜蒸菜，也是江油一带的传统名菜。', '相传因诗仙李白喜食而得名', 1, 3, 88.00, '江油太白祠餐厅', '绵阳市江油市青莲镇', 104.717352, 31.459911, '/images/food/taibaiya/taibaiya_shop.jpg'),
(87, '梓潼片粉', 'https://www.bilibili.com/video/BV1MdvVeiEdL/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '绵阳', '/images/food/zitongpianfen/zitongpianfen_dish.jpg', '梓潼片粉以绿豆浆制成粉皮切块，凉拌红油、蒜水与调料，粉片细嫩滑爽、麻辣鲜香、清凉利口。加韭黄、豆芽同拌更香，是绵阳梓潼一带夏日消暑的传统小吃。价廉物美、风味独特，是川渝街头的常客。', '梓潼传统小吃，以绿豆粉皮凉拌而食', 3, 4, 10.00, '梓潼片粉（老店）', '绵阳市梓潼县文昌镇', 104.717352, 31.459911, '/images/food/zitongpianfen/zitongpianfen_shop.jpg'),
(88, '川北凉粉', 'https://www.bilibili.com/video/BV1Y3411x71b/?spm_id_from=333.337.search-card.all.click', '小吃', '南充', '/images/food/chuanbeiliangfen/chuanbeiliangfen_dish.jpg', '川北凉粉以绿豆或豌豆粉制成，粉条细滑、晶莹剔透，浇红油、蒜水与调料，麻辣鲜香、清爽利口。以顺庆最为著名，历史悠长，是川北地区家喻户晓的经典凉食。街头巷尾随处可见，是成都烟火气里的经典小吃。', '源于川北顺庆，以细嫩爽口闻名', 4, 5, 8.00, '川北凉粉（顺庆总店）', '南充市顺庆区', 106.071113, 30.791995, '/images/food/chuanbeiliangfen/chuanbeiliangfen_shop.jpg'),
(89, '南充米粉', 'https://www.bilibili.com/video/BV1H1421q7im/?spm_id_from=333.337.search-card.all.click', '面食', '南充', '/images/food/nanchongmifen/nanchongmifen_dish.jpg', '南充米粉以细米粉配牛肉、肥肠或圆子臊子，汤红味浓、麻辣鲜香，米粉劲道入味。南充米粉讲究现冒现卖，通宵营业，是南充人宵夜与早餐的日常选择。面条筋道、调味浓郁，是川味面馆最受欢迎的招牌。', '南充传统米粉，以臊子多样著称', 4, 4, 9.00, '老麻鱼米粉（南充总店）', '南充市顺庆区文化路', 117.664808, 28.981452, '/images/food/nanchongmifen/nanchongmifen_shop.jpg'),
(90, '张飞牛肉', 'https://www.bilibili.com/video/BV1o44y1L73x/?spm_id_from=333.337.search-card.all.click', '小吃', '南充', '/images/food/zhangfeiniurou/zhangfeiniurou_dish.jpg', '张飞牛肉是阆中特产，色黑皮红、肉干而不燥，外黑内红形似张飞脸谱，故名。入口酥香化渣、咸鲜回甜，既可直接切片下酒，也可入面作臊，是川北著名特产小吃。老少皆宜、回味悠长，深受本地人与游客喜爱。', '因色黑内红似张飞脸谱而得名，阆中特产', 2, 4, 40.00, '张飞牛肉（阆中古城店）', '南充市阆中市古城', 117.664808, 28.981452, '/images/food/zhangfeiniurou/zhangfeiniurou_shop.jpg'),
(91, '内江牛肉面', 'https://www.bilibili.com/video/BV1Hs411D7J8/?', '面食', '内江', '/images/food/neijiangniuroumian/neijiangniuroumian_dish.jpg', '内江牛肉面以红烧牛肉为臊，汤色红亮、牛肉软糯，面条劲道爽滑，配韭黄、香菜与红油辣椒，麻辣鲜香、牛肉味浓。一碗牛肉面便是内江人清晨的精神早餐。汤面交融、麻辣鲜香，是四川街头随处可见的美味。', '内江牛肉面为当地传统早餐面食', 4, 4, 14.00, '张大妈牛肉面（内江总店）', '内江市市中区大西街', 105.057706, 29.580144, '/images/food/neijiangniuroumian/neijiangniuroumian_shop.jpg'),
(92, '资中兔子面', 'https://www.bilibili.com/video/BV1r44y1V7rr/?', '面食', '内江', '/images/food/zizhongtuzimian/zizhongtuzimian_dish.jpg', '资中兔子面以红烧兔肉为浇头，兔肉麻辣鲜嫩、酥香入味，面条爽滑，红油浓香、麻辣适口。兔肉面在川南一带颇具人气，内江资中的做法尤为地道。面条筋道、调味浓郁，是川味面馆最受欢迎的招牌。', '川南以兔肉入面，资中兔子面自成特色', 4, 4, 15.00, '资中兔子面（总店）', '内江市资中县重龙镇', 105.057706, 29.580144, '/images/food/zizhongtuzimian/zizhongtuzimian_shop.jpg'),
(93, '攀枝花油底肉', 'https://www.bilibili.com/video/BV1Dt4y1n7Re/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '攀枝花', '/images/food/panzhihuayoudirou/panzhihuayoudirou_dish.jpg', '油底肉是攀枝花传统美食，以猪肉切块入锅与油慢熬，肉质粑糯、肥而不腻，油封保存、久放不坏。吃时取出回锅，咸香醇厚、下饭一绝，是攀西地区存肉与风味的智慧结晶。老少皆宜、回味悠长，深受本地人与游客喜爱。', '彝汉杂居区传统存肉手法，油封而成', 2, 4, 45.00, '攀枝花油底肉（仁和店）', '攀枝花市仁和区', 101.735273, 26.491689, '/images/food/panzhihuayoudirou/panzhihuayoudirou_shop.jpg'),
(94, '石棉烧烤', 'https://www.bilibili.com/video/BV1TEdYB1Erf/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '小吃', '雅安', '/images/food/shimianshaokao/shimianshaokao_dish.jpg', '石棉烧烤发源于雅安石棉，以当地高山小黑猪为料，现串现烤、木炭炙烤，肉串外焦里嫩、蒜香与炭火香交融。荤素串串琳琅满目，配冰啤酒，是川西坝子入夜后最热闹的江湖烟火。', '源于雅安石棉，以香猪小串闻名川西', 4, 4, 60.00, '石棉烧烤（安顺场店）', '雅安市石棉县', 103.056717, 30.028760, '/images/food/shimianshaokao/shimianshaokao_shop.jpg'),
(95, '李庄白肉', 'https://www.bilibili.com/video/BV1U34y1o7xH/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '川菜', '宜宾', '/images/food/lizhuangbairou/lizhuangbairou_dish.jpg', '李庄白肉是宜宾李庄名菜，以猪后腿肉煮后切薄如纸的大片，蘸蒜泥红油味汁，肉片肥瘦均匀、薄可透光，入口肥而不腻、蒜香拌味，麻辣鲜香。刀工讲究、风味独特，是李庄“三白”之首。', '抗战时期随同济大学内迁而名扬，李庄三白之首', 3, 5, 50.00, '李庄陈记白肉', '宜宾市翠屏区李庄镇', 104.642978, 28.752095, '/images/food/lizhuangbairou/lizhuangbairou_shop.jpg'),
(96, '凉糕', 'https://www.bilibili.com/video/BV1xT4y1u7Qn/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '甜品', '宜宾', '/images/food/lianggao/lianggao_dish.jpg', '凉糕以大米磨浆熬制，口感嫩滑软糯，浇红糖水冰镇而食，清甜爽口、老少皆宜。配以玫瑰蜜或蜂蜜风味更佳，是川南夏日最受欢迎的清凉甜品之一。软糯香甜、抚慰肠胃，是川渝人钟爱的甜蜜滋味。', '宜宾葡萄井凉糕最为闻名', 1, 5, 8.00, '葡萄井凉糕（宜宾店）', '宜宾市长宁县长宁镇', 104.642978, 28.752095, '/images/food/lianggao/lianggao_shop.jpg'),
(97, '宜宾黄粑', 'https://www.bilibili.com/video/BV1tm4y1o7Ax/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c', '小吃', '宜宾', '/images/food/yibinhuangba/yibinhuangba_dish.jpg', '宜宾黄粑以糯米拌红糖，用黄姜叶或粽叶包裹蒸制，色泽金黄、糯米软糯、带着坚果般清香。可蒸可烤，甜糯适口、清香难忘，是川南逢年过节与街头常见的传统小吃。价廉物美、风味独特，是川渝街头的常客。', '川南以粽叶包蒸的传统糯米小吃', 1, 4, 8.00, '宜宾黄粑（西街店）', '宜宾市翠屏区西街', 104.624693, 28.772098, '/images/food/yibinhuangba/yibinhuangba_shop.jpg'),
(98, '宜宾燃面', 'https://www.bilibili.com/video/BV1qj411U78G/?spm_id_from=333.337.search-card.all.click', '面食', '宜宾', '/images/food/yibinranmian/yibinranmian_dish.jpg', '宜宾燃面以水面条拌油辣子、花生碎、芽菜与香油，面条干爽松散、油光发亮，麻辣鲜香、香而不腻。因其油重无水、点火即燃而得名，是宜宾最具代表性的面食名片。面条筋道、调味浓郁，是川味面馆最受欢迎的招牌。', '因油重水少、点火即燃而得名', 4, 5, 15.00, '宜宾燃面（西街店）', '宜宾市翠屏区西街', 104.624693, 28.772098, '/images/food/yibinranmian/yibinranmian_shop.jpg'),
(99, '富顺豆花', 'https://www.bilibili.com/video/BV11SRDBWEqF/?spm_id_from=333.337.search-card.all.click', '小吃', '自贡', '/images/food/fushundouhua/fushundouhua_dish.jpg', '富顺豆花以嫩豆腐脑配香辣蘸水，豆花绵软细嫩、入口即化，蘸水中豆瓣、花椒、花生香气交融，配一碗籼米饭，麻辣鲜香、清淡可口。是自贡富顺人日常离不开的平民美食。街头巷尾随处可见，是成都烟火气里的经典小吃。', '富顺豆花以蘸水闻名，自贡名食', 3, 5, 10.00, '富顺豆花饭（总店）', '自贡市富顺县', 104.778819, 29.339070, '/images/food/fushundouhua/fushundouhua_shop.jpg'),
(100, '自贡冷吃兔', 'https://www.bilibili.com/video/BV1ST4y1f7gE/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '小吃', '自贡', '/images/food/zigonglengchitu/zigonglengchitu_dish.jpg', '冷吃兔是自贡盐帮菜名品，以兔丁入锅干煸，配干辣椒、花椒与香料，色泽红亮、麻辣干香，兔肉酥嫩入味。冷吃更香，既可当菜也可当零食，是自贡人待客与佐酒的招牌。价廉物美、风味独特，是川渝街头的常客。', '自贡盐帮菜代表，干煸做法冷食更香', 5, 5, 35.00, '自贡火边子牛肉·冷吃兔', '自贡市自流井区五星街', 104.778819, 29.339070, '/images/food/zigonglengchitu/zigonglengchitu_shop.jpg')
INSERT INTO `culture` (`id`, `name`, `category`, `cover_image`, `summary`, `content`, `website`, `related_scenic`, `related_person`, `video_url`, `tags`) VALUES
(1, '川剧变脸', '戏曲', '/images/culture/chuanjubianlian/chuanjubianlian_cover.jpg', '川剧变脸是川剧独有的绝技，演员在瞬间变换脸谱，神秘莫测、叹为观止，被誉为“东方魔术”，是国家级非物质文化遗产与巴蜀文化的一张名片。', '川剧变脸是川剧表演艺术中最具代表性的绝技，被誉为“东方魔术”，2006年随川剧列入国家级非物质文化遗产名录。它指演员在舞台上以极快的手法在瞬间变换面部脸谱，或抹脸、或吹脸、或扯脸，快到观众几乎无法察觉，呈现出喜怒哀乐与忠奸善恶的瞬息变化，极具视觉震撼。脸谱以红、黑、白、黄、蓝、金等浓烈色彩勾画，红表忠勇、黑表刚直、白表奸诈、金银多用于神怪，色彩本身即是一种叙事语言。变脸常与吐火、藏刀等绝技配合演出，在《白蛇传》《金山寺》《望娘滩》等剧目中大放异彩。变脸技艺长期以师徒相授、口传心授的方式在川剧班社中传承，讲究“手法快、身法稳、眼神到”，演员需多年苦练方能登台。它既承袭了戏曲程式化的美学，又融入巴蜀人火辣张扬的性格，是川剧最具辨识度的符号。如今，变脸不仅活跃于剧场，也走向世界舞台，成为向海内外展示巴蜀文化的金字招牌，代表性传承人彭登怀等更让绝技名扬国际。观看川剧变脸，既是一次惊心动魄的视觉体验，也是触摸川剧百年文脉的绝佳窗口。值得一提的是，变脸的技法大致可分为抹脸、吹脸、扯脸三类，其中扯脸以丝线将多层薄脸谱藏于身上，随演随扯，最见功夫。如今，变脸不仅是剧场里的压轴绝技，也频频亮相央视舞台与国际文化交流，成为世界认识川剧的第一扇窗口。', 'https://baike.baidu.com/item/%E5%B7%9D%E5%89%A7%E5%8F%98%E8%84%B8/63484', '锦江剧场,蜀风雅韵,成都川剧艺术中心,宽窄巷子', '彭登怀', 'https://www.bilibili.com/video/BV1KN411V7Wa/?spm_id_from=333.337.search-card.all.click', '非遗,国粹,巴蜀文化,川剧,绝技'),
(2, '蜀绣', '工艺', '/images/culture/shuxiu/shuxiu_cover.jpg', '蜀绣是中国四大名绣之一，以针法严谨、色彩明快、题材生动著称，代表作熊猫、芙蓉鲤鱼，2006年列入首批国家级非物质文化遗产名录。', '蜀绣又称“川绣”，与苏绣、湘绣、粤绣并称中国四大名绣，2006年列入首批国家级非物质文化遗产名录。它发源于川西平原，因成都古称“蜀”而得名，历史可追溯至三星堆与金沙时期的丝织遗存，汉代已相当繁盛，明清时更因“蜀绣之工，甲于天下”而闻名。蜀绣以“针法严谨、片线光亮、层次分明、色彩明快”著称，讲究“针脚整齐、线片光亮、紧密结合、劲气生动、虚实得体”，针法多达一百二十余种，如晕针、铺针、滚针、截针、掺针、沙针等，尤其擅长表现花鸟、走兽、山水与人物。其双面异色绣、双面异形绣堪称绝技，两面图案与色彩各异而浑然一体，令人叫绝。蜀绣题材多取自巴蜀风物，憨态可掬的大熊猫、灵动传神的芙蓉鲤鱼、雍容的牡丹与秀美的山水，无不是川人审美与生活的写照。它以“线如丝、色如画”的表现力，将蚕桑文明、绘画意境与手工技艺熔于一炉。如今，蜀绣既用于高端艺术品与国礼，也融入服饰、文创走进日常，在成都蜀绣工坊、蜀锦织绣博物馆等传承基地延续着千年针线。一针一线之间，是巴蜀匠人对美的执着追求，也是丝绸之路上东方美学的璀璨结晶。在传承上，蜀绣既保留了家族与师徒相授的传统，也走进高校与工坊培养新人。近年来，蜀绣作品屡屡作为国礼赠予外国元首，憨态可掬的熊猫绣屏、灵动的芙蓉鲤鱼成为中外文化交流的友好使者，让千年针线在新时代焕发出蓬勃生机。', 'https://baike.baidu.com/item/%E8%9C%80%E7%BB%A3/218', '成都蜀锦织绣博物馆,蜀绣工坊,文殊坊,安靖蜀绣之乡', '郝淑萍,孟德芝,杨德全', 'https://www.bilibili.com/video/BV1g6XTY5EsU/?spm_id_from=333.337.search-card.all.click', '非遗,四大名绣,巴蜀文化,手工艺'),
(3, '川菜', '饮食', '/images/culture/chuancai/chuancai_cover.jpg', '川菜位列中国八大菜系之首，以“一菜一格，百菜百味”著称，善用麻辣，味型丰富，麻辣鲜香、家常亲民，是四川最鲜活的文化名片。', '川菜是中国八大菜系之一，发源于巴蜀大地，以“一菜一格，百菜百味”享誉世界，是四川最具烟火气的文化名片。川菜讲究“麻、辣、咸、甜、酸、苦、香”七味调和，尤以麻辣见长，却绝非只有辣——仅常见味型就有鱼香、怪味、糊辣、荔枝、酸辣、麻辣、椒麻、蒜泥、姜汁、咸鲜等二三十种，味型之多居各菜系之冠。其灵魂调味首推郫县豆瓣与花椒，辅以泡椒、泡姜、豆豉、芽菜、井盐，善于“以味为核心”，通过复合调味创造层次丰富的口感体验。川菜亦有“三香三椒”之说，善用葱、姜、蒜与辣椒、花椒、胡椒，讲究火候与“锅气”。菜品既有麻婆豆腐、回锅肉、宫保鸡丁、水煮鱼、夫妻肺片、鱼香肉丝等经典名菜，也有开水白菜这等清汤极品的“清淡一派”，还有火锅、冒菜、串串、担担面等深入市井的平民美味。历史上，川菜融合了湖广移民的烹饪技艺与本土风物，明清时期“湖广填四川”推动其定型成熟，近代川菜更随抗战时期下江大厨入川而精益求精。川菜不仅是味觉享受，更承载着川人乐观豁达、热爱生活的性格。如今，川菜馆遍布全球，“麻辣”成为世界认识中国的味觉入口，是饮食文化中最具传播力的四川符号。值得一提的是，川菜不仅讲究味道，也讲究“色、香、味、形、器”兼备，一道好菜往往是味道与审美的统一。改革开放以来，川菜随着川人走向全国乃至海外，如今已成为中国最具国际影响力的菜系，真正做到了“舌尖上的四川，飘香于世界”。', 'https://baike.baidu.com/item/%E5%B7%9D%E8%8F%9C/26409', '陈麻婆豆腐,成都川菜博物馆,宽窄巷子,锦里', '史正良,蓝其金,彭子渝', 'https://www.bilibili.com/video/BV1Vp4y1B7hx/?spm_id_from=333.337.search-card.all.click', '八大菜系,美食,巴蜀文化,非遗'),
(4, '茶马古道', '历史', '/images/culture/chamagudao/chamagudao_cover.jpg', '茶马古道是古代以川滇茶叶换取藏区马匹的商贸通道，雅安、康定是重要节点，横跨川西高原，是民族交融与文明互鉴的历史见证。', '茶马古道是唐宋以来汉、藏等民族之间以茶叶交易马匹而形成的古老商道，是西南地区最著名的商贸与文化通道之一。它起源于古代川、滇边茶产区与藏族牧区之间的物资互补需求：内地盛产茶叶而缺马，青藏高原多马而嗜茶需茶，于是以“茶”换“马”的互市应运而生，形成横贯川、滇、藏并在明清达到鼎盛的庞大交通网络。川藏线茶马古道以西康、雅安为起点，经泸定、康定、理塘、巴塘入藏，雅安“边茶”与康定“锅庄”闻名于世；康定作为汉藏贸易枢纽，商贾云集、锅庄林立，因一曲《康定情歌》而名扬海内。茶马古道不仅运茶易马，也运盐、布匹、药材与骡马，往来其间的是挑夫、马帮与锅庄商人，他们翻雪山、渡激流，用背夹与骡马将文明驮向高原。古道沿途留下了驿站、马店、桥梁、锅庄与摩崖石刻，也催生了多民族聚居的城镇与集市。它是汉、藏、彝、羌等民族交往交流交融的纽带，见证了多元一体的中华文明。与茶马古道并行的，还有更为古老的“南方丝绸之路”。如今，古道虽已沉寂，但其精神仍活在茶马古道沿线的古镇、驿站与藏羌村寨之中，成为文化研究与旅游探寻的热点。如今，川藏茶马古道沿线的雅安、康定、泸定等地积极挖掘古道文化与藏茶非遗，蒙顶茶、雅安藏茶与古镇驿站吸引着众多旅行者重走古道。这条横跨千年、联结汉藏的商路，正以其厚重的历史感与壮美的高原风光，成为巴蜀文化中一张独特的金色名片。', 'https://baike.baidu.com/item/%E8%8C%B6%E9%A9%AC%E5%8F%A4%E9%81%93/18157', '雅安,康定,泸定桥,上里古镇,望鱼古镇', NULL, 'https://www.bilibili.com/video/BV1wM7C6zEoE/?spm_id_from=333.337.search-card.all.click', '商贸通道,民族交融,历史,高原,藏茶'),
(5, '三国文化', '历史', '/images/culture/sanguowenhua/sanguowenhua_cover.jpg', '三国文化以魏蜀吴争霸为背景，蜀汉以四川为根基，武侯祠、剑门关、白马关等遗迹遍布蜀地，是巴蜀历史中影响深远的文化符号。', '三国文化是以东汉末年魏、蜀、吴三分天下为历史背景，并在后世文学、戏曲、民俗中不断丰富而成的文化体系。四川是蜀汉政权的核心之地，刘备据益州、诸葛亮治蜀、姜维屯兵剑门，留下了大量史迹与传说，使巴蜀成为三国文化最重要的承载地之一。成都武侯祠是全国影响最大的三国遗迹博物馆，纪念诸葛亮、刘备等蜀汉君臣，以“三绝碑”与君臣合祀祠庙闻名；广元剑门关以“剑门天下险”扼守蜀道，是蜀汉门户与古战场；德阳白马关有庞统祠墓，绵竹、阆中、昭化等地亦遍布三国遗迹。三国文化不仅见于史书《三国志》（作者陈寿即为蜀人），更因小说《三国演义》与川剧、评书、皮影等艺术形式而深入人心，诸葛亮“鞠躬尽瘁”的忠义人格、刘关张“桃园结义”的手足情谊，成为中华传统价值的重要象征。蜀汉的兴衰与川人的家国情怀彼此交织，使三国故事在四川民间家喻户晓，地名、庙宇、习俗中随处可见其印记。如今，武侯祠庙会、锦里民俗街、三国文化主题旅游等，让古老的英雄故事在当下焕发新生，是巴蜀历史文脉中浓墨重彩的一笔。值得一提的是，三国文化早已超越历史本身，融入了川人的日常语言与世俗生活：成都街头巷尾的三国地名、川剧里的三国戏、茶馆中的三国评书，以及大量三国主题的文创与美食，都让金戈铁马的英雄时代与今日的巴蜀烟火彼此交织，历久弥新。', 'https://baike.baidu.com/item/%E4%B8%89%E5%9B%BD%E6%96%87%E5%8C%96?fromModule=lemma_search-box', '成都武侯祠,剑门关,白马关,昭化古城,阆中古城', '陈寿', 'https://www.bilibili.com/video/BV1GhuDzqEF4/?spm_id_from=333.337.search-card.all.click', '蜀汉,三国,历史,武侯祠,三国演义'),
(6, '三星堆', '历史', '/images/culture/sanxingdui/sanxingdui_cover.jpg', '三星堆是古蜀文明的杰出代表，青铜神树、大立人、纵目面具与金杖震惊世界，展现了长江上游早期文明的辉煌与神秘。', '三星堆遗址位于广汉市鸭子河南岸，是距今约4800至2600年的古蜀文化遗址，被称为20世纪人类最伟大的考古发现之一，与金沙遗址一前一后，共同构成古蜀文明的先后篇章。1986年发现的一、二号祭祀坑出土了青铜神树、青铜大立人、青铜纵目面具、金杖、金面罩与大量玉器、象牙，造型奇诡、工艺精湛，展现出与中原青铜文明迥异的独特风格，引发世人对古蜀“人神合一”信仰的无限遐想。高大的青铜神树高达近四米，被学者推测为古蜀人“通天”神话的具象；纵目面具“千里眼、顺风耳”的夸张造型，则与巴蜀传说中蚕丛“纵目”的记载遥相呼应。2021年以来，三至八号祭祀坑的发掘又出土了黄金面具、青铜大面具、跪坐人像、玉琮等文物上万件，不断刷新人们对古蜀文明的认识，其青铜铸造工艺与用金工艺之精，足以改写中国青铜文明的地图。三星堆博物馆以现代化的展陈方式呈现这些惊世文物，成为四川最受欢迎的文化地标之一。三星堆不仅是考古学上的奇迹，更象征着中华文明“多元一体”的宏大图景，证明长江上游同样是中华文明的重要发源地。今天，三星堆与金沙遗址共同构成“古蜀文明”的双子星，三星堆博物馆的青铜大面具、青铜神树等文物已成为四川文化的超级IP，频频亮相于文创、影视与展览之中。它让世界重新认识了长江上游文明的辉煌，也让中华文明“多元一体”的历史画卷更加丰满而立体。', 'https://baike.baidu.com/item/%E4%B8%89%E6%98%9F%E5%A0%86%E9%81%97%E5%9D%80/304608?fromtitle=%E4%B8%89%E6%98%9F%E5%A0%86&fromid=104175', '三星堆博物馆,金沙遗址博物馆,宝墩遗址', NULL, 'https://www.bilibili.com/video/BV1hSt9zdEmX/?spm_id_from=333.337.search-card.all.click', '古蜀文明,青铜文明,考古,博物馆,多元一体'),
(7, '大熊猫', '自然', '/images/culture/daxiongmao/daxiongmao_cover.jpg', '大熊猫是中国的国宝与国际名片，四川是主产区，卧龙、碧峰峡等是著名基地，憨态可掬的熊猫既是生态保护的象征，也承载着“熊猫外交”。', '大熊猫被誉为“国宝”，是世界上最具知名度的珍稀动物之一，而四川是其核心栖息地，全球绝大多数的野生大熊猫都分布在四川盆地周边的山地里。大熊猫已生存了至少800万年，被称为“活化石”，以箭竹为主食，性情温顺、憨态可掬。四川的卧龙、四姑娘山、夹金山等地区构成“四川大熊猫栖息地”，2006年列入世界自然遗产名录，青川唐家河、宝兴蜂桶寨、都江堰龙溪虹口等保护区也栖息着大熊猫。大熊猫不仅是生物多样性保护的旗舰物种，更在近代发展出独特的“熊猫外交”：自上世纪以来，大熊猫作为友好使者远赴海外，成为中外友好的象征，成都大熊猫繁育研究基地、卧龙中华大熊猫苑、雅安碧峰峡基地等成为向世界展示中国生态保护与自然之美的窗口。近年来，随着保护力度加强，大熊猫受威胁等级从“濒危”降为“易危”，成为全球濒危物种保护的典范，成都更以“熊猫之都”为城市名片，处处可见熊猫元素。保护大熊猫，就是守护一方青山与生物多样性，它衔接着自然生态与人类文明的和谐共生。值得一提的是，从古代文献中的记载到现代科学的保护，大熊猫始终牵动着国人的心。科研人员通过野化放归、栖息地廊道建设等方式守护这一物种，成都熊猫基地的“熊猫幼崽”直播更风靡全网。大熊猫以它的可爱，让世界对中国的生态保护与绿水青山有了更直观、更温暖的认识。', 'https://baike.baidu.com/item/%E5%A4%A7%E7%86%8A%E7%8C%AB/34935', '成都大熊猫繁育研究基地,卧龙中华大熊猫苑,碧峰峡,唐家河', '胡锦矗,张和民', 'https://www.bilibili.com/video/BV1Tn1iYNEUM/?spm_id_from=333.337.search-card.all.click', '国宝,生态保护,世界遗产,熊猫外交,旗舰物种'),
(8, '酒文化', '饮食', '/images/culture/jiuwenhua/jiuwenhua_cover.jpg', '四川是中国白酒的重要产区，五粮液、泸州老窖、剑南春、水井坊等名酒辈出，千年窖池与酿造技艺造就了川酒的浓香传奇与酒礼文化。', '四川素有“川酒甲天下”之誉，是中国浓香型白酒的核心产区，五粮液、泸州老窖、剑南春、郎酒、水井坊、全兴等名酒辈出，构成中华酒文化中最耀眼的版图。川酒文化源远流长，成都平原自古粮食丰足、水泉清冽，为酿酒提供了得天独厚的条件，三星堆、宝墩文化中已可见酒器与酿酒痕迹。泸州老窖的1573国宝窖池群始建于明代万历年间，连续使用从未间断，被誉为中国酿酒史上的“活文物”；宜宾五粮液的“包包曲”与陈年老窖，代表浓香型白酒的典型风味；绵竹剑南春则以“天益老号”古窖池与历史悠久闻名；水井坊遗址更是中国白酒的“活化石”。四川酒文化不仅关乎酿造，更渗透进社交、礼俗与诗酒风流：早在古代，酒便是川人待客、祭祀、节庆的重要角色，“无酒不成席”的饮酒礼仪在巴蜀尤为浓厚。酿酒的讲究、品鉴的门道与酒桌上的人情，共同构成独特的川酒文化。如今，酒文化旅游景区、白酒工业旅游与酒庄文化兴起，泸州老窖旅游区、五粮液旅游景区让游人可探窖池、品醇香、识酒礼。川酒的醇厚绵长，不仅是味觉记忆，更是巴蜀水土与人文的深情洗礼。值得一提的是，川酒不仅是一种饮品，更是一种文化社交：宴席上的敬酒礼、酒桌上的祝酒词，以及“开瓶闻香、举杯观色”的品鉴讲究，都让喝酒成为一门浸透人情的生活方式。近年来，白酒文化旅游与酒庄体验升温，让川酒的酿造之美、窖池之美与品饮之美被更多人亲身感受。', 'https://baike.baidu.com/item/%E4%B8%AD%E5%9B%BD%E9%85%92%E6%96%87%E5%8C%96/85580?fromtitle=%E9%85%92%E6%96%87%E5%8C%96&fromid=1122', '五粮液旅游景区,泸州老窖旅游区,剑南春,水井坊遗址', NULL, 'https://www.bilibili.com/video/BV1dz42117A3/?spm_id_from=333.337.search-card.all.click', '白酒,酿造,非遗,窖池,酒礼'),
(9, '川剧', '戏曲', '/images/culture/chuanju/chuanju_cover.jpg', '川剧是巴蜀最有代表性的地方戏曲，融合高腔、昆曲、胡琴、弹戏与灯调“五腔”，以变脸、帮腔、辑眼等绝技闻名，是一门活着的非遗艺术。', '川剧流行于四川、重庆及贵州、云南部分地区，是巴蜀最具代表性的地方戏曲剧种，也是中国戏曲宝库中一颗璀璨的明珠。它形成于清代，融会了昆腔、高腔、胡琴、弹戏与四川灯戏五种声腔，俗称“五腔共和”，在长期的融合中发展出自己独特的表演体系。川剧高腔最具特色，“一人唱、众人和”的帮腔如江河涛声，既烘托气氛又叙事抒情，配以锣鼓与辑眼，一唱三叹、曼味悠长；胡琴戏与弹戏则分别展现胡琴与梆子南路的风采。川剧剧目丰富，传统剧目数以千计，代表性剧目如《白蛇传》《柳荫记》《玉簪记》《变脸》等，题材涵盖历史、神话与市井生活。川剧表演讲究“唱、做、念、打”兼备，善于用夸张、幽默的程式营造生活气息，富于喜剧精神。川剧脸谱色彩斑斓、寓意鲜明，与变脸、吐火等绝技相得益彰。2006年，川剧列入首批国家级非物质文化遗产名录。如今，四川省川剧院、成都市川剧研究院等院团常年演出，成都在中小学试点“戏曲进校园”，锦江剧场、蜀风雅韵等成为观赏川剧的胜地。川剧既存古韵又接地气，是巴蜀人性格与审美的鲜活写照。值得一提的是，川剧在传承中不断寻求创新，新编剧目、青春版经典与文旅融合演出不断涌现，让古老的戏曲走近年轻人。作为一门活着的艺术，川剧既守住了“五腔共和”的根脉，又能与当代生活共鸣，这正是它历经数百年而不衰的魅力所在。', 'https://baike.baidu.com/item/%E5%B7%9D%E5%89%A7/294200', '锦江剧场,四川省川剧院,蜀风雅韵,成都川剧艺术中心', '沈铁梅,陈巧茹', 'https://www.bilibili.com/video/BV1H9yrBYEjw/?spm_id_from=333.337.search-card.all.click', '非遗,地方戏曲,五腔,高腔,巴蜀文化'),
(10, '川剧高腔', '戏曲', '/images/culture/chuanjugaoqiang/chuanjugaoqiang_cover.jpg', '川剧高腔是川剧五大声腔之一，“帮、打、唱”结合，一人领唱、众人帮腔，高亢悠远、情感浓烈，是川剧最具特色的声腔。', '川剧高腔是川剧五腔（昆、高、胡、弹、灯）中最具代表性的一种，源出明代弋阳腔，入川后与四川方言、民间音乐、锣鼓曲牌相融，形成独树一帜的风貌。高腔最大的特点是“帮、打、唱”三者紧密结合：“帮”即帮腔，由乐队或帮腔者以齐唱、领和的方式为台上角色演唱帮衬，既能替角色说出心中之言，又能以叙事口吻评点剧情，作用多端；“打”指锣鼓伴奏，不用丝竹管弦，仅以锣鼓敲击烘托气氛、节制节奏；“唱”则是角色的独唱部分。此种形式使高腔高亢清越、跌宕起伏，富于戏剧张力与抒情色彩。高腔剧目众多，如《玉簪记·琴挑》《柳荫记·送行》《红梅记》等，尤为擅长表现悲情与抒情段落。高腔的曲牌十分丰富，有“九宫十八调”之说，帮腔与锣鼓的配合讲究“跟腔行腔、以鼓带腔”。作为川剧声腔的“灵魂”，高腔不仅影响了川剧整体风格，也为研究中国戏曲声腔演变提供了珍贵样本。如今，高腔在四川省川剧院等院团得到重点保护与传承，老一辈名角与新秀同台，让这门“众声和鸣”的古老声腔继续在当代舞台上回响。值得一提的是，高腔的帮腔并非固定不变，而是可由帮腔者为不同情绪、不同剧情灵活选择，成为川剧“对话式”叙事的独特手法。它在改革开放后陆续复排的经典剧目中得以完整呈现，让观众得以领略这门源自明代、又在四川生根的古老声腔之美。', 'https://baike.baidu.com/item/%E9%AB%98%E8%85%94/3120679', '四川省川剧院,锦江剧场,蜀风雅韵', '沈铁梅,陈巧茹', 'https://www.bilibili.com/video/BV1j3411b7Mp/?spm_id_from=333.337.search-card.all.click', '川剧,声腔,非遗,帮腔,高腔'),
(11, '川剧吐火', '戏曲', '/images/culture/chuanjutuhuo/chuanjutuhuo_cover.jpg', '吐火是川剧中的神奇绝技，演员口含燃油喷吐火焰，瞬间火光升腾、惊心动魄，常与变脸相佐，是巴蜀戏曲中最具视觉冲击的表演。', '吐火是川剧表演中极具视觉冲击力的绝技之一，常与变脸、藏刀等联手呈现，令观众惊叹不已。表演时，演员口含特制的燃料（传统上多用脱脂煤油或酒），对着火源一口气喷出，顿时一团火焰腾空而起，短则一瞬、长则数尺，配以鼓点与身段，极具震撼。吐火讲究“气足、势准、时快”，能否一吐成火、焰形大小，均见演员火候。在川剧传统剧目中，吐火多用于表现神怪现身、妖魔作法或人物情怒等特殊情境，如《白蛇传》《火焰山》等戏中便有运用，起到了渲染气氛、外化情感的作用。作为川剧绝技的重要组成，吐火与变脸一样，长期依靠师徒相授的方式在班社中流传，传承人对燃料配比、吐气技巧与安全把控均有严格讲究。2006年川剧列入首批国家级非物质文化遗产名录后，吐火等绝技受到更多保护与关注。如今，观众可在锦江剧场、蜀风雅韵等剧场欣赏到吐火表演，它既是扣人心弦的技艺展示，也承载着川剧人代代相传的智慧与胆识，是巴蜀戏曲舞台上不可不看的一抹奇观。值得一提的是，吐火对火种、燃料与表演节奏的配合要求极高，演员既要保证火焰形态的观赏效果，又须严守安全规范，稍有不慎便可能受伤，因此这门绝技往往需数年苦练方能掌握，也格外考验演员之间的搭档默契与临场经验。此外，吐火与变脸的组合往往安排在剧目高潮，演员先变脸、再吐火，火光与脸谱交相辉映，将剧情推向顶点，这也是川剧绝技表演中最令观众屏息的瞬间之一。', 'https://baike.baidu.com/item/%E5%90%90%E7%81%AB/68636071?fromModule=search-result_lemma', '锦江剧场,蜀风雅韵,成都川剧艺术中心', NULL, 'https://www.bilibili.com/video/BV1sr4y1b7Tt/?spm_id_from=333.337.search-card.all.click', '川剧,绝技,非遗,吐火'),
(12, '四川清音', '戏曲', '/images/culture/sichuanqingyin/sichuanqingyin_cover.jpg', '四川清音是流行于巴蜀的说唱艺术，以琵琶、月琴等伴奏，调子清亮婉转，唱腔悠扬，是国家级非物质文化遗产。', '四川清音是流行于四川及重庆一带的传统说唱艺术，原名“唱小曲”“唱月琴”等，后固定称为“清音”，2008年列入国家级非物质文化遗产名录。它以抒情叙事见长，演唱者多为单人坐唱，自持月琴或由别人伴奏，配以琵琶、三弦、碗碗琴等，唱腔婉转清亮、韵味悠长。清音的曲牌十分丰富，分大调、小调和背工调等，既有抒情委婉的《布谷鸟儿咕咕叫》《赶花会》等，也有叙事幽默的作品。演唱讲究“字正腔圆、声情并茂”，一唱三叹、细腻动人，尤其善于用声音塑造不同的角色与情境。四川清音与四川扬琴、金钱板等共同构成巴蜀曲艺的多样性，与川剧清唱、谱子曲艺亦有渊源。近代以来，清音涌现出李月秋等名家，其演唱曾风靡一时。作为民间说唱的代表，清音从茶馆、书场走向舞台，生动记录了巴蜀民众的生活与情感。如今，清音在四川省曲艺研究院等单位得到保护传承，并不断尝试与当代音乐融合，让这门清亮婉转的古老曲艺在当下重新焕发魅力。值得一提的是，四川清音的演唱多辅以竹鼓、檀板击节，一个“打竹鼓”的动作便能让节奏与情绪陡转，别具风味。它题材贴近生活，或叙故事、或抒胸臆，嬉笑怒骂皆成文章，是巴蜀曲艺中雅俗共赏、广为流传的代表。此外，四川清音的许多经典段子如《布谷鸟儿咕咕叫》至今仍在传唱，其清丽婉转的声腔常被比作“东方夜莺”，在巴蜀曲艺舞台上独树一帜。', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E6%B8%85%E9%9F%B3?fromModule=lemma_search-box', '四川省曲艺研究院,锦江剧场,宽窄巷子', '李月秋,沈伐', 'https://www.bilibili.com/video/BV1eCe36GEVg/?spm_id_from=333.337.search-card.all.click', '曲艺,非遗,说唱,巴蜀文化'),
(13, '川北大木偶', '戏曲', '/images/culture/chuanbeidamuou/chuanbeidamuou_cover.jpg', '川北大木偶（杖头木偶）流行于南充等地，木偶形体高大、制作精良，表演细腻传神，被誉为“世界上罕见的木偶艺术”。', '川北大木偶又称杖头木偶，流行于四川南充、仪陇一带，2006年列入首批国家级非物质文化遗产名录，被誉为“世界上罕见的木偶艺术”。它以体型高大著称，传统木偶高可近一人半，重达数十斤，由双人操纵，动作却细腻传神，能完成洗脸、穿衣、吐火、变脸等高难动作，令人叫绝。川北大木偶的造型逼真，角色行当齐全，兼具戏曲的“唱做念打”，常演出《打神庙》《玉莲花》等传统剧目。其制作工艺讲究，木偶头部、身躯与机关均需精心雕刻与设计，便于完成丰富的手眼身法。大木偶最考验操纵者的默契与体力，两人配合如一，方能人偶合一、栩栩如生。作为巴蜀木偶艺术的代表，川北大木偶曾多次出访海外，向世界展示中国木偶技艺的精妙。如今，南充市大木偶剧院等传承团体持续创作演出，并不断创新剧目，让这一古老而独特的木偶艺术在当代舞台上继续大放异彩。值得一提的是，川北大木偶常与川剧唱腔、锣鼓配合演出，并吸收了杂技与舞蹈元素，既能演传统大戏，也能表演吐火、变脸等绝技，因而独具魅力。它不仅是剧场艺术，也成为南充对外文化交流的亮丽名片，深受海内外观众喜爱。此外，南充大木偶还曾多次赴海外演出，被赞为“中华一绝”，其巨型木偶在异国舞台上的精彩表演，成为对外文化交流中一张别致的文化名片。', 'https://baike.baidu.com/item/%E6%9C%A8%E5%81%B6%E6%88%8F%EF%BC%88%E5%B7%9D%E5%8C%97%E5%A4%A7%E6%9C%A8%E5%81%B6%E6%88%8F%EF%BC%89?fromtitle=%E5%B7%9D%E5%8C%97%E5%A4%A7%E6%9C%A8%E5%81%B6&fromid=1632468&fromModule=lemma_search-box', '南充大木偶剧院,南充,仪陇', NULL, 'https://www.bilibili.com/video/BV1hLPyeLE1J/?spm_id_from=333.337.search-card.all.click', '木偶,非遗,戏曲,南充'),
(14, '成都皮影', '戏曲', '/images/culture/chengdupiying/chengdupiying_cover.jpg', '成都皮影（四川皮影）以牛皮雕刻、光影演艺，影人形神兼备、唱腔为川剧调，是融美术与戏曲于一体的民间非遗艺术。', '成都皮影，又称灯影戏、四川皮影，是流行于成都及川西一带的民间艺术，以兽皮（多为牛皮）雕成人物、道具，借灯光映于幕布上表演故事，2008年列入国家级非物质文化遗产名录。四川皮影历史悠久，明清时期已相当繁盛，尤其成都皮影以制作精美、行当齐全著称，皮影人物高约一尺，雕刻讲究，刀法细致，色彩艳丽，头帽、服饰、脸谱均取川剧程式，栩栩如生。演出时由操纵者一人在幕前幕后灵活舞动，配以川剧唱腔与锣鼓，一人可演多个角色，幽默生动。成都灯影戏旧时在茶馆、庙会与婚丧节庆中大受欢迎，剧目多为历史、神话与民间故事。皮影艺术融绘画、雕刻、音乐、戏剧于一体，被誉为“电影的先祖”。如今，成都皮影在博物馆与非遗活动中得到保护展示，传承人也在尝试用皮影演绎当代题材，让这门古老的光影艺术继续在幕布上生辉。值得一提的是，成都皮影的唱腔多取川剧曲调，剧目分“单本”“连台”两类，故事多取自历史演义与民间传说。表演时人物可腾云、打斗、变身，幕台上光怪陆离，幕后台下掌声阵阵，把市井生活的趣味发挥得淋漓尽致。此外，成都皮影不仅是表演艺术，也是雕刻与彩绘的艺术，影人的镂空花纹繁复细腻，本身就是极具收藏价值的手工艺品。如今，这门光影艺术仍在博物馆与非遗展演中焕发光彩。', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E7%9A%AE%E5%BD%B1?fromModule=lemma_search-box', '成都博物馆,锦里,成都皮影博物馆', NULL, 'https://www.bilibili.com/video/BV1U4411V7M9/?spm_id_from=333.337.search-card.all.click', '皮影,非遗,民间艺术,光影'),
(15, '四川扬琴', '戏曲', '/images/culture/sichuanyangqin/sichuanyangqin_cover.jpg', '四川扬琴是巴蜀古典说唱的代表，以扬琴、碗碗琴等伴奏，坐唱抒情、声情并茂，有“坐地传情”之誉，是国家级非物质文化遗产。', '四川扬琴又称“扬琴戏”“琴书”，是流传于成都及川西平原的说唱艺术，2008年列入国家级非物质文化遗产名录。演出时由五人左右围坐，分别演奏扬琴、碗碗琴（京胡）、三弦、琵琶与鼓板，并兼作唱腔，无需化装与表演，凭说、唱与音乐感染听众，故有“坐地传情”“五方人人坐五方”之说。四川扬琴的曲调分为大调、月调、背工调三大类，唱腔丰富、故事性强，传统曲目多为《活捉三郎》《古鼓传书》等经典。音乐性尤为突出，扬琴音色清亮、碗碗琴婉转，五件乐器配合默契，与唱腔相得益彰。四川扬琴与四川清音、金钱板等共同构成巴蜀曲艺的丰富面貌，是文人气息与市井韵味兼具的雅致艺术。近代涌现出李德才等名家。如今，扬琴在四川省曲艺研究院等团体得到保护传承，老艺术家与年轻学员同台，让这门“五方和鸣、坐唱传情”的古老曲艺继续抚慰人心。值得一提的是，扬琴的唱腔讲究“以字行腔、字正腔圆”，不同角色由不同演唱者分担，人人既是乐手又是演员，配合如行云流水。它题材多取自民间故事与历史传奇，情节曲折、情感细腻，是巴蜀说唱艺术中文学性与音乐性兼具的代表。此外，四川扬琴的曲词文辞雅致，多取材于历史故事与民间传奇，唱来如叙家常，听来余音绕梁，是老成都书场茶楼里最受欢迎的一门雅曲。', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E6%89%AC%E7%90%B4?fromModule=lemma_search-box', '四川省曲艺研究院,锦江剧场', '李德才', 'https://www.bilibili.com/video/BV1TA4m1N7uT/?spm_id_from=333.337.search-card.all.click', '曲艺,非遗,说唱,巴蜀文化'),
(16, '蜀锦', '工艺', '/images/culture/shujin/shujin_cover.jpg', '蜀锦是中国四大名锦之一，以色彩鲜艳、纹样华美著称，兴起于秦汉、鼎盛于唐宋，是南方丝绸之路上的瑰宝，2006年列入首批国家级非遗。', '蜀锦是指成都及四川一带所产的织锦，与南京云锦、苏州宋锦、广西壮锦并称中国四大名锦，2006年列入首批国家级非物质文化遗产名录。蜀锦兴起于秦汉，盛于唐宋，因成都“锦官城”之名而闻名，是中国最早的无梭织锦之一。它以色彩鲜艳、纹样华美、经面浮花为主要特征，讲究“逐花异色”，可织出山水、花鸟、龙凤、古今人物等丰富图案，质地厚实、光泽华美。著名的“陵阳公样”以对鹿、对凤、斗羊等对称纹样著称，深深影响了唐代织锦艺术。蜀锦不仅是衣饰与贡品，更是南方丝绸之路上贸易与文化交流的载体，与蜀绣共同构成“锦绣天府”的美誉。其织造工艺繁复，从图案设色到上机织造均需匠人精心协作，尤其是花楼织机的提花技艺，代表了古代织锦工艺的高峰。如今，成都蜀锦织绣博物馆等机构保存着传统花楼织机与织造技艺，传承人在坚守古法的同时也将蜀锦融入服饰、文创与现代生活，让这门“锦官城”的古老技艺继续流光溢彩。值得一提的是，蜀锦的纹样会随时代而变，从汉代的经锦到唐宋的花楼织锦，再到当代融入现代审美的创新织品，始终在演进。它与蜀绣、蜀绘、桑蚕文化共同构成了成都“锦官城”的历史记忆，让丝绸文明在巴蜀大地生生不息。此外，蜀锦以“锦”命名成都，成就了“锦官城”“锦江”“锦里”等一连串与锦相关的地名，足见蜀锦对这座城市影响的深远。', 'https://baike.baidu.com/item/%E8%9C%80%E9%94%A6/304696', '成都蜀锦织绣博物馆,蜀锦工坊,锦里', NULL, 'https://www.bilibili.com/video/BV1mu411K76E/?spm_id_from=333.337.search-card.all.click', '非遗,四大名锦,丝织,巴蜀文化'),
(17, '成都漆艺', '工艺', '/images/culture/chengduqiyi/chengduqiyi_cover.jpg', '成都漆艺历史悠久，以天然生漆髹饰器具，工艺繁复、色彩瑰丽，雕填、堆光等技法精妙，与蜀绣蜀锦并称巴蜀工艺三绝。', '成都漆艺是流传于成都及四川地区的传统髹（xiū）漆工艺，2006年列入首批国家级非物质文化遗产名录。它以天然生漆为主要材料，在木、竹等胎体上一层一层髹涂、描饰、雕刻，工艺繁复、色泽光亮，色彩以红、黑、金为主，端庄典丽。成都漆艺历史极为悠久，可上溯至商周与战国时期，汉代成都已是全国著名的漆器产地，蜀郡、广汉郡的漆器远销各地，与蜀锦、蜀绣并称巴蜀工艺的杰出代表。成都漆艺技法多样，有雕填、堆光、雕漆隐花、银片平脱、罩漆彩绘等，尤其是“雕填”与“雕漆隐花”技艺，层次丰富、画面生动。其作品既有饮食器皿、佩饰，也有文房与陈设艺术品，兼具实用与审美。作为巴蜀漆艺的中心，成都宋元明清历代皆有漆器传世。如今，成都漆艺在成都漆器工艺厂（现为非遗传承单位）与传承人的坚守下得以延续，并与文创设计结合，走进现代生活，让这抹古老而华贵的漆彩继续辉映。值得一提的是，成都漆器旧时多用作日用器物与嫁娶陈设，色泽内敛、经久不坏，深受士人与百姓喜爱。它讲究“慢工细活”，一件作品往往要经数月甚至数年的层层髹涂，正是这份耐心与专注，成就了巴蜀漆艺的温润与厚重。此外，成都漆器曾随蜀地的井盐、蜀锦远销各地，是川人“精工细作”的又一张名片，其富丽而不失内敛的风格，至今为藏家所珍视。', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E6%BC%86%E8%89%BA?fromModule=lemma_search-box', '成都漆器工艺厂,成都博物馆,文殊坊', '宋西平', 'https://www.bilibili.com/video/BV12H4y1H7U7/?spm_id_from=333.337.search-card.all.click', '非遗,髹漆,手工艺,巴蜀文化'),
(18, '成都银花丝', '工艺', '/images/culture/chengduyinhuasi/chengduyinhuasi_cover.jpg', '成都银花丝以白银抽丝、平填焊接而成，纤细如发、玲珑剔透，被誉为“中国一绝”，是成都独特的金银细工非遗技艺。', '成都银花丝是成都独特的传统金银细工技艺，2008年列入国家级非物质文化遗产名录。它选用纯度很高的白银，经拉丝、手工平填、焊接、垒砌等多道工序而成，讲究“平、薄、细、亮”，成品纤细如发、玲珑剔透，极具观赏价值。银花丝以银丝盘绕、编织出花鸟、龙凤、人物与几何图案，再以银条层层垒砌边框，虚实相间，光影摇曳。成都银花丝历史可追溯到汉代，宋元明清历代发展，形成了浓郁的地方特色，尤以平填技艺为代表，与北方的累丝、景泰蓝等工艺迥然不同。作品既可用于首饰、摆件，也能与漆、竹、蜀绣等工艺结合，尽显蓉城工匠的心灵手巧。由于工序繁难且需长期磨练，银花丝一度面临后继乏人的困境，近年来随着非遗保护推进，传承人通过工作室、校园传承等方式培养新人，并不断创新设计，让这门“银丝上的芭蕾”在当代重新焕发光彩，成为成都工艺美术的精致名片。值得一提的是，银花丝与蜀绣、蜀锦、漆器等同为成都传统工艺的代表，共同体现了川人“精工细作、以巧取胜”的审美取向。今天，游客既可在博物馆欣赏古代银器，也能在工坊里亲手体验银丝的揉制，感受金属在指尖起舞的神奇。此外，银花丝常与漆艺、竹编、蜀绣等巴蜀工艺结合，制成摆件与首饰，尽显成都工匠在方寸之间营造精致的巧思。', 'https://baike.baidu.com/item/%E9%93%B6%E8%8A%B1%E4%B8%9D/2534125?fromModule=search-result_lemma', '成都(银花丝)城仙居,成都博物馆,文殊坊', '道安,倪成玉', 'https://www.bilibili.com/video/BV1AB4y1o7BK/?spm_id_from=333.337.search-card.all.click', '非遗,金银工艺,手工艺,成都'),
(19, '青神竹编', '工艺', '/images/culture/qingshenzhubian/qingshenzhubian_cover.jpg', '青神竹编源于眉山青神县，以“薄如蝉翼、细如发”的竹丝编出书画与器物，技艺绝伦，是国家级非遗与“中国竹编艺术之乡”。', '青神竹编是四川省眉山市青神县的传统手工艺，2008年列入国家级非物质文化遗产名录，青神也因此被誉为“中国竹编艺术之乡”。它以当地慈竹为原料，经选料、去青、启篾、分层、刮薄、染煮等多道工序，将竹片分割成“薄如蝉翼、细如发”的竹丝，再以精妙的手法编制成平面书画与立体器物。青神竹编分“粗篾”与“细篾”两大体系，粗篾多用于日常器具与包装，细篾则达到编织书画的高度：细篾可细至一根发丝，编出的熊猫、花鸟、名人题字栩栩如生，被誉为“竹编中的国画”。其代表性作品如《清明上河图》竹编长卷、《乐山大佛》等，曾作为国礼赠予外宾。青神竹编既保持了传统竹编的质朴，又将其推向了艺术与文化的高度，成为展现巴蜀匠心的绝佳载体。如今，青神建有国际竹编艺术博览馆与竹艺工坊，年轻人学习技艺、开发竹编文创与家居产品，让这门古老的竹编技艺在当代活起来、用起来。值得一提的是，青神竹编以“细篾”技艺闻名，编织时须运用挑、压、穿、插、锁等多种针法，图案与画面的明暗靠竹丝的疏密与光泽呈现，极考匠人的耐心与审美。如今竹编工艺与竹文化已深深融入青神的城乡生活与乡村振兴之中。此外，青神竹编曾多次作为国礼赠予国际友人，其“竹丝作画”的绝技常令观者惊叹，成为四川非遗对外展示中极具代表性的一张名片。', 'https://baike.baidu.com/item/%E9%9D%92%E7%A5%9E%E7%AB%B9%E7%BC%96?fromModule=lemma_search-box', '国际竹艺城,青神竹编博物馆,眉山青神', '陈云华', 'https://www.bilibili.com/video/BV1hF411V7yH/?spm_id_from=333.337.search-card.all.click', '非遗,竹编,手工艺,眉山'),
(20, '道明竹编', '工艺', '/images/culture/daomingzhubian/daomingzhubian_cover.jpg', '道明竹编源于崇州道明镇，以平面竹编与瓷胎竹编闻名，温润古朴、富有创意，是国家级非遗与川西林盘里的非遗名片。', '道明竹编是四川省崇州市道明镇的传统手工艺，2014年列入国家级非物质文化遗产名录，与青神竹编同为巴蜀竹艺的杰出代表。道明竹编历史悠久，自古就是川西竹编之乡，产品有平面竹编、立体竹编、瓷胎竹编等，尤以“瓷胎竹编”著称：以纤细竹丝紧扣瓷胎编织成罩，将竹艺与瓷器巧妙结合，温润古朴、独具韵味。道明的“竹里”建筑与竹艺村更将非遗与乡村文创结合，成为乡村振兴的典范。道明竹编讲求“细、柔、美”，一根竹丝可细若游丝，编织讲究平整、光洁、匀称，能编制出花鸟、几何图案与实用器物，既有传统纹样，也融入现代设计。它依托川西林盘的竹资源与生活方式而生，贴近日常、富有温度。如今，道明竹艺村吸引大量年轻人学习与体验竹编，非遗工坊与文创品牌不断涌现，让这门“代代手编、以竹为生”的古老技艺在乡村田园中重新焕发生机，成为川西非遗的一张亮丽名片。值得一提的是，道明竹编依托川西林盘，以竹的生活智慧为底色，既编出生产农具，也编出艺术雅器。竹艺村通过“非遗+文创+旅游”的模式吸引了大量游客与青年返乡，让一门以竹为生的老手艺，在田野与乡愁中重新生长。此外，道明的竹艺建筑与水乡林盘相映成趣，成为许多设计展与文创活动的举办地，让传统竹编在当代乡村与设计语境中获得新生。', 'https://baike.baidu.com/item/%E9%81%93%E6%98%8E%E7%AB%B9%E7%BC%96?fromModule=lemma_search-box', '崇州竹艺村,道明镇,竹里', '赵思进', 'https://www.bilibili.com/video/BV1UV411j77G/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,竹编,乡村文创,崇州'),
(21, '绵竹年画', '工艺', '/images/culture/mianzhunianhua/mianzhunianhua_cover.jpg', '绵竹年画是中国四大年画之一，以木板刻印、手工彩绘而成，色彩鲜明、寓意吉祥，乡土气息浓郁，2006年列入首批国家级非遗。', '绵竹年画是流行于四川绵竹一带的民间木版年画，与天津杨柳青、山东潍坊、苏州桃花坞年画并称中国四大年画，2006年列入首批国家级非物质文化遗产名录。它兴起于宋代，盛于明清，以木板刻印墨线、再手工填色绘制为主要工艺，与大多先印后套色的年画不同，绵竹年画尤其讲究“开脸”与手工彩绘，色彩鲜明、线条流畅，具有浓郁的乡土气息与民间幽默。绵竹年画题材丰富，有门神、神像、戏曲故事、民俗生活与讽刺幽默类，其中“老鼠嫁女”“三猴献寿”等篇章最为生动。年画讲究“红不刺目、黄不耀眼”，色彩明快而不失和谐，呈现出川人乐观幽默、热爱生活的性格。它与绵竹的造纸、竹编等民间工艺彼此辉映，是川西民间美术的杰出代表。如今，绵竹建有年画博物馆与年画村，国家级传承人带领画师创作新年画、开发文创，让“过年贴年画”的古老习俗以时尚的方式延续。值得一提的是，绵竹年画分“黑货”“红货”两类：黑货为墨线拓印、淡雅古朴，红货则手绘彩画、喜庆明快，门神、三星、斗方各具样式。它与春节习俗、民间信仰紧密相连，是川西百姓年节中不可或缺的精神寄托与吉庆装饰。此外，绵竹年画还吸收了川剧的题材与表现手法，画中人物神态生动、故事有趣，是研究川西民俗、戏曲与民间审美的重要载体。', 'https://baike.baidu.com/item/%E7%BB%B5%E7%AB%B9%E5%B9%B4%E7%94%BB?fromModule=lemma_search-box', '绵竹年画村,绵竹年画博物馆,绵竹', '李芳福,胡光葵', 'https://www.bilibili.com/video/BV1QUCdYfEKd/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,年画,民间美术,四大年画'),
(22, '羌绣', '工艺', '/images/culture/qiangxiu/qiangxiu_cover.jpg', '羌绣是羌族女性的传统手工刺绣，纹样古朴绚丽、色彩鲜明，记录着羌族的历史与信仰，2008年列入国家级非遗。', '羌绣是羌族民间流传的手工刺绣，主要流行于阿坝州茂县、汶川、理县一带的羌族聚居区，2008年列入国家级非物质文化遗产名录。羌绣历史悠久，与羌族人民的生活、信仰、服饰唇齿相依，女子从小便学绣，一针一线记录着山川草木、日月星辰与族群记忆。羌绣色彩鲜明、对比强烈，多采用红、黄、蓝、绿等饱和色彩，配以桃红、翠绿等对比色，耀目而热烈。纹样题材丰富，有羊角花、四瓣花、云纹、日月星辰与各种动植物图案，寓意吉祥与繁衍。针法多样，有挑花、纤花、铺花、纳花等，讲究对称、饱满与层次。羌绣的图案口传心授、代代相传，是羌族“无文字的历史书”。汶川地震后，羌绣作为灾后重建与女性脱贫的重要产业得到大力扶持，非遗工坊、合作社与文创品牌纷纷涌现，让这门古老刺绣从深山走向时尚舞台，成为展示羌族文化的一张亮丽名片。值得一提的是，羌绣还兼具实用与情感：围腰、云云鞋、头帕上的花饰，往往出自母亲与姑娘之手，一针一线寄托着祝福与心意。今天，羌绣既通过工坊研学让年轻人体验，也借助设计走进服饰与家居，让古老纹样在当代生活中继续流转。此外，羌绣的羊角花与四瓣花纹样，承载着羌族对自然与祖先的敬奉，是认识羌族文化不可或缺的一把钥匙。一针一线，绣出的是民族的记忆与温度。', 'https://baike.baidu.com/item/%E7%BE%8C%E6%97%8F%E5%88%BA%E7%BB%A3/4476985?fromtitle=%E7%BE%8C%E7%BB%A3&fromid=2509599', '中国古羌城,茂县坪头羌寨,汶川', '杨华珍,李兴秀', 'https://www.bilibili.com/video/BV1Vs411V7hC/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,羌族,刺绣,民族工艺'),
(23, '自贡扎染', '工艺', '/images/culture/zigongzaran/zigongzaran_cover.jpg', '自贡扎染又称“蜀缬”，以针扎、缬染在手织布上形成花纹，色晕自然、变化万千，是自贡历史悠久的传统染缬技艺。', '自贡扎染又称“蜀缬”，是自贡及川南一带历史悠久的传统手工染缬技艺，2008年列入国家级非物质文化遗产名录。它被称为“扎染”与“撮缬”，通过针扎、缝缬、撮缬等手法，将织物按设计绑扎后入染缸浸染，未被扎紧处上色、扎紧处保持原色，从而形成层次丰富的花纹，色晕自然、变幻无穷。自贡扎染以棉布、丝绸为胎，染料多用蓼蓝等天然植物，色调以蓝白为主，又有红、黄等多色套染，古朴素雅而又生动活泼。自贡扎染历史可追溯到秦汉，与蜀锦、蜀绣同为四川纺织艺术的重要组成，旧时产品除自用外还经盐道集散。它兼具实用与审美，可用于衣饰、布艺、家居等。如今，自贡扎染在自贡扎染工艺厂等传承单位与传承人手中得以延续，并与现代设计结合，开发出服装饰品与文创产品，让这门“一扎一染皆天成”的古老技艺在当代重放异彩。值得一提的是，自贡扎染的图案不由笔绘，而是靠扎缚的疏密与染液的渗透自然生成，每一件都是孤品，故有“一扎一染皆天成”之说。它既有蓝白相间的素雅，也能呈现多色晕染的浓烈，是川南民间审美与染色智慧的生动结晶。此外，扎染工艺也被广泛融入现代服饰与家居设计，古朴的蓝色花纹与现代剪裁相遇，让这门古老的手工染色重获时尚气息。蓝白之间，是川南人世代相传的染色智慧。', 'https://baike.baidu.com/item/%E8%87%AA%E8%B4%A1%E6%89%8E%E6%9F%93?fromModule=lemma_search-box', '自贡扎染工艺厂,自贡', '张晓平', 'https://www.bilibili.com/video/BV1JW4y1L7tc/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,扎染,染缬,自贡'),
(24, '分水油纸伞', '工艺', '/images/culture/fenshuiyouzhisan/fenshuiyouzhisan_cover.jpg', '泸州分水油纸伞以楠竹、皮纸、桐油手工制作，工艺繁复，古朴典雅、经久耐用，被誉为“中国民间伞艺的活化石”。', '分水油纸伞是四川省泸州市江阳区分水岭镇的传统手工艺，2008年列入国家级非物质文化遗产名录。它以楠竹为骨、皮纸为面、桐油为衣，经选料、制骨、糊伞、绘花、抹油等九十六道工序手工制成，不用金属，全靠竹、木、皮纸与桐油等天然材料，古朴典雅、经久耐用，反复撑收数千次而不坏，被誉为“中国民间伞艺的活化石”。分水油纸伞历史悠久，明末清初就已繁盛，曾行销西南乃至海外。伞面多绘山水、花鸟或写意图案，色彩淡雅、充满文人气息。它不仅是日用之具，更承载着巴蜀民间的审美与生活智慧。由于工艺繁复、效益偏低，油纸伞一度式微，近年随着非遗保护与文旅兴起，分水岭镇重建了油纸伞作坊与展示馆，传承人通过带徒、进校园与文创开发，让这门“满伞彩绘、雨中雅韵”的古老手艺重新撑开，成为泸州文化的一张诗意图腾。值得一提的是，分水油纸伞的托花、绘花与抹油道道皆有讲究，尤其伞面所绘的山水花鸟，使一把雨伞兼具实用与观赏价值。它既能挡雨遮阳，也常被用作舞台道具、婚庆与文旅纪念品，让古老手艺在当下找到了新的用武之地。此外，一把伞从劈竹到成伞需经近百道工序，往往要花费一个人数日之功，正因如此，油纸伞才显得格外珍贵而富有温度。一伞一世界，撑起的是手艺，也是乡愁。', 'https://baike.baidu.com/item/%E5%88%86%E6%B0%B4%E6%B2%B9%E7%BA%B8%E4%BC%9E?fromModule=lemma_search-box', '分水岭镇,泸州分水油纸伞博物馆', '毕六福', 'https://www.bilibili.com/video/BV1R1421m7DJ/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,油纸伞,手工艺,泸州'),
(25, '糖画', '工艺', '/images/culture/tanghua/tanghua_cover.jpg', '糖画（成都糖画）以热熔糖液在石板上作画，一气呵成、亦糖亦画，可观可食，是巴蜀街头脍炙人口的民间非遗技艺。', '糖画是流传于四川成都及周边地区的民间艺术，俗称“倒糖饼儿”“糖灯影”，2008年列入国家级非物质文化遗产名录。它以铜勺舀起热熔的麦芽糖（饴糖），在光滑的石板或金属板上运腕作画，或提、或顿、或拉丝，趁热一气呵成，转眼间便绘出龙、凤、蝴蝶、花鸟、人物等图案，插上竹签便成一枚可看可吃的糖画。成都糖画讲究“勺为笔、糖为墨、手为心”，技艺娴熟的艺人可闭目成画，线条流畅、造型生动，极具民间智慧与艺术趣味。糖画旧时多见于庙会、集市与街头巷尾，是几代川人共同的童年记忆，承载着巴蜀市井的生活温度。它以最朴素的材料创造出最生动的美感，是“民间艺术活化石”。如今，糖画艺人活跃在锦里、宽窄巷子、各大庙会与非遗活动中，吸引着游人尤其是儿童的驻足，这门甜蜜的民间艺术依旧滋养着成都的街头烟火。值得一提的是，糖画艺人常以勺子为笔、以糖液为墨，运腕之间便能成画，讲究“提、顿、顿、拉”一气呵成，图案可分为平面糖画与立体盛盘两类。它既是庙会上孩子们追逐的甜蜜记忆，也是一门融绘画与技艺于一体、可观可食的民间绝活。此外，糖画因取材简易、老少皆宜，常在庙会与节庆中现身，它把甜蜜与艺术结合，成为几代川人心中难忘的童年记忆。一口甜、一抹色，成了川人共同的年味记忆。', 'https://baike.baidu.com/item/%E7%B3%96%E7%94%BB/10597730', '锦里,宽窄巷子,成都大庙会', '樊德然', 'https://www.bilibili.com/video/BV1DT4y1q7Ec/?spm_id_from=333.337.search-card.all.click', '非遗,糖画,民间艺术,成都'),
(26, '荣县土陶', '工艺', '/images/culture/rongxiantutao/rongxiantutao_cover.jpg', '荣县土陶以本地页岩与柴窑、地窑烧制，土陶茶壶、泡菜坛等质朴粗犷、透气性好，是有着千年历史的民间陶瓷技艺。', '荣县土陶是四川省自贡市荣县的传统陶瓷技艺，历史可追溯到唐宋时期，是巴蜀地区重要的民间陶艺之一，近年来列入四川省非物质文化遗产名录。荣县土陶以当地特有的页岩为原料，经碎炼、制坯、雕刻、晒干、入窑烧制等多道工序而成，产品多为日用之器：泡菜坛、灰陶罐、土陶茶壶、砂锅与酒具等，尤以“泡菜坛”与“土陶茶壶”最负盛名。土陶制品透气性好、保温性强，用来泡菜不臭、炖汤留香，是川人厨房里再熟悉不过的老伙计。荣县土陶造型朴实、色泽温润，既有实用的厚实，又有民间的拙朴，或刻花、或堆塑，散发着川南乡土的质朴。它多以传统龙窑、柴窑烧造，火候与土质的配合全靠匠人经验。如今，荣县通过土陶技艺传承与陶艺小镇建设，让老匠人与年轻陶艺工作者同台，开发茶器、花器与文创陶品，使这门带着泥火香的古老手艺在当代焕发新的生机。值得一提的是，荣县土陶的“泡菜坛”坛沿注水、密封性好，是川渝人家腌菜的常用器皿，也常用作馈赠外地亲友的乡土礼物。今天，荣县在传承土陶技艺的同时，打造陶艺主题街区与体验工坊，让制陶从作坊走向研学与文创，让“一把泥土、一把火”的川南民艺重获新生。此外，荣县土陶的茶壶因透气性好，用来泡茶不易变味，深受茶客喜爱，也让这门乡土陶艺在茶文化中占据了独特的一席之地。', 'https://baike.baidu.com/item/%E8%8D%A3%E5%8E%BF%E5%9C%9F%E9%99%B6?fromModule=lemma_search-box', '荣县土陶创意基地,荣县大佛,自贡', NULL, 'https://www.bilibili.com/video/BV1ZeFGzmEbi/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,土陶,陶瓷,自贡'),
(27, '蒙顶茶文化', '饮食', '/images/culture/mengdingchawenhua/mengdingchawenhua_cover.jpg', '蒙顶山是世界茶文化发源地，蒙顶茶自唐代即为贡茶，素有“扬子江中水，蒙山顶上茶”之誉，茶史与茶技交相辉映。', '蒙顶山位于雅安市名山区，被誉为“世界茶文化发源地”，其茶史可上溯至西汉，相传吴理真在蒙顶山手植茶树，开创人工种茶之先河。蒙顶茶自唐代便被列为贡茶，宋代设置茶马互市，明清延续不绝，素有“扬子江中水，蒙山顶上茶”之誉。蒙顶山盛产甘露、黄芽、石花等名茶，其中“蒙顶甘露”为烘青名茶代表，蒙顶黄芽更是黄茶中的珍品。蒙顶茶文化不仅关乎制茶，更衍生出独特的茶礼、茶艺与茶道：蒙顶山的“龙行十八式”茶技，将长嘴铜壶抛、转、掺、倒融入武术与舞蹈，把掺茶变成一门表演艺术，成为巴蜀茶文化的生动写照。蒙顶山现存古甘露寺、天盖寺、皇茶园等遗迹，古茶树与石碑见证千年茶史。蒙顶茶还随茶马古道远销藏区，深深影响了藏茶文化。如今，蒙顶山景区与茶博馆将茶史、茶技、茶旅融为一体，每到采茶时节游人如织，让“茶祖故里、世界茶源”的文化名片愈发鲜明。值得一提的是，蒙顶山茶自古与茶马互市紧密相连，这里的茶叶经雅安、康定远销藏区，演化为后世的“藏茶”，深深影响了高原民族的饮食结构。今天，蒙顶山茶的采制与蒙顶黄芽非遗技艺仍在延续，“茶旅融合”让“世界茶源”的金字招牌愈发闪亮。此外，蒙顶山的“皇茶园”与古茶树被视作茶史上珍贵的活文物，每年春季的开园采茶与祭祀茶祖活动，都吸引着众多茶人前来朝圣。', 'https://baike.baidu.com/item/%E8%92%99%E9%A1%B6%E5%B1%B1%E8%8C%B6%E6%96%87%E5%8C%96/4943089?fromModule=search-result_lemma', '蒙顶山,天盖寺,雅安名山', NULL, 'https://www.bilibili.com/video/BV1HV411s7mW/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '茶文化,贡茶,非遗,雅安'),
(28, '郫县豆瓣', '饮食', '/images/culture/pixiandouban/pixiandouban_cover.jpg', '郫县豆瓣是川菜之魂，以蚕豆、辣椒发酵酿制，色泽红亮、酱香浓郁，被誉为“川菜之魂”，其酿制技艺为国家级非遗。', '郫县豆瓣是四川省成都市郫都区（原郫县）的特产，它是用蚕豆、辣椒与面粉经长时间发酵酿制而成的调味品，色泽红亮、酱香浓郁、麻辣鲜香，被誉为“川菜之魂”。郫县豆瓣历史悠久，相传始于清康熙年间，由福建移民在郫县结合当地气候与物产创造而成，经数百年传承，形成了“翻、晒、露”的独特工艺：每年翻晒上千次，日晒夜露，历经数月甚至数年而成，酶香生成、风味醇厚，越陈越香。它是川菜中回锅肉、麻婆豆腐、豆瓣鱼等经典名菜的灵魂调味料，与花椒、泡椒共同构成川菜“麻辣鲜香”的味觉基底，与川菜文化唇齿相依。郫县豆瓣传统制作技艺已被列入国家级非物质文化遗产名录，郫都区建有豆瓣博物馆与工业旅游区。如今，郫县豆瓣既是家庭厨房的必备之味，也是出口海外的川味名片，让“川菜之魂”香飘世界。值得一提的是，郫县豆瓣的酿造还要“翻、晒、露”并借当地特有的温润气候与水源，形成难以复制的风味。它既是川菜不可替代的“灵魂调味”，也是成都对外交流的味觉名片，让世界从一勺红亮的豆瓣酱里，读懂川菜的密码。此外，郫县豆瓣的制作技艺世代薪火相传，掌握“翻晒露”火候的老师傅尤为难得，使这门手艺成为川菜文化中不可或缺的一环。一勺红亮的豆瓣酱，正是川菜最深的底色。', 'https://baike.baidu.com/item/%E9%83%AB%E5%8E%BF%E8%B1%86%E7%93%A3?fromModule=lemma_search-box', '郫县豆瓣博物馆,郫都区,成都川菜博物馆', NULL, 'https://www.bilibili.com/video/BV1454y1G7BG/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,川菜,调味,郫都'),
(29, '保宁醋', '饮食', '/images/culture/baoningcu/baoningcu_cover.jpg', '保宁醋产自阆中，是中国四大名醋之一，以麸皮、大米与数十味中药制曲酿造，色褐香浓、酸味綿长，酿制技艺为国家级非遗。', '保宁醋是中国四大名醋（山西老陈醋、镇江香醋、永春老醋、保宁醋）之一，产自四川省阆中市（古称保宁）。它创始于明末清初，已有三百多年历史，以麸皮、大米、小麦等为原料，以砂仁、白蔻、黄连等数十味中药材制曲发酵，经熏醅、淋醋、陈酿等多道工序而成，色泽棕红、香气浓郁、酸味綿长、色香俱佳，故有“五味合一”之说。保宁醋不仅是调味佳品，旧时还被视为药醋，具有开胃养生的功效，与阆中的饮食、药业文化息息相关。“一菜一格，百菜百味”的川菜中，保宁醋常用于凉拌、蘸食与糖果调味，是川味中酸香的来源之一。其独特的药曲制曲工艺在国内食醋中别具一格，保宁醋传统酿制技艺亦列入国家级非物质文化遗产名录。如今，保宁醋业秉承古法酿造，产品畅销全国并出口，成为阆中古城与四川饮食文化的一张韵味悠长的名片。值得一提的是，保宁醋的“药曲”是它区别于其他名醋的独门秘方，用之酿出的醋香气浓郁、入口回甘，久存不坏。旧时阆中醋坊林立、商队络绎，一坛坛保宁醋经水路远销各地，是阆中商业与饮食繁荣的重要见证。此外，阆中依托保宁醋形成了独特的“醋文化”，醋坊、醋宴与醋工业旅游相互结合，让一瓶老醋成为古城的一张韵味悠长的名片。一瓶老醋，酿尽阆中三百年的烟火滋味。', 'https://baike.baidu.com/item/%E4%BF%9D%E5%AE%81%E9%86%8B?fromModule=lemma_search-box', '阆中古城,保宁醋博物馆,阆中', NULL, 'https://www.bilibili.com/video/BV1uf421272R/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '名醋,非遗,酿造,阆中'),
(30, '四川泡菜', '饮食', '/images/culture/sichuanpaocai/sichuanpaocai_cover.jpg', '四川泡菜以多种蔬菜入坛泡制，酸辣鲜香、爽脆开胃，是川菜“三香”之外的头道风味，制作技艺历史悠久、家喻户晓。', '四川泡菜是川渝人家普遍制作的传统发酵蔬菜，以萝卜、豇豆、嫩姜、辣椒、白菜等多种蔬菜，加盐、花椒、姜蒜、白酒与冰糖入陶坛泡制而成，经乳酸发酵形成酸辣鲜香、爽脆开胃的风味，是川菜除了麻辣之外的另一重头风味。四川泡菜历史悠久，早在秦汉时期巴蜀人家就已开始制泡菜，千百年来成为川人餐桌与厨房的标配，而“泡菜坛子”更是川渝家庭的象征之一。泡菜讲究“老酸水”，即经年使用、风味醇厚的泡菜水，配菜与调味时常常淋上一勺泡菜水提味。川菜中的鱼香、泡椒系列菜品，离不了泡椒、泡姜、泡豇豆等泡菜，泡菜也因此被称为川菜的“味觉基因”。眉山东坡区更被誉为“中国泡菜之乡”，建有中国泡菜城与泡菜博物馆。如今，四川泡菜制作技艺被列入非物质文化遗产名录，既有家庭里代代相传的乡村泡菜，也有规模化生产的工业泡菜，让这道酸辣开胃的川味走进千家万户。值得一提的是，川渝人家几乎家家都有一坛“老酸水”，讲究的是一坛泡菜越泡越香，蔬菜可随季节轮换，辣椒、嫩姜、青菜皆可入坛。它既是餐桌上的开胃小菜，也是川菜调味的隐形主角，泡菜坛因此成为巴蜀厨房里最具烟火气的器物之一。此外，泡菜的制作看似简单，实则讲究水温、盐度与密封，一坛好泡菜往往成为一家人的骄傲，也是川渝人家待客时最日常的风味。', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E6%B3%A1%E8%8F%9C?fromModule=lemma_search-box', '中国泡菜城,眉山东坡区,成都川菜博物馆', NULL, 'https://www.bilibili.com/video/BV16x4y1n7PV/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,泡菜,饮食,眉山'),
(31, '火锅文化', '饮食', '/images/culture/huoguowenhua/huoguowenhua_cover.jpg', '川渝火锅源于码头船工，以牛油辣椒熬汤、百菜皆可烫，麻辣鲜香、围锅共食，是巴蜀最具烟火气的饮食文化符号。', '火锅是川渝地区最具代表性的饮食文化现象，源于长江、嘉陵江码头船工的粗放饮食：旧时船工将牛毛肚、鸭肠等下水入麻辣沸腾的汤锅烫食，既驱寒又省钱，后经餐馆改良定型，逐渐发展成风靡全国的美食。川渝火锅以“麻、辣、鲜、香、烫”见长，锅底用牛油、二荆条辣椒与汉源花椒等熬制，红亮醇厚、越煮越香，与清油锅底、鸳鸯锅并行共存。其讲究的不仅是食材，更是一种社交方式：毛肚“七上八下”、鸭肠“提三摆三”，一桌人围锅共食、边烫边聊，热热闹闹。蘸碟也有讲究，香油蒜泥、干碟与蚝油碟各有拥趸。火锅在川渝已成为深植生活的文化：一年四季皆可吃火锅，夏日配冰粉、冬日围炉暖身，火锅店遍布街头，形成庞大的产业链与文化景观。作为巴蜀饮食的代表，火锅体现了川人火辣豪爽、乐群尚情的性格，也以其兼容并包的锅底走向世界，成为中华美食最生动的名片之一。值得一提的是，川渝火锅的店堂文化也十分独特：一锅红汤、几把竹椅、数位好友，吃得酣畅、聊得痛快，火锅早已超越了“吃”的本身，成为一种社交与生活方式。它也带动了底料、蘸料、食材等一条庞大的产业链，成为川渝极具辨识度的城市名片。此外，锅底、蘸料与食材的搭配也各有流派，成都偏重香辣柔和、重庆偏爱麻辣猛烈，一江之隔便吃出两种性格，正是巴蜀饮食的生动写照。', 'https://baike.baidu.com/item/%E7%81%AB%E9%94%85/274015?fromModule=search-result_lemma', '成都火锅店街,春熙路,锦里', NULL, 'https://www.bilibili.com/video/BV1CmTizrE3g/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '火锅,饮食文化,麻辣,巴蜀文化'),
(32, '盖碗茶文化', '饮食', '/images/culture/gaiwanchawenhua/gaiwanchawenhua_cover.jpg', '盖碗茶以茶盖、茶碗、茶船三件套得名，是成都茶馆文化的主角，一盏茶、一把竹椅，尽显川人怡然自得的市井风情。', '盖碗茶是四川茶馆文化的代表，因其“一盖、一碗、一船”三件套而得名。相传盖碗茶起源于唐代四川，由当时的茶具演变而来，茶船托底防烫、茶盖保温防尘、茶碗盛茶，“茶盖启落之间，茶香四溢”，与茶道器具有关。川人饮盖碗茶，多讲究一个“摆”字：往茶馆里竹椅上一坐，沏上一碗茉莉花茶或竹叶青，边喝边摆龙门阵，说书、下棋、打牌、采耳，生活节奏顿时慢了下来。成都茶馆遍布街巷，人民公园鹤鸣茶社、宽窄巷子、太古里等地皆是听茶、采耳、晒太阳的好去处。盖碗茶不仅是一种饮品，更是一种生活方式与社交空间，体现了川人乐观、悠闲、注重享受的生活态度。现代成都兴起的“新中式茶馆”依然以盖碗茶为灵感，承续着这种兼容传统与时尚的川味生活美学，使盖碗茶成为巴蜀文化中最具亲和力的一张名片。值得一提的是，盖碗茶的讲究还体现在“一看、二闻、三品”：掀盖闻香、以盖拨茶，动作优雅，尽显从容。它既是成都茶馆的日常，也是老成都人情与市井生活的缩影，如今更成为游客体验慢生活的必选项目。此外，盖碗茶在川渝也发展出“掺茶”技艺与茶馆评书、川剧坐唱等配套文化，一碗茶里，泡着巴蜀人悠闲、从容而热闹的市井人生。一盏盖碗茶里，盛着的是成都人待客与自处的日常仪式，也盛着一城悠闲。', 'https://baike.baidu.com/item/%E7%9B%96%E7%A2%97%E8%8C%B6/158324?fromModule=search-result_lemma', '鹤鸣茶社,人民公园,宽窄巷子,彭镇老茶馆', NULL, 'https://www.bilibili.com/video/BV15dxPzQEuM/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '茶文化,茶馆,市井生活,成都'),
(33, '古蜀金沙文明', '历史', '/images/culture/gushujinshawenming/gushujinshawenming_cover.jpg', '金沙遗址是古蜀文明的又一高峰，太阳神鸟金饰、金面具见证三千年古都的灿烂，“太阳神鸟”已成为中国文化遗产标志。', '金沙遗址位于成都市青羊区，是距今约3200至2600年前古蜀王都的遗址，2001年发现，被誉为“21世纪中国首个重大考古发现”，与三星堆一脉相承，共同构成古蜀文明的先后篇章。遗址出土了太阳神鸟金饰、金面具、玉琮、金冠带、十节玉琮等珍贵文物数千件，其中“太阳神鸟”金饰以镂空工艺表现四只神鸟环绕十二道太阳光芒旋转的图案，构图巧妙、寓意深远，已被确定为中国文化遗产标志。金沙遗址与三星堆同为古蜀文明的代表，展现了古蜀人高度发达的金玉工艺、祭祀体系与宇宙观，证明成都平原是中华文明的重要发源地之一。博物馆在遗迹馆原址上展示了祭祀区与大量文物，让人直观感受古蜀王都的辉煌。金沙不仅是考古学的丰碑，更是成都三千多年城市文明延续不乱的见证，以其神秘的魅力吸引着世界目光。值得一提的是，金沙以“太阳神鸟”金饰最为人熟悉，它轻薄如纸、镂空精巧，四只神鸟与十二道光芒旋转不息，被解读为古蜀人太阳崇拜与宇宙想象的具象。它与三星堆一脉相承，让古蜀文明的脉络得以连贯，也让成都的城市文脉可追溯到三千多年之前。此外，金沙与三星堆共同证明，成都平原早在三四千年前就已孕育出高度发达的文明，是中华文明多元一体格局中不可替代的一极。', 'https://baike.baidu.com/item/%E5%8F%A4%E8%9C%80%E9%87%91%E6%B2%99/61760601?fromModule=search-result_lemma', '金沙遗址博物馆,三星堆博物馆,成都博物馆', NULL, 'https://www.bilibili.com/video/BV1ok4y1y7Mi/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '古蜀文明,考古,太阳神鸟,博物馆'),
(34, '蜀道文化', '历史', '/images/culture/shudaowenhua/shudaowenhua_cover.jpg', '蜀道是古代穿越秦岭巴山、连接中原与四川的交通体系，以剑门蜀道最为险峻，栈道古柏、诗篇无数，是中华交通与文化史上的奇观。', '蜀道是古代连接中原与巴蜀的交通体系，穿越秦岭、大巴山，包括金牛道、米仓道、阴平道、荔枝道等多条路线，其中以“剑门蜀道”最为闻名。蜀道自古艰险，李白“蜀道之难，难于上青天”将其写入诗篇，栈道沿崖凿孔架木，飞桥跨谷、天梯石栈，充分展现了古代巴蜀人民的工程智慧。蜀道不仅是军事与商旅通道，更是文化交流的纽带：中原的礼乐、佛教与巴蜀的物产、文化沿此往返，留下了大量碑刻、石窟与历史遗迹。剑门关扼守蜀道之险，翠云廊古柏参天，明月峡古栈道与古驿道、栈道、纤道相互交叠，被称为“中国交通史博物馆”。昭化古城、剑门古镇与朝天明月峡皆依蜀道而生，构成了丰富多彩的蜀道文化景观。蜀道沿线还传颂着五丁开山、姜维守关、黄忠斩夏侯渊等历史传说。如今，剑门蜀道已被列为世界遗产预备名录与全国重点文物保护单位，徒步蜀道、寻访古柏成为热门旅游主题，让这条千年古道在当代重焕生机。值得一提的是，蜀道沿线的古柏如“翠云廊”绵延三百余里，被誉为“世界奇观”，见证了古人护路护树的智慧；而明月峡一段古栈道与驿道、纤道、公路、铁路共存一峡，被称为“中国交通史博物馆”，堪称一部立体的交通演进史。此外，蜀道之上还留下了大量的诗歌、碑刻与摩崖造像，李白、杜甫、陆游等都曾在蜀道上留下传世篇章，使其成为一条诗意的文化走廊。', 'https://baike.baidu.com/item/%E8%9C%80%E9%81%93/81963?fromModule=search-result_lemma', '剑门关,明月峡,翠云廊,昭化古城', NULL, 'https://www.bilibili.com/video/BV1ZVZ9BxE9J/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '蜀道,古栈道,剑门关,交通史'),
(35, '都江堰水利文化', '历史', '/images/culture/dujiangyanshuiliwenhua/dujiangyanshuiliwenhua_cover.jpg', '都江堰是两千多年前李冰父子主持修建的无坝引水工程，至今仍灌溉成都平原，是世界水利文化的典范与世界文化遗产。', '都江堰位于成都平原西部的岷江出山口，是战国末期秦国蜀郡太守李冰父子在前人基础上组织修建的大型无坝引水水利工程。它由鱼嘴分水堤、飞沙堰溢洪道、宝瓶口引水口三大主体工程构成，科学地解决了江水自动分流、自动排沙、控制进水量等问题，使成都平原“水旱从人，不知饥馑”，成为沃野千里的“天府之国”。都江堰最令人惊叹的是其“无坝引水、因势利导”的治水智慧，做到了“深淘滩、低作堰”“遇弯截角、逢正抽心”，体现了中国古代“天人合一”的哲学。工程建成于公元前256年左右，至今两千多年仍在持续发挥灌溉与防洪作用，是世界上年代最久、唯一留存、以无坝引水为特征的宏大水利工程，2000年列入世界文化遗产名录，后又入选世界灌溉工程遗产。都江堰周边还有二王庙、伏龙观、安澜索桥、离堆公园等众多遗迹。它不仅是中华治水文明的丰碑，也是人与自然和谐共生的生动范例。值得一提的是，都江堰两千多年来仍持续发挥灌溉与防洪作用，灌区面积近千万亩，成就了“水旱从人、不知饥馑”的天府之国。它蕴含的“深淘滩、低作堰”与“天人合一”的治水哲学，至今仍为水利工程提供着宝贵的思想滋养。此外，都江堰的建设还体现了古代“顺势而为、因势利导”的治水理念，其“鱼嘴、飞沙堰、宝瓶口”三大工程彼此配合，堪称古代水利科技的杰出典范。', 'https://baike.baidu.com/item/%E9%83%BD%E6%B1%9F%E5%A0%B0/122963?fromModule=search-result_lemma', '都江堰景区,二王庙,安澜索桥,离堆公园', '李冰', 'https://www.bilibili.com/video/BV1JK42147uN/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '世界遗产,水利工程,治水,历史'),
(36, '自贡盐文化', '历史', '/images/culture/zigongyanwenhua/zigongyanwenhua_cover.jpg', '自贡以盐立市，凿井取卤、火井煮盐的历史近两千年，燊海井见证盐都辉煌，盐业催生了会馆、盐帮菜与灯会。', '自贡素有“千年盐都”之称，其凿井取卤、煎盐的历史可上溯至东汉，因盐业而兴市、而富庶。自贡盐场鼎盛时盐井数以千计，凿井、汲卤、输卤、煎盐的工艺震撼一时：明清时期，自贡人首创冲击式顿钻凿井法，打出了世界上第一口超千米深井——燊海井，开创了人类钻井技术的新纪元。盐业不仅带来了巨大的财富，也深刻塑造了自贡的城市与文化：盐商会馆、盐业行帮、盐工习俗、盐运古道、盐商宅院遍布城乡，自贡盐业历史博物馆（西秦会馆）便是其缩影。盐业之利还催生了精致讲究的“盐帮菜”与烟火璀璨的自贡灯会，养成了自贡人敢为人先、精于工艺的性格。盐井、盐道与盐运码头至今仍可寻迹，燊海井、盐业历史博物馆与各类盐业遗址共同见证着这座城市的盐史荣光。如今，自贡依托盐业遗产发展文旅与工业旅游，让千年盐都的故事在当代继续传扬。值得一提的是，盐业之利不仅催生了会馆、钱庄与盐运码头，也孕育了自贡的盐帮菜与灯会，使这座“千年盐都”兼具商贸的繁盛与市井的风雅。今天，自贡以盐业遗产、恐龙化石与彩灯并称“盐龙灯”，构成独具特色的城市文化名片。此外，自贡的盐运古道与盐运码头至今仍可寻迹，串起了古城的街巷与遗存，让今人得以触摸千年盐都的往昔繁华。盐都之名，由此而来，历久不衰。', 'https://baike.baidu.com/item/%E4%BA%95%E7%9B%90%E6%96%87%E5%8C%96?fromtitle=%E8%87%AA%E8%B4%A1%E7%9B%90%E6%96%87%E5%8C%96&fromid=62846946&fromModule=lemma_search-box', '燊海井,自贡盐业历史博物馆,西秦会馆', NULL, 'https://www.bilibili.com/video/BV1W7QwBgExh/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '盐业,工业遗产,自贡,历史'),
(37, '移民文化', '历史', '/images/culture/yiminwenhua/yiminwenhua_cover.jpg', '“湖广填四川”是明清时期的大规模移民，使四川的人口、方言与饮食文化焕然一新，川剧、川菜与客家文化皆与之密切相关。', '“湖广填四川”是明清时期政府对四川的大规模移民运动。宋元之际与明末清初的连年战乱，使四川人口锐减，清政府为恢复生产，鼓励湖广、江西、福建、广东等地的百姓迁入四川。这场持续百余年的移民潮，深刻重塑了四川的人口构成、语言与社会面貌：巴蜀方言在融合中形成，川剧吸收了各地方声腔，川菜也汇合了移民带来的烹饪技艺，而客家人迁入更在成都东山一带形成客家文化区，洛带古镇即为“西部客家第一镇”。移民带来了各地的手艺、信仰与习俗，使四川成为多元文化交融之地。移民以“会馆”凝聚同乡，湖广会馆、广东会馆、江西会馆等遍布城乡；家谱、墓碑与口头传说中的“祖籍”记忆，至今仍深植于川人的家族认同。移民文化既是一部悲壮的迁徙史，也是一部开放包容的融合史，它铸就了川人开拓进取、兼容并包的性格，是理解四川人精神气质与巴蜀文化底蕴不可回避的一把钥匙。值得一提的是，移民带来的不仅有方言与菜肴，更有崇文重教、敢闯敢拼的移民精神，这种精神深刻融入了川人的性格。今天，寻根问祖、会馆文化节与客家民俗体验方兴未艾，让“从哪里来”的追问成为理解巴蜀文化包容性的一把钥匙。此外，这场移民运动还深刻影响了四川的宗族结构、地名与饮食，许多川人至今仍能从家谱与口传中，寻到一段跨越数省的家族迁徙史。', 'https://baike.baidu.com/item/%E7%A7%BB%E6%B0%91%E6%96%87%E5%8C%96?fromModule=lemma_search-box', '洛带古镇,湖广会馆,成都博物馆', NULL, 'https://www.bilibili.com/video/BV19A411M7mm/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '移民,历史,客家,文化交流'),
(38, '自贡灯会', '民俗', '/images/culture/zigongdenghui/zigongdenghui_cover.jpg', '自贡灯会始于唐宋、盛于当代，以巨型彩灯、瓷灯、变光技术闻名，被誉为“天下第一灯”，是国家级非物质文化遗产。', '自贡灯会是四川自贡地区的传统民俗活动，始于唐宋年间，至今已有千余年历史，其彩灯制作技艺被列入国家级非物质文化遗产名录，自贡也享有“南国灯城”“天下第一灯”之美誉。自贡灯会以规模宏大、构思巧妙、制作精良著称，善于以瓷器、玻璃瓶等非常规材料制灯，配以现代光、声、动技术，将人物、神话、山水的彩灯组合成移步换景的奇幻世界。唐宋时自贡已形成天灯、河灯等习俗，明清时作为盐商耍灯的传统延续至今，每年春节前后自贡都会举办灯会，吸引八方游客。2000年以来，自贡灯会更走向海外，在数十个国家和地区举办巡展，成为中华文化“走出去”的亮丽名片。自贡中华彩灯大世界已成为灯会主场，彩灯产业与文旅融合蔚为大观。自贡灯会不仅是川人闹新春的传统，更以光与色的艺术语言讲述中国故事，是民俗文化中最富想象力的篇章之一。值得一提的是，自贡灯会善用瓷器、玻璃瓶、光导与机械构成大型灯组，将制盐的工匠传统巧妙转化为制灯技艺，故有“自贡归来不看灯”之美誉。它已走出国门，在数十个国家和地区举办巡展，成为中华文化“走出去”的代表之一。此外，自贡的彩灯制作已形成庞大的产业与技艺传承体系，匠人们将瓷器、玻璃瓶等材料化为流光溢彩的灯组，令人叹服。', 'https://baike.baidu.com/item/%E7%81%AF%E4%BC%9A%EF%BC%88%E8%87%AA%E8%B4%A1%E7%81%AF%E4%BC%9A%EF%BC%89/50880959', '中华彩灯大世界,自贡彩灯公园,自贡', NULL, 'https://www.bilibili.com/video/BV1x9w2egE6v/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,灯会,民俗,自贡'),
(39, '都江堰放水节', '民俗', '/images/culture/dujiangyanfangshuijie/dujiangyanfangshuijie_cover.jpg', '都江堰放水节每年清明举行，以古法砍栈揭堰、放水春灌，纪念李冰治水，是巴蜀最具特色的农耕民俗与水利文化节庆。', '都江堰放水节是每年清明时节在都江堰举行的传统民俗活动，源于古代“祀水”大典，至今延续近两千年，旨在纪念李冰父子修建都江堰、泽被后世的功绩，祈求风调雨顺、五谷丰登。旧时每逢清明，官民齐聚鱼嘴，待顺水而下的栈槎被砍开，江水咆哮涌入内江，万顷良田得以灌溉，“砍栈揭堰”的场面蔚为壮观，拉开了成都平原春耕序幕。放水节上，祭祀李冰、戏曲杂耍、舞蹈鼓乐等轮番上演，热闹非凡，兼具祭祀、农耕与民俗意义。都江堰放水节被称为“西部第一盛会”，2006年入选国家级非物质文化遗产名录。它不仅是人们对治水先贤的深情缅怀，也是中国农耕文明“重农敬水、顺势而为”的生动写照。如今，放水节已成为都江堰的重要文化旅游名片，让古老的祀水传统在当代焕发新的生机。值得一提的是，放水节的恢复举办让古老的祀水传统得以重现，祭祀仪式、民乐歌舞与仿古巡游轮番上演，吸引海内外游客共赴盛会。它不仅是农业文明的记忆，也成为都江堰水利文化与旅游融合的重要载体。此外，随着都江堰成为世界文化遗产，放水节也逐渐走向国际，让海内外游客在清明时节，共同感受这场古老而盛大的水文化庆典。自此，古堰的春灌大典与民俗庆典便年复一年地延续下来，成为川西平原上极富仪式感的年度盛事。', 'https://baike.baidu.com/item/%E9%83%BD%E6%B1%9F%E5%A0%B0%E6%94%BE%E6%B0%B4%E8%8A%82/10781269', '都江堰景区,二王庙,离堆公园', '李冰', 'https://www.bilibili.com/video/BV1GQXZBEECg/?spm_id_from=333.337.search-card.all.click', '非遗,民俗,农耕,都江堰'),
(40, '凉山火把节', '民俗', '/images/culture/liangshanhuobajie/liangshanhuobajie_cover.jpg', '火把节是彝族最盛大的传统节日，届时点燃火把、围绕篝火载歌载舞，斗牛赛马、选美对歌，是凉山彝族文化的集中体现。', '火把节是彝族、白族、纳西等民族共同的盛大传统节日，而在四川凉山彝族自治州最为隆重，通常于农历六月二十四前后举行，历时三天。火把节源于古代祭火、驱虫的习俗，节日期间人们身着盛装，点燃松明火把到田里巡游，以驱虫除害、祈求丰收；夜幕降临，人们围绕熊熊篝火，手拉着手跳起达体舞，歌声与欢笑此起彼伏。火把节也是彝族传统竞技与文化交流的舞台，拥有赛马、摔跤、斗牛、斗羊、选美、赛歌等丰富多彩的活动，尽显彝族人民热情豪迈、能歌善舞的民族性格。凉山火把节规模宏大、氛围浓烈，被称为“东方狂欢节”，已成为展示彝族文化、促进民族团结与旅游发展的重要窗口。火把节不仅是一场欢腾的民俗盛会，更承载着彝族人对火的崇敬、对生活的热爱与对丰收的祈愿，是巴蜀民族文化中最耀眼的火。值得一提的是，火把节的彝族民俗丰富多样，除了打火把、跳达体舞，还有祭火、拜火等仪式，火被视为驱邪祈福、带来光明的象征。它已成为凉山最具影响力的民族文化旅游品牌，让世界看见彝族热情似火的民族文化。此外，火把节也带动了凉山民族文化的对外传播，赛马、摔跤、选美与篝火晚会，让来自各地的人们沉浸式感受彝族文化的热情与活力。熊熊火光照亮的，是彝乡的今昔、热情与绵长的希望。', 'https://baike.baidu.com/item/%E7%81%AB%E6%8A%8A%E8%8A%82%EF%BC%88%E5%BD%9D%E6%97%8F%E7%81%AB%E6%8A%8A%E8%8A%82%EF%BC%89/49849756', '西昌,邛海,凉山彝族村寨', NULL, 'https://www.bilibili.com/video/BV1Sc4RzsEQj/?spm_id_from=333.337.search-card.all.click', '民俗,彝族,节日,凉山'),
(41, '羌年', '民俗', '/images/culture/qiangnian/qiangnian_cover.jpg', '羌年（羌历年）是羌族最隆重的传统节日，在农历十月初一举行，祭山祭祖、歌舞饮酒，是羌族文化信仰的集中展现。', '羌年又称“羌历年”，是羌族最隆重的传统节日，通常在农历十月初一前后举行，2008年列入国家级非物质文化遗产名录（后被列入联合国人类非遗名录）。羌年源于羌族的祭祀习俗，节日期间，羌族人家家户户扫除、贴红纸、喝咂酒、吃年饭，祭天神、祭山、祭祖，祈求来年风调雨顺、人畜兴旺。人们身着色彩绚丽的羌族服饰，敲起羊皮鼓、唱起多声部羌歌、跳起锅庄，云云鞋、挑花围腰与各种银饰光彩夺目。羌年也是羌族人团聚、走亲会友与传承文化的重要时刻，男子比试推杆、翻杠，女子歌舞赛美，气氛热烈。羌族生活在川西北高原河谷，历史悠久、文化独特，羌年与羌笛、羌绣、释比文化共同构成了丰富多彩的羌族文化。每逢羌年，茂县、汶川、理县等地的羌寨便沉浸在一片欢乐祥和之中。如今，羌年已成为展示羌族文化、促进民族团结的重要窗口，让这个居住在川西群山的古老民族的传统与骄傲被更多人看见。值得一提的是，羌年是羌族文化认同的重要纽带，节日里的祭山会、咂酒、锅庄与多声部民歌，浓缩了羌族的历史记忆与审美趣味。它被列入联合国人类非遗名录，也让这个古老民族的节日传统得到更广泛的保护与关注。此外，羌年的许多仪式与习俗由羌族“释比”主持，经词、祭仪与歌舞共同传达着羌人对天、地、祖先的敬奉，是羌族文化最集中的活态呈现。', 'https://baike.baidu.com/item/%E7%BE%8C%E5%B9%B4?fromModule=lemma_search-box', '中国古羌城,茂县坪头羌寨,汶川', NULL, 'https://www.bilibili.com/video/BV1vy4y187r8/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '非遗,羌族,节日,民俗'),
(42, '洛带客家文化', '民俗', '/images/culture/luodaikejiawenhua/luodaikejiawenhua_cover.jpg', '洛带古镇是西部最大的客家聚居地，保留着广东会馆等清代客家建筑，客家话、舞龙与傷心凉粉延续着数百年的移民文化。', '洛带古镇位于成都市龙泉驿区，是四川乃至中国西部最大的客家聚居地，被誉为“中国西部客家第一镇”。明末清初“湖广填四川”的移民潮中，大量客家人从广东、福建、江西迁入成都东山一带，洛带由此成为客家文化的重要聚居区。镇上保存着广东会馆、江西会馆、湖广会馆等清代客家会馆群，建筑宏阔、雕饰精美，记录着客家人的迁徙与奋斗历史。客家人至今仍保留着独特的语言、建筑、饮食与民俗：客家话在洛带仍可听闻，火龙节、水龙节等传统热闹非凡，客家美食如伤心凉粉、天鹅蛋、油烫鹅远近闻名。客家文化以“耕读传家、崇文重教”著称，也养成了客家人勤劳坚韧、团结互助的性格。洛带古镇通过会馆、客家博物馆与民俗活动，将这段跨越千里的移民记忆鲜活地保存下来，成为巴蜀移民文化与客家文化交融的生动写照。值得一提的是，洛带还设有四川客家博物馆与客家文化研究中心，系统梳理“湖广填四川”的移民脉络。客家舞龙、客家山歌与客家宴席等活动让古镇常年热闹，使洛带成为感受客家文化、体验移民历史的西部首选之地。此外，洛带的客家宴席与客家土楼式建筑也极具特色，会馆、祠堂与老街共同构成了一个立体的客家文化空间，吸引着各地游客前来寻访。客家文脉，便在这青砖老街间绵延不绝、生生不息。', 'https://baike.baidu.com/item/%E6%B4%9B%E5%B8%A6%E9%95%87/7064231', '洛带古镇,广东会馆,江西会馆', NULL, 'https://www.bilibili.com/video/BV12DzcByEaW/?spm_id_from=333.337.search-card.all.click', '客家文化,移民,古镇,成都'),
(43, '川西农耕文化', '民俗', '/images/culture/chuanxinonggengwenhua/chuanxinonggengwenhua_cover.jpg', '川西农耕依托都江堰灌溉与川西林盘，形成精耕细作的稻作传统，林盘、院坝、林盘、水田构成人与自然和谐共生的田园画卷。', '川西农耕文化是依托成都平原自然条件与都江堰灌溉系统发展起来的农业文明，是巴蜀文化赖以生存的根基。成都平原水沛土肥、气候温和，都江堰的无坝引水又使之“水旱从人”，因此自秦汉以来便是全国重要的粮食产区。川西的农耕形态以稻作为主，兼有麦、油菜与蔬果，形成了春耕、夏耘、秋收、冬藏的农业生产节律，也衍生出丰收节、扶农神、祭水神等民俗。川西林盘是这一文化的典型景观：竹林、树木与院落构成一个个林盘，散落在沃野之上，房前屋后种菜栽竹、人家炊烟，人与自然、田与居相融共生。川西人性格乐天知足、喜客尚聚，与这片肥沃而安定的土地息息相关，“天府之国”的宜居，正是一切农耕文明的基础。如今，川西林盘与田园被作为文化遗产加以保护，战旗村、农科村等展示了新时代的乡村风貌，让“田、林、水、院”的农耕美学得以延续，成为巴蜀乡土文化最温柔动人的一章。值得一提的是，川西林盘已被视为具有重要价值的乡土景观与文化景观，竹林、菜园、院坝与林盘人家构成人和自然和谐相处的典范。今天，保护林盘、发展乡村文创与农旅融合，正让这份天府农耕的田园诗意得以延续。此外，川西的院子、林盘与田畴也是众多诗人与画家笔下的主题，其“田、林、水、院”相融的格局，成为天府田园诗意最动人的写照。', 'https://baike.baidu.com/item/%E5%B7%9D%E8%A5%BF%E6%9E%97%E7%9B%98/3418364', '战旗村,农科村,川西林盘', NULL, 'https://www.bilibili.com/video/BV15t4y1r7RJ/?spm_id_from=333.337.search-card.all.click', '农耕,林盘,乡村,成都平原'),
(44, '成都花会', '民俗', '/images/culture/chengduhuahui/chengduhuahui_cover.jpg', '成都花会（青羊宫花会）源于唐宋，每年春季赏花、看戏、品美食，是成都历史悠久的传统民俗盛会。', '成都花会是每年春季在成都青羊宫一带举行的传统民俗盛会，源于唐宋年间，至今已有千余年历史。花会最初与青羊宫的道教庙会相连，后来逐渐演变为集赏花、观戏、品美食、购什物于一体的综合性民俗盛会，是成都市井文化的一张名片。旧时每逢花会，青羊宫周边花市盛开、游人如织，海棠、兰花、梅花等应时绽放，各色小吃、杂耍与川剧表演汇聚一堂，尽显“花重锦官城”的风貌，故有“成都花会”之称。与花会相伴的还有每年正月举行的“成都灯会”，赏灯与赏花两个传统相映成趣，共同构成成都人春秋两季的游乐盛事。如今，成都传承这一传统，在文化公园等地继续举办花会、花展与灯会，近郊的桃花会、郁金香节、牡丹花会等也相继兴起。花会不仅体现了成都人热爱花木、喜好游乐、崇尚雅致的生活态度，也是巴蜀民俗中最富有生活美学的一面。值得一提的是，花会不仅是赏花，更是一场民生经济与民间艺术的大聚会：花农摆摊、艺人献技，堪称老成都的“嘉年华”。它体现了成都人爱花、尚美、讲情趣的生活品格，与成都现今的公园城市气质一脉相承。此外，与花会相伴的还有成都人爱花、养花、惜花的生活方式，从青石桥的花市到街头的花摊，花朵早已融入成都城市的日常与气质。一城春色、满市花香，尽在每年如期而至的花会之中。', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E8%8A%B1%E4%BC%9A?fromModule=lemma_search-box', '青羊宫,文化公园,百花潭', NULL, 'https://www.bilibili.com/video/BV1jP411n7Ne/?spm_id_from=333.337.search-card.all.click&vd_source=61dc0aa4383b9b5ee8742ed7eec6fc83', '民俗,花会,市井,成都'),
(45, '蜀风雅韵', '民俗', '/images/culture/shufengyayun/shufengyayun_cover.jpg', '“蜀风雅韵”是成都集川剧、变脸、吐火、手影、滚灯与茶艺于一体的传统艺术演出品牌，是感受巴蜀民俗的经典舞台。', '“蜀风雅韵”是成都著名的传统民俗艺术演出品牌，坐落于成都文化公园内，以集中展示川剧与巴蜀民艺著称，是许多人初识川剧的窗口。演出内容涵盖川剧经典折子戏、变脸、吐火、手影戏、滚灯、木偶戏、杖头木偶、茶艺表演与民乐演奏等，一台演出将川剧的唱、念、做、打与民间绝技浓缩呈现，精彩纷呈。“蜀风雅韵”既延续了旧时川剧“坐唱馆子”与戏园的观演传统，又面向当代游客进行舞台编排与体验升级，观众可边品盖碗茶、品尝小吃，边欣赏原汁原味的川剧艺术。其中变脸、吐火、手影与滚灯等节目尤为受欢，一颦一笑、一吐一逗都迸发着川人的幽默与智慧。作为成都最具代表性的川剧演出场景之一，“蜀风雅韵”与锦江剧场、四川省川剧院等共同构成成都戏曲文化的活力版图，让川剧与巴蜀民艺在当代舞台上持续生辉，成为游客体验“最成都”的文化一站。值得一提的是，“蜀风雅韵”对外地游客而言，是最快触摸川剧精粹的舞台；对本地人而言，则延续着在剧场里品茶看戏的旧时情调。它以一台演出浓缩巴蜀民艺，让川剧的绝技与韵味走进更多人心里，成为“最成都”的文化体验之一。此外，“蜀风雅韵”还常作为文化交流的窗口，接待来蓉的各国宾朋，让川剧的绝技与巴蜀的民艺，在一台演出中走近世界观众。', 'https://baike.baidu.com/item/%E8%9C%80%E9%A3%8E%E9%9B%85%E9%9F%B5?fromModule=lemma_search-box', '蜀风雅韵,文化公园,琴台路', NULL, 'https://www.bilibili.com/video/BV1gN411A7Kv/?spm_id_from=333.337.search-card.all.click', '川剧,民俗,演出,成都'),
(46, '蜀山文化（贡嘎山）', '自然', '/images/culture/shushanwenhuagonggashan/shushanwenhuagonggashan_cover.jpg', '贡嘎山是四川第一高峰，被誉为“蜀山之王”，藏语意为“白色冰山”，围绕它形成了丰富的登山、朝圣与摄影文化。', '贡嘎山位于甘孜州泸定、康定、九龙交界处，主峰海拔7556米，是四川第一高峰，被誉为“蜀山之王”。藏语称其为“木雅贡嘎”，意为“白色的冰山”，在藏传佛教中它是神圣的修行之地，历代高僧在此修行，山神传说与朝圣传统流传至今。贡嘎山是世界上攀登难度极高、死亡率较高的山峰之一，吸引了全球登山者；而对普通人而言，它更多以“蜀山之王”的身份存在于观景、摄影与信仰之中，牛背山、海螺沟、王岗坪、子梅坪等都是眺望贡嘎的经典地点，日照金山、云海佛光令人震撼。蜀山不仅是自然的高度，更承载着巴蜀人对雪山的崇敬与向往：从李白的“蜀道难”到今日的川西高原环线，雪山始终是蜀地文化意象中神圣而壮美的一极。围绕蜀山形成了登山探险、雪山观景、藏地朝圣与高原摄影等内容丰富的文化，是四川自然文化中最具性灵与神性的一章。值得一提的是，贡嘠山的“日照金山”是无数摄影者梦寐以求的景象，晨曦初照时，雪峰由粉转金、光华夺目，震撼人心。围绕雪山还流传着诸多山神传说与藏族信仰，是巴蜀自然与精神世界中极为崇高而神圣的一极。此外，贡嘎山周围还点缀着海螺沟冰川、红石滩与众多高山湖泊，雪山与冰川相映，构成川西高原上最为壮丽而神圣的自然画卷。蜀山巍巍，气脉浩然，令人心生敬畏。', 'https://baike.baidu.com/item/%E8%B4%A1%E5%98%8E%E5%B1%B1/507005?fromModule=search-result_lemma', '海螺沟,牛背山,王岗坪,子梅坪', NULL, 'https://www.bilibili.com/video/BV1a4411E76N/?spm_id_from=333.337.search-card.all.click', '雪山,蜀山之王,自然,甘孜'),
(47, '九寨沟水景文化', '自然', '/images/culture/jiuzhaigoushuijingwenhua/jiuzhaigoushuijingwenhua_cover.jpg', '九寨沟以翠海、叠瀑、彩林、雪峰、蓝冰、藏情“六绝”闻名，被誉为“童话世界、人间仙境”，是水景美学的极致。', '九寨沟位于阿坝州九寨沟县，是世界自然遗产与国家级自然保护区，以翠海、叠瀑、彩林、雪峰、蓝冰、藏情“六绝”闻名于世，素有“童话世界”“人间仙境”“九寨归来不看水”之美誉。景区由树正、日则、则查洼三条主沟组成，百余处高山湖泊（当地称“海子”）与瀑布、滩流次第分布，湖水因钙化沉积与光影变化而呈现出蓝、绿、青、金等缤纷水色，五花海、诺日朗瀑布、珍珠滩、长海等景点四季皆美。九寨沟的美是水的美：这里有世界上最丰富的彩色湖泊与钙华滩流，堪称“水景之王”，历代文人画家为之倾倒。同时，公园内还散布着数个藏族村落，藏式碉楼、经幡、寨子与彩林、雪山、湖泊相映，藏情文化让自然之美多了人文温度。2017年九寨沟经历地震后重建开放，更让人看到生态保护与文化传承的坚持。九寨沟不仅是四川自然审美的巅峰，也是人与自然和谐共生、生态旅游与文化保护相统一的典范。值得一提的是，九寨沟的水色随季节、天气与光线变幻万千，春看新绿、夏观叠瀑、秋赏彩林、冬览蓝冰，四季各有惊艳。它不仅是四川自然审美的巅峰，也是中国生态旅游的一张世界级名片，让“九寨归来不看水”成为共识。此外，九寨沟的藏情文化同样令人难忘，藏寨、经幡、转经与藏族同胞的笑脸，为这片水景平添了温暖的人情味，让自然之美更具温度。', 'https://baike.baidu.com/item/%E4%B9%9D%E5%AF%A8%E6%B2%9F%E5%9B%BD%E5%AE%B6%E7%BA%A7%E8%87%AA%E7%84%B6%E4%BF%9D%E6%8A%A4%E5%8C%BA/8762684', '五花海,诺日朗瀑布,长海,珍珠滩', NULL, 'https://www.bilibili.com/video/BV1MCUVB3EVF/?spm_id_from=333.337.search-card.all.click', '世界遗产,水景,自然,阿坝'),
(48, '若尔盖湿地文化', '自然', '/images/culture/ruoergaishidiwenhua/ruoergaishidiwenhua_cover.jpg', '若尔盖草原是我国三大湿地草原之一，黄河九曲第一弯与花湖构成壮阔湿地，也是红军长征过草地的历史现场。', '若尔盖草原位于阿坝州若尔盖县，地处青藏高原东缘，是我国三大湿地草原之一，也是黄河上游重要的水源涵养地与生态屏障，素有“川西北高原的绿洲”之称。这里草原辽阔、水草丰美，黄河在境内形成壮美的“九曲第一弯”，花湖则是高原沼泽湿地与候鸟天堂，黑颈鹤、天鹅等珍稀鸟类在此栖息，生态价值极为突出。若尔盖不仅是自然美的代表，更是一片红色热土：1935年红军长征穿越茫茫水草地，若尔盖成为长征“过草地”的历史现场，“金色的鱼钩”“七根火柴”等故事传颂后世，长征精神与高原风光在此交相辉映。此外，这里是藏、羌等民族的生活之地，牧场、帐篷、酥油茶、赛马会与转山会构成浓郁的草原民族文化。若尔盖湿地不仅是生态的“地球之肾”，也是红色文化与民族文化的双重载体，是四川自然与人文交织的壮阔一章。值得一提的是，若尔盖湿地不仅是黄河上游重要的水源涵养地和生物多样性宝库，更以其辽阔壮美的草原风光成为自驾川西北的必经之地。它把生态价值、红色记忆与藏族风情熔于一炉，是四川自然与人文不可分割的一部分。此外，若尔盖的候鸟生态与牧民文化也极具魅力，夏日的草原上，黑颈鹤翔集、牛羊如云，是观察高原生态与传统游牧生活的绝佳之地。湿地如肾、草原如歌，滋养着这片高原的生生不息。', 'https://baike.baidu.com/item/%E8%8B%A5%E5%B0%94%E7%9B%96%E5%9B%BD%E5%AE%B6%E5%85%AC%E5%9B%AD/61173335?fromModule=search-result_lemma', '花湖,黄河九曲第一湾,若尔盖,红原', NULL, 'https://www.bilibili.com/video/BV1FP411a7nb/?spm_id_from=333.337.search-card.all.click', '湿地,草原,红色,自然'),
(49, '蜀南竹海', '自然', '/images/culture/shunanzhuhai/shunanzhuhai_cover.jpg', '蜀南竹海是中国最大的竹林景区，七万余亩翠竹连缀成海，竹景、丹霞与竹文化彼此交融，是竹乡文化的典型代表。', '蜀南竹海位于宜宾市长宁县与江安县交界处，是中国最大的原始绿竹景区，七个峰峦的翠竹连缀成海，享有“中国最美十大森林”之誉，是四川竹文化的典型代表。竹海以浩瀚竹景、丹霞地貌与飞瀑流泉著称，楠竹连山遍野、四季翠绿，清风过处竹涛阵阵，登高远眺，绿海接天、云蒸霞蔚。景区内有翡翠长廊、七彩飞瀑、仙女湖、仙寓洞等众多景观，兼具自然之美与秘境之幽。竹海不仅有美景，更孕育了丰富的竹文化：竹子可用于建筑、器具、造纸、竹编、饮食与艺术，宜宾的竹雕、竹编、竹工艺与全竹宴远近闻名，“宁可食无肉，不可居无竹”的文人竹情在此得到生动印证。竹文化与中国传统文人精神密切相关，象征虚心、有节、清高。如今，蜀南竹海将生态观光、竹文化体验与康养度假融为一体，游人可赏竹、食笋、住竹屋、购竹艺，感受“竹与竹文化”的东方美学，是巴蜀自然文化中清雅而重要的一章。值得一提的是，竹海所在的宜宾长宁、江安一带自古竹业兴盛，竹编、竹雕、竹工艺与全竹宴远近闻名，竹子深深植入当地人的生产与生活。竹海以竹为魂，把自然生态、竹文化与康养旅游融为一体，是川南一道清雅而怡人的风景。此外，竹海四季景观各异，春可观笋、夏可避暑、秋可赏叶、冬可观雪，尤其是雨雾中的竹海烟岚弥漫，宛如一幅流动的水墨长卷。', 'https://baike.baidu.com/item/%E8%9C%80%E5%8D%97%E7%AB%B9%E6%B5%B7%E6%97%85%E6%B8%B8%E5%BA%A6%E5%81%87%E5%8C%BA?fromtitle=%E8%9C%80%E5%8D%97%E7%AB%B9%E6%B5%B7&fromid=247652&fromModule=lemma_search-box', '宜宾蜀南竹海,翡翠长廊,仙寓洞', NULL, 'https://www.bilibili.com/video/BV18V411x7Dx/?spm_id_from=333.337.search-card.all.click', '竹海,自然,竹文化,宜宾'),
(50, '高原彩林文化', '自然', '/images/culture/gaoyuancailinwenhua/gaoyuancailinwenhua_cover.jpg', '川西高原秋日彩林绚烂如画，黑水奶子沟、米亚罗等地红叶层林尽染，是高原独有的自然景观与摄影盛地。', '高原彩林是四川西部高原秋季最壮丽的自然景观，每到十月至十一月，高原上的桦树、槭树与红桦等树种变得金黄、火红、赭褐，与雪山、藏寨、湖泊、溪流相映，构成如诗如画的秋日画卷。黑水奶子沟彩林被誉为“亚洲面积最大、色彩最丰富”的红叶彩林区，绵延数十公里，素有“八十里画廊”之美誉；理县米亚罗、平武王朗、九寨沟、四姑娘山与毕棚沟等地也是观赏彩林的胜地。高原彩林之美，在于色彩与光影的不断变幻，在于雪山、藏寨与红叶的冷暖交融，因此深受摄影爱好者与旅行者的追捧。围绕彩林形成了丰富的高原赏秋文化：自驾川西、拍摄红叶、住藏寨、品酥油茶，人们在雪山与彩林间感受高原之秋的壮美与宁静。高原彩林不仅是自然生态的奇观，也是川西高原季节文化的鲜明符号，是四川自然文化中最绮丽动人、最富诗意的篇章之一。值得一提的是，高原彩林之美与藏羌村落、雪山圣湖彼此映衬，构成川西秋季最迷人的风光长廊，吸引着全国各地的自驾客与摄影爱好者。围绕赏秋而形成的“川西秋色”已成为四川最具季节特色的旅游文化符号之一。此外，高原彩林的观赏往往与藏寨、雪山、草原串联成线，形成“川西环线”秋日自驾之旅，成为无数人心目中一生必去的风景。待到秋风起时，彩林如画，静候八方来客。', 'https://baike.baidu.com/item/%E5%BD%A9%E6%9E%97/8024040', '奶子沟,米亚罗,毕棚沟,四姑娘山', NULL, 'https://www.bilibili.com/video/BV1uu4y1v7qP/?spm_id_from=333.337.search-card.all.click', '彩林,红叶,自然,摄影')
