INSERT INTO `heritage` (`id`, `name`, `website`, `category`, `level`, `inheritor`, `summary`, `video_url`) VALUES
(1, '蜀锦织造技艺', 'https://baike.baidu.com/item/%E8%9C%80%E9%94%A6%E7%BB%87%E9%80%A0%E6%8A%80%E8%89%BA/8087818', '传统技艺', '国家级', NULL, '蜀锦是中国四大名锦之一，成都所产，以花楼织机手工织造，讲究逐花异色、纹样华美。2006年列入首批国家级非物质文化遗产名录，是南方丝绸之路上光彩夺目的巴蜀名片。', 'https://www.bilibili.com/video/BV1Tr4y177hV/'),
(2, '成都漆艺', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E6%BC%86%E8%89%BA/7823772', '传统技艺', '国家级', '宋西平', '成都漆艺以天然生漆髹涂器物，雕填、堆光、银片平脱等技法精妙，色彩瑰丽、经久耐用。2006年列入首批国家级非遗名录，与蜀锦、蜀绣并称巴蜀工艺的杰出代表。', 'https://www.bilibili.com/video/BV1bf4y1Z7kU/'),
(3, '自贡扎染技艺', 'https://baike.baidu.com/item/%E8%87%AA%E8%B4%A1%E6%89%8E%E6%9F%93/1972556', '传统技艺', '国家级', '张晓平', '自贡扎染又称蜀缬，以针扎、缬扎后浸染，色晕自然、变化万千，蓝白相间、古朴素雅。2008年列入国家级非遗名录，是川南历史悠久的传统手工染缬技艺。', 'https://www.bilibili.com/video/BV1JW4y1L7tc/'),
(4, '泸州分水油纸伞制作技艺', 'https://baike.baidu.com/item/%E4%BC%9E%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%88%E6%B2%B9%E7%BA%B8%E4%BC%9E%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%89/53230608', '传统技艺', '国家级', '毕六福', '泸州分水油纸伞以楠竹为骨、皮纸为面、桐油为衣，经近百道工序手工制成，古朴典雅、经久耐用，被誉为“中国民间伞艺的活化石”，2008年列入国家级非遗名录。', 'https://www.bilibili.com/video/BV1R1421m7DJ/'),
(5, '青神竹编', 'https://baike.baidu.com/item/%E7%AB%B9%E7%BC%96%EF%BC%88%E9%9D%92%E7%A5%9E%E7%AB%B9%E7%BC%96%EF%BC%89/53488925', '传统技艺', '国家级', '陈云华', '青神竹编产于眉山青神，以“薄如蝉翼、细如发丝”的竹丝编出书画与器物，技艺绝伦，2008年列入国家级非遗名录，青神亦被誉为“中国竹编艺术之乡”。', 'https://www.bilibili.com/video/BV1cJ4m1V76Z/'),
(6, '道明竹编', 'https://baike.baidu.com/item/%E9%81%93%E6%98%8E%E7%AB%B9%E7%BC%96/6569341', '传统技艺', '国家级', '赵思进', '道明竹编产于崇州道明镇，以平面竹编与瓷胎竹编闻名，温润古朴、富有创意。2014年列入国家级非遗名录，依托川西林盘发展出“非遗+文创+旅游”的新模式。', 'https://www.bilibili.com/video/BV1AX4y1n77w/'),
(7, '成都银花丝制作技艺', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E9%93%B6%E8%8A%B1%E4%B8%9D%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/24193987', '传统技艺', '国家级', '道安,倪成玉', '成都银花丝以白银抽丝、手工平填与焊接而成，纤细如发、玲珑剔透，被誉为“中国一绝”。2008年列入国家级非遗名录，是成都独特的金银细工技艺。', 'https://www.bilibili.com/video/BV1ta411n7EJ/'),
(8, '郫县豆瓣传统制作技艺', 'https://baike.baidu.com/item/%E8%B1%86%E7%93%A3%E4%BC%A0%E7%BB%9F%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/18713176', '传统技艺', '国家级', NULL, '郫县豆瓣产于成都郫都区，以蚕豆、辣椒经“翻、晒、露”长期发酵而成，色泽红亮、酱香浓郁，被誉为“川菜之魂”。其传统制作技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1VtnRzLEAc/'),
(9, '保宁醋传统酿造技艺', 'https://baike.baidu.com/item/%E9%85%BF%E9%86%8B%E6%8A%80%E8%89%BA%EF%BC%88%E4%BF%9D%E5%AE%81%E9%86%8B%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E5%B7%A5%E8%89%BA%EF%BC%89/57219108', '传统技艺', '国家级', NULL, '保宁醋产自阆中，是中国四大名醋之一，以麸皮、大米与数十味中药制曲酿造，色褐香浓、酸味绵长。其传统酿制技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1uf421272R/'),
(10, '五粮液酒传统酿造技艺', 'https://baike.baidu.com/item/%E8%92%B8%E9%A6%8F%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA%EF%BC%88%E4%BA%94%E7%B2%AE%E6%B6%B2%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA%EF%BC%89/53943330', '传统技艺', '国家级', NULL, '五粮液产于宜宾，以五种粮食为原料，经包包曲、老窖发酵与勾调而成，是浓香型白酒的代表。其传统酿造技艺列入国家级非物质文化遗产名录，是川酒文化的骄傲。', 'https://www.bilibili.com/video/BV15r421E7kk/'),
(11, '泸州老窖酒酿制技艺', 'https://baike.baidu.com/item/%E6%B3%B8%E5%B7%9E%E8%80%81%E7%AA%96%E9%85%92%E9%85%BF%E5%88%B6%E6%8A%80%E8%89%BA/8088208', '传统技艺', '国家级', NULL, '泸州老窖以1573国宝窖池群与独特酿造技艺著称，是中国浓香型白酒的鼻祖之一。其酿制技艺列入首批国家级非遗名录，窖池群连续使用数百年而从未间断。', 'https://www.bilibili.com/video/BV1PxQKBHEAT/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(12, '剑南春酒传统酿造技艺', 'https://baike.baidu.com/item/%E8%92%B8%E9%A6%8F%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA%EF%BC%88%E5%89%91%E5%8D%97%E6%98%A5%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA%EF%BC%89/53946101', '传统技艺', '国家级', NULL, '剑南春出自绵竹，以“天益老号”古窖池群与浓香工艺酿造，历史悠久、风味绵柔。其传统酿造技艺列入国家级非物质文化遗产名录，是川酒名品之一。', 'https://www.bilibili.com/video/BV1hA4y1o7tz/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(13, '水井坊酒传统酿造技艺', 'https://baike.baidu.com/item/%E6%B0%B4%E4%BA%95%E5%9D%8A%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA/2545164', '传统技艺', '国家级', NULL, '水井坊酒传统酿造技艺传承于成都，以古法发酵、蒸馏与勾调而成，其水井坊遗址被誉为中国白酒的“活化石”。其酿造技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1LfqZBUEPL/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(14, '郎酒传统酿造技艺', 'https://baike.baidu.com/item/%E8%92%B8%E9%A6%8F%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA%EF%BC%88%E5%8F%A4%E8%94%BA%E9%83%8E%E9%85%92%E4%BC%A0%E7%BB%9F%E9%85%BF%E9%80%A0%E6%8A%80%E8%89%BA%EF%BC%89/53954158', '传统技艺', '国家级', NULL, '郎酒产于古蔺县二郎镇，依托赤水河畔独特的自然条件，采用“四高三长”工艺酿造，属酱香型代表。其传统酿造技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV122P9zsEA2/'),
(15, '自贡井盐汲制技艺', 'https://baike.baidu.com/item/%E8%87%AA%E8%B4%A1%E4%BA%95%E7%9B%90%E6%B7%B1%E9%92%BB%E6%B1%B2%E5%88%B6%E6%8A%80%E8%89%BA/7077146', '传统技艺', '国家级', NULL, '自贡井盐汲制技艺以冲击式顿钻凿井、汲卤、输卤与煎盐为特色，打出了世界第一口超千米深井。该技艺列入国家级非遗名录，见证了“千年盐都”的辉煌历史。', 'https://www.bilibili.com/video/BV1gQ4y1z7z8/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(16, '荥经砂器烧制技艺', 'https://baike.baidu.com/item/%E9%99%B6%E5%99%A8%E7%83%A7%E5%88%B6%E6%8A%80%E8%89%BA%EF%BC%88%E8%8D%A5%E7%BB%8F%E7%A0%82%E5%99%A8%E7%83%A7%E5%88%B6%E6%8A%80%E8%89%BA%EF%BC%89/49729151', '传统技艺', '国家级', NULL, '荥经砂器产于雅安荥经，以当地黏土手工制坯、龙窑烧制而成，成品黑亮厚重、透气耐用，尤以砂锅著称。其烧制技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV18P4y1L7Fw/'),
(17, '夹江竹纸制作技艺', 'https://baike.baidu.com/item/%E5%A4%B9%E6%B1%9F%E9%80%A0%E7%BA%B8/62511723', '传统技艺', '国家级', NULL, '夹江竹纸制作技艺流传于乐山夹江，以嫩竹为料，经石灰浸沤、蒸煮、舂捣、抄纸等七十二道工序而成，纸质细腻、宜书宜画。该技艺列入国家级非遗名录。', 'https://www.bilibili.com/video/BV1wuiyBQEZy/'),
(18, '自贡龚扇制作技艺', 'https://baike.baidu.com/item/%E9%BE%9A%E6%89%87/2692105', '传统技艺', '国家级', '龚倩', '自贡龚扇以细如发丝的竹丝手工编织成扇，扇面可编出山水、花鸟与文字，薄透如绢、精美绝伦，被誉为“天下第一扇”。其制作技艺列入国家级非遗名录。', 'https://www.bilibili.com/video/BV1NgjezaEdn/'),
(19, '江安竹簧工艺', 'https://baike.baidu.com/item/%E7%AB%B9%E5%88%BB%EF%BC%88%E6%B1%9F%E5%AE%89%E7%AB%B9%E7%B0%A7%EF%BC%89/53520197', '传统技艺', '国家级', NULL, '江安竹簧工艺产于宜宾江安，以楠竹内壁竹簧雕刻镶嵌，工艺细腻、古朴雅致，常见于文具、摆件与器物。其技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV14v4y1m7L4/'),
(20, '渠县刘氏竹编', 'https://baike.baidu.com/item/%E7%AB%B9%E7%BC%96%EF%BC%88%E6%B8%A0%E5%8E%BF%E5%88%98%E6%B0%8F%E7%AB%B9%E7%BC%96%EF%BC%89/53488431', '传统技艺', '国家级', '刘嘉峰', '渠县刘氏竹编以精细竹丝编织书画与器物见长，讲究“细、光、紧、匀”，作品雅致生动。其竹编技艺列入国家级非物质文化遗产名录，是川东竹艺的代表。', 'https://www.bilibili.com/video/BV1UG4y1p7Ft/'),
(21, '荣县土陶制作技艺', 'https://baike.baidu.com/item/%E8%8D%A3%E5%8E%BF%E5%9C%9F%E9%99%B6%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/65420178', '传统技艺', '省级', NULL, '荣县土陶技艺历史可追溯到唐宋，以页岩制坯、柴窑烧造，产品以泡菜坛、土陶茶壶与砂锅著称，质朴粗犷、透气耐用，是川南民间陶瓷的代表。', 'https://www.bilibili.com/video/BV1qN411n7Th/'),
(22, '富顺豆花制作技艺', 'https://baike.baidu.com/item/%E5%AF%8C%E9%A1%BA%E8%B1%86%E8%8A%B1%E5%88%B6%E4%BD%9C%E5%B7%A5%E8%89%BA/55593668', '传统技艺', '省级', NULL, '富顺豆花以嫩豆腐脑配香辣蘸水，绵软细嫩、蘸水鲜香，是自贡富顺的招牌名食。其制作技艺（含戴氏豆花蘸水工艺）入选省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Ky4y1b7Cd/'),
(23, '陈麻婆豆腐制作技艺', 'https://baike.baidu.com/item/%E9%99%88%E9%BA%BB%E5%A9%86%E8%B1%86%E8%85%90%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/65603194', '传统技艺', '省级', NULL, '陈麻婆豆腐创制于清同治年间，以豆腐、牛肉臊与郫县豆瓣、花椒烧制，麻辣鲜香、烫嫩酥鲜，是川菜经典。其制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1z3G2zyErr/'),
(24, '川菜传统烹饪技艺', 'https://baike.baidu.com/item/%E5%B7%9D%E8%8F%9C%E7%83%B9%E9%A5%AA%E6%8A%80%E8%89%BA/57218491', '传统技艺', '省级', NULL, '川菜传统烹饪技艺以“一菜一格、百菜百味”著称，善于运用郫县豆瓣、花椒与复合调味，味型多达二三十种。其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1os41167LD/'),
(25, '夫妻肺片制作技艺', 'https://baike.baidu.com/item/%E5%A4%AB%E5%A6%BB%E8%82%BA%E7%89%87%E4%BC%A0%E7%BB%9F%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/60150299', '传统技艺', '省级', NULL, '夫妻肺片以牛头皮、牛心、牛舌、牛肚卤制切片，浇红油、花椒与花生末凉拌，麻辣鲜香、软糯爽口，由成都郭朝华夫妇创制，是川味凉菜的经典。', 'https://www.bilibili.com/video/BV15x41157S9/'),
(26, '樟茶鸭制作技艺', 'https://baike.baidu.com/item/%E6%A8%9F%E8%8C%B6%E9%B8%AD/2987287', '传统技艺', '省级', NULL, '樟茶鸭以肥鸭用樟树叶、花茶熏制后再蒸再炸，皮酥肉嫩、烟香浓郁，色泽枣红、咸鲜醇厚，是川菜宴席上极具特色的传统名菜，其技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV1Qb411a72g/'),
(27, '四川小吃制作技艺', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E5%B0%8F%E5%90%83%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/60150657', '传统技艺', '省级', NULL, '四川小吃制作技艺涵盖龙抄手、钟水饺、赖汤圆、韩包子等众多名小吃，讲究制皮、调味与火候，风味多样、老少皆宜，是巴蜀市井饮食文化的鲜活载体。', 'https://www.bilibili.com/video/BV1f94y1Z7fG/'),
(28, '四川泡菜制作技艺', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E6%B3%A1%E8%8F%9C%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%88%E5%9C%9F%E9%97%A8%E6%B3%A1%E8%8F%9C%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%89/62180450', '传统技艺', '省级', NULL, '四川泡菜以蔬菜入陶坛、加盐与香料经乳酸发酵而成，酸辣鲜香、爽脆开胃，讲究“老酸水”的养护。其制作技艺列入省级非物质文化遗产名录，是川味的重要组成。', 'https://www.bilibili.com/video/BV1jbbM64EdU/'),
(29, '达州灯影牛肉制作技艺', 'https://baike.baidu.com/item/%E8%BE%BE%E5%B7%9E%E7%81%AF%E5%BD%B1%E7%89%9B%E8%82%89/5430781', '传统技艺', '省级', NULL, '达州灯影牛肉以牛肉切薄如纸、经卤、烘、炸等多道工序制成，片薄酥脆、麻辣回甜、入口化渣，因薄可透光似皮影而得名，是川东著名的地方特产。', 'https://www.bilibili.com/video/BV1dHdFBYE4Q/'),
(30, '自贡火边子牛肉制作技艺', 'https://baike.baidu.com/item/%E7%81%AB%E8%BE%B9%E5%AD%90%E7%89%9B%E8%82%89%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/62920950', '传统技艺', '国家级', NULL, '自贡火边子牛肉以牛后腿肉片成极薄大片，经烤烘而成，片薄如纸、麻辣鲜香、久存不坏，因旧时在灶火边烘烤而得名。其制作技艺列入国家级非遗名录。', 'https://www.bilibili.com/video/BV1Ss411E7H4/'),
(31, '张飞牛肉传统制作技艺', 'https://baike.baidu.com/item/%E5%BC%A0%E9%A3%9E%E7%89%9B%E8%82%89/965524', '传统技艺', '省级', NULL, '张飞牛肉是阆中特产，色黑皮红、外黑内红形似张飞脸谱，肉干而不燥、酥香化渣。其传统制作技艺列入省级非物质文化遗产名录，是川北著名特产。', 'https://www.bilibili.com/video/BV19m4y1D7kZ/'),
(32, '潼川豆豉制作技艺', 'https://baike.baidu.com/item/%E6%BD%BC%E5%B7%9D%E8%B1%86%E8%B1%89%E9%85%BF%E5%88%B6%E6%8A%80%E8%89%BA/24193994', '传统技艺', '省级', NULL, '潼川豆豉产于绵阳三台，以大黑豆经浸泡、蒸煮、制曲、发酵而成，色黑油润、豉香浓郁，是川菜中重要的传统调味品，其制作技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV1uubUzkEF2/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(33, '中江挂面制作技艺', 'https://baike.baidu.com/item/%E4%B8%AD%E6%B1%9F%E6%8C%82%E9%9D%A2/4465982', '传统技艺', '国家级', NULL, '中江挂面以小麦面粉经发酵、拉条、上竹、晾晒而成，面条细如银丝、中空透气、久煮不烂，入口绵软。其制作技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1TM4y1R7Pu/'),
(34, '绵阳米粉制作技艺', 'https://baike.baidu.com/item/%E7%BB%B5%E9%98%B3%E7%B1%B3%E7%B2%89/3144672', '传统技艺', '省级', NULL, '绵阳米粉以细米粉配牛肉、肥肠或鸡汤臊子，汤色红亮、臊子酥香、米粉滑爽，是绵阳人早餐的首选。其制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1yUdwBXEgE/'),
(35, '宜宾燃面传统制作技艺', 'https://baike.baidu.com/item/%E5%AE%9C%E5%AE%BE%E7%87%83%E9%9D%A2%E4%BC%A0%E7%BB%9F%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/61866021', '传统技艺', '省级', NULL, '宜宾燃面以水面条拌油辣子、芽菜、花生碎与香油，油重无水、点火即燃，故而得名，麻辣鲜香、干爽酥香。其传统制作技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV1wF411z7JA/'),
(36, '川味火锅底料传统制作技艺', 'https://baike.baidu.com/item/%E7%81%AB%E9%94%85%E5%BA%95%E6%96%99/3255542', '传统技艺', '省级', NULL, '川味火锅底料以牛油、二荆条辣椒与汉源花椒等慢火熬制，红亮醇厚、麻辣鲜香，是川渝火锅的灵魂。其传统制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1eU4y1M72o/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(37, '广汉缠丝兔制作技艺', 'https://baike.baidu.com/item/%E5%B9%BF%E6%B1%89%E7%BC%A0%E4%B8%9D%E5%85%94%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/62179529', '传统技艺', '省级', NULL, '广汉缠丝兔以兔肉腌制后用麻绳缠绕风干制成，色泽红亮、肉质紧实、麻香适口，是德阳广汉的传统名食，其制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1f94y1Z7at/'),
(38, '崇州怀远藤编', 'https://baike.baidu.com/item/%E8%97%A4%E7%BC%96%EF%BC%88%E6%80%80%E8%BF%9C%E8%97%A4%E7%BC%96%EF%BC%89/57219070', '传统技艺', '国家级', NULL, '崇州怀远藤编以青藤手工编织家具与器物，造型别致、结实耐用，融合实用与审美。其藤编技艺列入国家级非物质文化遗产名录，是川西民间手工艺的代表。', 'https://www.bilibili.com/video/BV1R7411d72U/'),
(39, '新繁棕编', 'https://baike.baidu.com/item/%E6%A3%95%E7%BC%96%EF%BC%88%E6%96%B0%E7%B9%81%E6%A3%95%E7%BC%96%EF%BC%89/50994774', '传统技艺', '省级', NULL, '新繁棕编以棕榈叶为原料，编织帽、扇、包与动物造型等，色泽自然、轻巧耐用。其棕编技艺列入省级非物质文化遗产名录，是成都新繁一带的民间绝活。', 'https://www.bilibili.com/video/BV1v8yuBfENN/'),
(40, '成都糖画', 'https://baike.baidu.com/item/%E7%B3%96%E5%A1%91%EF%BC%88%E6%88%90%E9%83%BD%E7%B3%96%E7%94%BB%EF%BC%89/51145087', '传统技艺', '国家级', '樊德然', '成都糖画以热熔饴糖在石板上运腕作画，一气呵成，绘出龙、凤、花鸟等图案，可观可食。其制作技艺列入国家级非物质文化遗产名录，是巴蜀街头脍炙人口的民艺。', 'https://www.bilibili.com/video/BV1Am411z73U/'),
(41, '蒙顶山茶传统制作技艺', 'https://baike.baidu.com/item/%E7%BB%BF%E8%8C%B6%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%88%E8%92%99%E5%B1%B1%E8%8C%B6%E4%BC%A0%E7%BB%9F%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%89/57218398', '传统技艺', '省级', NULL, '蒙顶山茶产于雅安名山，蒙顶甘露、黄芽以独特的杀青、揉捻与烘焙工艺而成，香气清雅、滋味鲜爽，是中国茶文化发源地的重要茶品，技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV17M4m1f7hu/'),
(42, '雅安藏茶制作技艺', 'https://baike.baidu.com/item/%E9%9B%85%E5%AE%89%E8%97%8F%E8%8C%B6/10327244', '传统技艺', '省级', NULL, '雅安藏茶又称边销茶，以粗老茶再经蒸压、渥堆等工艺制成，色泽褐红、汤色红浓、醇厚回甘，自古远销藏区，其制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Ei421D7fR/'),
(43, '苴却砚制作技艺', 'https://baike.baidu.com/item/%E8%8B%B4%E5%8D%B4%E7%A0%9A%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA/22843167', '传统技艺', '省级', NULL, '苴却砚产于攀枝花与永仁一带，以苴却石雕琢而成，石质细腻、色纹斑斓，名贵者有“标青”“鬼脸青”等，是川滇著名的传统名砚，技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV18enezSE6v/'),
(44, '蒲砚制作技艺', 'https://baike.baidu.com/item/%E8%92%B2%E7%A0%9A%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA', '传统技艺', '省级', NULL, '蒲砚产于成都蒲江盐井沟一带，以蒲石雕制，石质坚润、发墨如油，早在宋代便已闻名，与苴却砚同为蜀中名砚，其制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1pw411y7YC/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(45, '宜宾芽菜制作技艺', 'https://baike.baidu.com/item/%E9%85%B1%E8%8F%9C%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%88%E5%AE%9C%E5%AE%BE%E8%8A%BD%E8%8F%9C%E5%88%B6%E4%BD%9C%E6%8A%80%E8%89%BA%EF%BC%89/62180276', '传统技艺', '省级', NULL, '宜宾芽菜以青菜嫩茎腌制发酵而成，色泽黄亮、咸鲜脆嫩、香气独特，是川菜与宜宾燃面的重要调味料，其制作技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Te4y1Q72h/'),
(46, '蜀绣', 'https://baike.baidu.com/item/%E8%9C%80%E7%BB%A3/218', '传统美术', '国家级', '郝淑萍,孟德芝', '蜀绣与苏绣、湘绣、粤绣并称中国四大名绣，以“针法严谨、片线光亮、色彩明快”著称，针法多达百余种，尤擅长表现熊猫、芙蓉鲤鱼，2006年列入首批国家级非遗名录。', 'https://www.bilibili.com/video/BV1xm4y1E7Zy/'),
(47, '羌绣', 'https://baike.baidu.com/item/%E7%BE%8C%E6%97%8F%E5%88%BA%E7%BB%A3/4476985', '传统美术', '国家级', '杨华珍', '羌绣是羌族女性的传统手工刺绣，纹样古朴绚丽、色彩鲜明，以羊角花、四瓣花等图案记录民族记忆，针法多样。其技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV15W9uYoE5q/'),
(48, '绵竹木版年画', 'https://baike.baidu.com/item/%E7%BB%B5%E7%AB%B9%E5%B9%B4%E7%94%BB/3406527', '传统美术', '国家级', '李芳福,胡光葵', '绵竹木版年画是中国四大年画之一，以木板刻印墨线、再手工彩绘而成，讲究“开脸”与手工填色，色彩鲜明、寓意吉祥，2006年列入首批国家级非遗名录。', 'https://www.bilibili.com/video/BV11J4m1J7bk/'),
(49, '夹江年画', 'https://baike.baidu.com/item/%E6%9C%A8%E7%89%88%E5%B9%B4%E7%94%BB%EF%BC%88%E5%A4%B9%E6%B1%9F%E5%B9%B4%E7%94%BB%EF%BC%89/53487837', '传统美术', '省级', NULL, '夹江年画产于乐山夹江，以木版套印与手绘结合而成，采用当地的粉笺纸印刷，色彩明快、线条古拙，是川西南著名的民间年画，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1vuFDzJEYX/'),
(50, '四川剪纸', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E5%89%AA%E7%BA%B8/7319687', '传统美术', '省级', NULL, '四川剪纸流行于川西平原与川南一带，题材多取花卉、鸟兽、戏剧人物与吉庆图案，风格细腻又富有民间旨趣，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Wz42187Zo/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(51, '川剧脸谱绘制技艺', 'https://baike.baidu.com/item/%E5%B7%9D%E5%89%A7%E8%84%B8%E8%B0%B1/68938063', '传统美术', '省级', NULL, '川剧脸谱以红、黑、白、黄、蓝、金等浓烈色彩勾画，红表忠勇、黑表刚直、白表奸诈，色彩本身即是一套叙事语言，其绘制技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV1TW4y197a7/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(52, '成都面塑', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E9%9D%A2%E4%BA%BA/65603205', '传统美术', '省级', NULL, '成都面塑又称“面人”，以糯米面掺色、经揉、捏、搓、压等手法捏成人物、动物与花卉，造型生动、色彩鲜艳，可长期保存，其技艺列入省级非遗名录。', 'https://www.bilibili.com/video/BV1p34y167PK/'),
(53, '宜宾面塑', 'https://baike.baidu.com/item/%E5%AE%9C%E5%AE%BE%E9%9D%A2%E5%A1%91/2850494', '传统美术', '省级', NULL, '宜宾面塑以发酵面粉掺入颜料制成，艺人以手代刀，捏塑出戏剧人物、神话角色与飞禽走兽，形神兼备、色彩明丽，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1dg411G74y/'),
(54, '广安竹丝画帘', 'https://baike.baidu.com/item/%E7%AB%B9%E4%B8%9D%E7%94%BB%E5%B8%98/9854277', '传统美术', '省级', NULL, '广安竹丝画帘以极细竹丝编织成帘，再在上面绘饰山水、花鸟与书法，透光观之清雅别致，兼具实用与观赏价值，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1xg411d7i9/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(55, '遂宁观音绣', 'https://baike.baidu.com/item/%E8%A7%82%E9%9F%B3%E7%BB%A3/10326498', '传统美术', '省级', NULL, '遂宁观音绣源于观音故里的民间刺绣，以细腻的针脚绣制观音、花卉与吉祥图案，色彩柔和、寓意吉祥，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1teCRYnELM/'),
(56, '广元麻柳刺绣', 'https://baike.baidu.com/item/%E6%B0%91%E9%97%B4%E7%BB%A3%E6%B4%BB%EF%BC%88%E9%BA%BB%E6%9F%B3%E5%88%BA%E7%BB%A3%EF%BC%89/53355127', '传统美术', '国家级', NULL, '麻柳刺绣流行于广元朝天一带，为川北民间刺绣代表，以构图饱满、色彩淡雅、针法多变著称，极具乡土气息，其技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1LtUoB3EHT/'),
(57, '嘉绒藏族刺绣', 'https://baike.baidu.com/item/%E8%97%8F%E6%97%8F%E7%BC%96%E7%BB%87%E3%80%81%E6%8C%91%E8%8A%B1%E5%88%BA%E7%BB%A3%E5%B7%A5%E8%89%BA/9972826', '传统美术', '省级', NULL, '嘉绒藏族刺绣流行于川西嘉绒藏区，以吉祥图案与艳丽色彩绣制于头帕、衣饰与围裙之上，兼具实用与装饰，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1RV411z7Dw/'),
(58, '白花石刻', 'https://baike.baidu.com/item/%E7%9F%B3%E9%9B%95%EF%BC%88%E7%99%BD%E8%8A%B1%E7%9F%B3%E5%88%BB%EF%BC%89/53487850', '传统美术', '省级', NULL, '白花石刻产于广元，以白花石雕刻成砚台、笔筒与摆件，石中天然花纹如枝叶花卉，经艺人巧雕更显雅致，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Xx4y1W7F7/'),
(59, '藏族唐卡（四川）', 'https://baike.baidu.com/item/%E8%97%8F%E6%97%8F%E5%94%90%E5%8D%A1%EF%BC%88%E5%99%B6%E7%8E%9B%E5%98%8E%E5%AD%9C%E7%94%BB%E6%B4%BE%EF%BC%89/53247832', '传统美术', '国家级', NULL, '藏族唐卡是藏族以彩缎装裱而成的挂轴画，四川藏区亦有传承，题材多为佛像、本尊与佛教故事，色彩鲜明、绘制精细，其技艺列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1THBsYJEKP/'),
(60, '阆中皮影雕刻技艺', 'https://baike.baidu.com/item/%E9%98%86%E4%B8%AD%E7%9A%AE%E5%BD%B1/1633440', '传统美术', '省级', NULL, '阆中皮影以牛皮雕刻、镂空着色制成影人，造型取川剧程式、雕刻精细，是皮影戏表演的重要依托，其雕刻技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1os411E7HW/'),
(61, '川剧', 'https://baike.baidu.com/item/%E5%B7%9D%E5%89%A7/294200', '传统戏剧', '国家级', '沈铁梅,陈巧茹', '川剧是巴蜀最具代表性的地方戏曲，融合昆、高、胡、弹、灯五大声腔，以变脸、帮腔等绝技闻名。2006年列入首批国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Kq4y1A7qc/'),
(62, '川剧变脸', 'https://baike.baidu.com/item/%E5%B7%9D%E5%89%A7%E5%8F%98%E8%84%B8/63484', '传统戏剧', '省级', '彭登怀', '川剧变脸是川剧绝技，演员在舞台上以抹脸、吹脸、扯脸等手法瞬息变换脸谱，神秘莫测、叹为观止，被誉为“东方魔术”，是川剧最具辨识度的符号。', 'https://www.bilibili.com/video/BV1VokrByEzz/'),
(63, '川剧吐火', 'https://baike.baidu.com/item/%E5%90%90%E7%81%AB', '传统戏剧', '省级', NULL, '川剧吐火是川剧中的神奇绝技，演员口含燃油喷吐火焰，火光升腾、惊心动魄，多用于表现神怪或情绪激昂的情境，常与变脸、藏刀等同台呈现。', 'https://www.bilibili.com/video/BV18V4y1Z7hx/'),
(64, '川北大木偶戏', 'https://baike.baidu.com/item/%E6%9C%A8%E5%81%B6%E6%88%8F%EF%BC%88%E5%B7%9D%E5%8C%97%E5%A4%A7%E6%9C%A8%E5%81%B6%E6%88%8F%EF%BC%89/52957161', '传统戏剧', '国家级', NULL, '川北大木偶戏流行于南充，以形体高大的杖头木偶表演，双人操纵、动作细腻传神，能演吐火、变脸等绝技，2006年列入首批国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1mp6PBsEjv/'),
(65, '成都皮影戏', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E7%9A%AE%E5%BD%B1%E6%88%8F/5091961', '传统戏剧', '国家级', NULL, '成都皮影戏又称灯影戏，以兽皮雕成人物、借灯光映于幕布上表演，唱腔取川剧曲调，剧目丰富、一人可扮多角，2008年列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Zb4y1H72S/'),
(66, '川北灯戏', 'https://baike.baidu.com/item/%E7%81%AF%E6%88%8F%EF%BC%88%E5%B7%9D%E5%8C%97%E7%81%AF%E6%88%8F%EF%BC%89/53186175', '传统戏剧', '国家级', NULL, '川北灯戏流行于川北一带，源于民间灯会与庆坛活动，以诙谐的方言、载歌载舞的形式演生活小事，滑稽生动、乡土气息浓，2006年列入国家级非遗名录。', 'https://www.bilibili.com/video/BV1Nc411o7HQ/'),
(67, '四川傩戏', 'https://baike.baidu.com/item/%E5%82%A9%E6%88%8F/828672', '传统戏剧', '省级', NULL, '四川傩戏源于古代傩祭，演员头戴傩面、驱邪逐疫，融仪式、舞蹈与戏曲于一体，保留着原始而神秘的民俗气息，其技艺列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1eLcPzQEZj/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(68, '芦山花灯', 'https://baike.baidu.com/item/%E8%8A%A6%E5%B1%B1%E8%8A%B1%E7%81%AF/67191821', '传统戏剧', '国家级', NULL, '芦山花灯流行于雅安芦山，以“旦靠丑”的表演形式与欢快的花灯调载歌载舞，语言幽默、生活气息浓，2008年列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1CY4y1A7F6/?vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(69, '四川清音', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E6%B8%85%E9%9F%B3/1125487', '传统戏剧', '国家级', NULL, '四川清音是流行于巴蜀的说唱艺术，以琵琶、月琴等伴奏，唱腔清亮婉转、长于抒情叙事，2008年列入国家级非物质文化遗产名录，是四川曲艺的代表。', 'https://www.bilibili.com/video/BV1zU4y137nD/'),
(70, '四川扬琴', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E6%89%AC%E7%90%B4/1969799', '传统戏剧', '国家级', NULL, '四川扬琴又称琴书，由五人围坐、分持扬琴、碗碗琴、三弦、琵琶与鼓板并兼唱，坐唱抒情、声情并茂，2008年列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1Vu411W7sf/'),
(71, '四川金钱板', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E9%87%91%E9%92%B1%E6%9D%BF/4591064', '传统戏剧', '国家级', NULL, '四川金钱板以三块竹板（一说铜钱板）击节伴奏，一人又说又唱，语言幽默、叙事生动，长于表现民间故事与市井生活，列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1rp4y1Y7v7/'),
(72, '四川竹琴', 'https://baike.baidu.com/item/%E5%9B%9B%E5%B7%9D%E7%AB%B9%E7%90%B4/1969656', '传统戏剧', '国家级', NULL, '四川竹琴又称道情，以竹筒与竹片击节伴奏，说唱相间、一唱众和，唱腔古朴悠长，多叙历史故事与民间传奇，列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1BB4y1T7QB/'),
(73, '泸州雨坛彩龙', 'https://baike.baidu.com/item/%E9%BE%99%E8%88%9E%EF%BC%88%E6%B3%B8%E5%B7%9E%E9%9B%A8%E5%9D%9B%E5%BD%A9%E9%BE%99%EF%BC%89/51151904', '民俗', '国家级', NULL, '泸州雨坛彩龙是流行于泸县雨坛一带的民间龙舞，以舞龙求雨祈丰收，龙身灵动、套路丰富、气势磅礴，2006年列入首批国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1KD4y1A754/'),
(74, '黄龙溪火龙灯舞', 'https://baike.baidu.com/item/%E9%BE%99%E8%88%9E%EF%BC%88%E9%BB%84%E9%BE%99%E6%BA%AA%E7%81%AB%E9%BE%99%E7%81%AF%E8%88%9E%EF%BC%89/52554338', '民俗', '国家级', NULL, '黄龙溪火龙灯舞流行于成都双流黄龙溪，舞龙者在烟花焰火中赤脚舞龙，火龙腾跃、火花四溅，惊险壮观，2008年列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1tb411b7Ng/'),
(75, '洛带客家水龙节', 'https://baike.baidu.com/item/%E6%B0%B4%E9%BE%99%E8%8A%82/3212621', '民俗', '省级', NULL, '洛带客家水龙节是成都龙泉驿洛带客家人的传统民俗，以泼水舞龙祈求风调雨顺，龙舞翻腾、水花四溅，热闹非凡，其习俗列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1fB4y1B7By/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(76, '广汉保保节', 'https://baike.baidu.com/item/%E4%BF%9D%E4%BF%9D%E8%8A%82/625426', '民俗', '省级', NULL, '广汉保保节于每年正月十六举行，民众到房湖公园为孩子“拉保保”（认干爹），求吉保安、人山人海，是川西独特的民间习俗，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1UzKHe7EpT/'),
(77, '达州元九登高', 'https://baike.baidu.com/item/%E5%85%83%E4%B9%9D%E7%99%BB%E9%AB%98%E8%8A%82/244088', '民俗', '省级', NULL, '达州元九登高是每年正月初九民众登高望远的传统习俗，相传与唐代诗人元稹有关，登高者扶老携幼、人潮如织，寓意新年步步高升，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1KM8MevEp6/'),
(78, '彝族火把节', 'https://baike.baidu.com/item/%E7%81%AB%E6%8A%8A%E8%8A%82%EF%BC%88%E5%BD%9D%E6%97%8F%E7%81%AB%E6%8A%8A%E8%8A%82%EF%BC%89/49849756', '民俗', '国家级', NULL, '火把节是彝族最盛大的传统节日，农历六月二十四前后举行，人们点燃火把、围绕篝火歌舞，斗牛赛马、选美对歌，是凉山彝族文化的集中展现，列入国家级非遗名录。', 'https://www.bilibili.com/video/BV1LmX6YmEfB/'),
(79, '羌年', 'https://baike.baidu.com/item/%E7%BE%8C%E5%B9%B4/8559959', '民俗', '国家级', NULL, '羌年（羌历年）是羌族最隆重的传统节日，农历十月初一前后举行，祭山祭祖、歌舞饮咂酒，是羌族文化信仰的集中展现，已列入人类非遗与国家级非遗名录。', 'https://www.bilibili.com/video/BV1vy4y187r8/'),
(80, '都江堰放水节', 'https://baike.baidu.com/item/%E9%83%BD%E6%B1%9F%E5%A0%B0%E6%94%BE%E6%B0%B4%E8%8A%82/10781269', '民俗', '国家级', NULL, '都江堰放水节每年清明举行，以古法砍栈揭堰、放水春灌，纪念李冰治水，祈求风调雨顺，场面宏大、仪典隆重，2006年列入首批国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV11t411e7VB/'),
(81, '自贡灯会', 'https://baike.baidu.com/item/%E7%81%AF%E4%BC%9A%EF%BC%88%E8%87%AA%E8%B4%A1%E7%81%AF%E4%BC%9A%EF%BC%89/50880959', '民俗', '国家级', NULL, '自贡灯会始于唐宋、盛于当代，以巨型彩灯、瓷灯与变光技术闻名，被誉为“天下第一灯”，每年春节前后举办，吸引八方游客，列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1WHWDeNEPV/'),
(82, '成都灯会', 'https://baike.baidu.com/item/%E7%81%AF%E4%BC%9A%EF%BC%88%E8%87%AA%E8%B4%A1%E7%81%AF%E4%BC%9A%EF%BC%89/50880959', '民俗', '省级', NULL, '成都灯会是每年正月在成都举办的赏灯传统，于青羊宫、文化公园一带张灯结彩，各式组灯五彩斑斓，与花会相映成趣，是成都市井年俗的代表，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1r4zDB5Edz/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(83, '成都花会', 'https://baike.baidu.com/item/%E6%88%90%E9%83%BD%E7%81%AF%E4%BC%9A/2752467', '民俗', '省级', NULL, '成都花会又称青羊宫花会，源于唐宋，每年春季赏花、看戏、品美食，尽显“花重锦官城”的风貌，是成都历史悠久的传统民俗盛会，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1USd6BiEka/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(84, '峨眉山朝山会', 'https://baike.baidu.com/item/%E6%9C%9D%E5%B1%B1%E4%BC%9A/13725', '民俗', '省级', NULL, '峨眉山朝山会是信众们朝礼峨眉金顶的盛大民间集会，每年举行，香客云集、击磬诵经、绕山祈福，既是宗教活动也是民俗盛事，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1JKbp6zEtN/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(85, '二王庙庙会', 'https://baike.baidu.com/item/%E9%83%BD%E6%B1%9F%E5%A0%B0%E4%BA%8C%E7%8E%8B%E5%BA%99%E5%BA%99%E4%BC%9A/22994014?fromtitle=%E4%BA%8C%E7%8E%8B%E5%BA%99%E5%BA%99%E4%BC%9A&fromid=2755928', '民俗', '省级', NULL, '二王庙庙会在都江堰二王庙举行，民众祭祀李冰父子、祈求水利安澜与五谷丰登，庙会期间戏曲杂耍、香火鼎盛，是川西著名的民俗庙会，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1Tau2znEeg/'),
(86, '成都大庙会', 'https://baike.baidu.com/item/%E6%AD%A6%E4%BE%AF%E7%A5%A0%E6%88%90%E9%83%BD%E5%A4%A7%E5%BA%99%E4%BC%9A/55217306', '民俗', '省级', NULL, '成都大庙会于每年春节期间在武侯祠一带举行，以三国文化为主题，集灯组、戏曲、民俗展演与美食于一体，游人如织、年味浓郁，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1GQxceEEse/'),
(87, '羌族瓦尔俄足节', 'https://baike.baidu.com/item/%E7%BE%8C%E6%97%8F%E7%93%A6%E5%B0%94%E4%BF%84%E8%B6%B3%E8%8A%82/3436798', '民俗', '国家级', NULL, '瓦尔俄足节是羌族妇女的传统节日，又称“歌仙节”，于农历五月初五举行，妇女们唱歌跳舞、祭祀萨朗女神，展现羌族女性的风采，列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV14ApSeeEtm/'),
(88, '羌族转山会', 'https://baike.baidu.com/item/%E8%BD%AC%E5%B1%B1%E4%BC%9A/3497869', '民俗', '省级', NULL, '羌族转山会是羌人于特定时节转山祈福、祭拜山神的活动，人们身着盛装、沿途诵经歌舞，祈求人畜兴旺、风调雨顺，是羌族自然崇拜的体现，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1dC411j7LP/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(89, '嘉绒藏族若木纽节', 'https://baike.baidu.com/item/%E8%8B%A5%E6%9C%A8%E7%BA%BD%E8%8A%82/3804103', '民俗', '省级', NULL, '若木纽节是嘉绒藏族的传统节日，人们节日里围坐欢歌、赛马竞技、备青稞酒待客，祈求丰收吉祥，体现着嘉绒藏族独特的风俗与信仰，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1DWUjBDENE/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(90, '白马藏人跳曹盖', 'https://baike.baidu.com/item/%E8%B7%B3%E6%9B%B9%E7%9B%96/7024216', '民俗', '国家级', NULL, '跳曹盖是平武白马藏人的传统祭祀舞蹈，舞者头戴面具、身着彩服，于正月间跳神驱邪、祈福纳吉，风格粗犷神秘，列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1U64y1W7xh/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(91, '藏族藏历年', 'https://baike.baidu.com/item/%E8%97%8F%E5%8E%86%E5%B9%B4/921454', '民俗', '省级', NULL, '藏历年是四川藏区藏族群众最重要的传统节日，届时煨桑祈福、互献哈达、跳锅庄、赛马，家家团圆、喜气洋洋，其习俗列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV13W411872x/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(92, '泸沽湖摩梭转山节', 'https://baike.baidu.com/item/%E6%91%A9%E6%A2%AD%E4%BA%BA%E8%BD%AC%E5%B1%B1%E8%8A%82/53241720', '民俗', '省级', NULL, '摩梭转山节是泸沽湖摩梭人的传统节日，人们于农历七月二十五围着格姆女神山游玩、歌舞祈福，尽显摩梭母系文化与自然崇拜，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1aF411r7on/'),
(93, '宜宾苗族花山节', 'https://baike.baidu.com/item/%E8%8A%B1%E5%B1%B1%E8%8A%82/5442927', '民俗', '省级', NULL, '花山节是川南苗族的传统盛大节日，人们身着盛装赴花山场对歌、跳芦笙舞、赛马斗牛，青年男女借此寻偶交谊，热闹非凡，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV128GbzBEJh/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(94, '阆中正月十六游百病', 'https://www.toutiao.com/article/7611341286242632230/?wid=1789820004760', '民俗', '省级', NULL, '“游百病”是阆中春节民俗，于正月十六日民众出城登山踏青、走桥游玩，寓意祛病消灾、健康平安，参与人数众多，是阆中古城独特的年俗，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1yd4y1n7xe/'),
(95, '天彭牡丹花会', 'https://baike.baidu.com/item/%E5%A4%A9%E5%BD%AD%E7%89%A1%E4%B8%B9%E8%8A%B1%E4%BC%9A', '民俗', '省级', NULL, '天彭牡丹花会源于彭州，唐宋时即盛行，每年春季牡丹盛开、游人如织，赏花、品茶、看戏，尽显天彭牡丹“蜀中第一”的风采，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1opwzzoEiE/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(96, '郫县望丛赛歌会', 'https://baike.baidu.com/item/%E9%83%AB%E5%8E%BF%E6%9C%9B%E4%B8%9B%E8%B5%9B%E6%AD%8C%E4%BC%9A/60155954', '民俗', '省级', NULL, '望丛赛歌会在成都郫都区望丛祠举行，民众以歌会友、对唱山歌，纪念古蜀望帝与丛帝，歌声悠扬、乡土气息浓，是川西平原独特的歌会，列入省级非遗名录。', 'https://www.bilibili.com/video/BV1MMw1zaEDo/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(97, '绵竹年画节', 'https://baike.baidu.com/item/%E7%BB%B5%E7%AB%B9%E5%B9%B4%E7%94%BB/3406527', '民俗', '省级', NULL, '绵竹年画节于每年春节前后举办，以绵竹年画为主题，开展年画展览、民俗巡游与手工体验，让“过年贴年画”的传统得以延续，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1g2421A7dH/'),
(98, '广元女儿节', 'https://baike.baidu.com/item/%E4%B8%AD%E5%9B%BD%C2%B7%E5%B9%BF%E5%85%83%E5%9B%BD%E9%99%85%E5%A5%B3%E5%84%BF%E8%8A%82/2603817', '民俗', '省级', NULL, '广元女儿节于每年九月举行，相传起源于纪念武则天的传统习俗，节日里划凤舟、比才艺、游景区，展现出独特的女性文化，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1yUHnejE2W/'),
(99, '自贡盐场会节', 'https://baike.baidu.com/item/%E7%9B%90%E9%83%BD%E4%BC%9A%E8%8A%82/63546115', '民俗', '省级', NULL, '自贡盐场会节源于盐业行帮与庙会传统，节庆时祭拜盐神、搭台唱戏、商贸集会，融合工商、信仰与民俗，见证了盐都的繁荣，列入省级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV16N411f7VZ/?spm_id_from=333.337.search-card.all.click&vd_source=6cb77c5657e7125c98a7a11b307a514c'),
(100, '巴中翻山铰子', 'https://baike.baidu.com/item/%E7%BF%BB%E5%B1%B1%E9%93%B0%E5%AD%90/2754839', '民俗', '国家级', NULL, '翻山铰子是流行于巴中一带的民间舞蹈，舞者甩动铰子（小钢碟）边舞边击，动作豪放、节奏明快，常在节日与婚庆中表演，列入国家级非物质文化遗产名录。', 'https://www.bilibili.com/video/BV1cN411t7QB/')
